INSERT INTO public.config_schema VALUES ('threshold.vwap_reversion.sigma_min', 'float', '1.5', 0.5, 5, NULL, false, 1, '[conventional] Min |session_vwap_deviation_sigma| to qualify as a departure from VWAP. 1.5 = ~87th percentile. ML learning target.', '2026-06-14 23:35:45.06439+00');
INSERT INTO public.config_schema VALUES ('threshold.vwap_reversion.hurst_max', 'float', '0.55', 0.3, 0.7, NULL, false, 1, '[conventional] Max Hurst exponent to confirm mean-reverting regime for AnchoredVWAPReversionPlugin. ML learning target.', '2026-06-14 23:35:45.06439+00');
INSERT INTO public.config_schema VALUES ('threshold.cis.fire_threshold', 'float', '0.35', 0, 1, NULL, false, 1, '[initial_estimate] Min filtered_cis score for the CIS dual gate to allow a signal to fire. Kalman-smoothed CIS must exceed this value. ML learning target.', '2026-06-15 08:44:51.918459+00');
INSERT INTO public.config_schema VALUES ('threshold.cis.bucket_agree_min', 'int', '3', 1, 6, NULL, false, 1, '[initial_estimate] Min number of CIS buckets that must contribute a non-zero score before signal fires. Prevents thin-bucket noise signals. ML learning target.', '2026-06-15 08:44:51.918459+00');
INSERT INTO public.config_schema VALUES ('threshold.cis.bucket_noise_floor', 'float', '0.1', 0, 1, NULL, false, 1, '[initial_estimate] Min per-bucket score to count as a contributing bucket in the bucket_agree_min gate. Scores below this are treated as zero. ML learning target.', '2026-06-15 08:44:51.918459+00');
INSERT INTO public.config_schema VALUES ('feature.zone_engine.min_zone_width_atr', 'float', '1.5', 0, 10, NULL, false, 1, '[rca_analysis] Default min zone width in ATR multiples across all asset classes. Phase 126 zone entry width gate. Noise-band analysis. Not a learning target until Phase 126 consumption code ships.', '2026-06-15 08:44:51.918459+00');
INSERT INTO public.config_schema VALUES ('feature.zone_engine.min_zone_width_atr.equity_etf', 'float', '1.5', 0, 10, NULL, false, 1, '[rca_analysis] Phase 126 zone entry width gate for equity ETF instruments. Noise-band analysis. Not a learning target until Phase 126 consumption code ships.', '2026-06-15 08:44:51.918459+00');
INSERT INTO public.config_schema VALUES ('feature.zone_engine.min_zone_width_atr.forex', 'float', '1.0', 0, 10, NULL, false, 1, '[rca_analysis] Phase 126 zone entry width gate for forex instruments. Tighter spread; calibrated lower than futures/equity. Not a learning target until Phase 126 consumption code ships.', '2026-06-15 08:44:51.918459+00');
INSERT INTO public.config_schema VALUES ('feature.zone_engine.min_zone_width_atr.futures', 'float', '1.5', 0, 10, NULL, false, 1, '[rca_analysis] Phase 126 zone entry width gate for futures instruments. Noise-band analysis. Not a learning target until Phase 126 consumption code ships.', '2026-06-15 08:44:51.918459+00');
INSERT INTO public.config_schema VALUES ('weights.vwap_reversion.sigma_magnitude', 'float', '0.40', 0, 1, NULL, false, 1, '[initial_estimate] sigma_magnitude factor weight in AnchoredVWAPReversionPlugin confidence calculation. ML learning target.', '2026-06-15 08:44:51.918459+00');
INSERT INTO public.config_schema VALUES ('weights.vwap_reversion.hurst_quality', 'float', '0.35', 0, 1, NULL, false, 1, '[initial_estimate] hurst_quality factor weight in AnchoredVWAPReversionPlugin confidence calculation. ML learning target.', '2026-06-15 08:44:51.918459+00');
INSERT INTO public.config_schema VALUES ('weights.vwap_reversion.vol_stability', 'float', '0.25', 0, 1, NULL, false, 1, '[initial_estimate] vol_stability factor weight in AnchoredVWAPReversionPlugin confidence calculation. ML learning target.', '2026-06-15 08:44:51.918459+00');
INSERT INTO public.config_schema VALUES ('feature.zone_engine.min_zone_width_atr.equity', 'float', '1.5', 0.1, 10, NULL, false, 1, '[initial_estimate — noise band analysis: zone_width + buffer (0.25xATR) >= 2.0xATR -> zone_width >= 1.75xATR; rounded to 1.5. ML learning target post Phase 127 replay.] Equity asset class override for min_zone_width_atr.', '2026-06-15 08:54:45.143571+00');
INSERT INTO public.config_schema VALUES ('feature.zone_engine.min_zone_width_atr.fx', 'float', '1.0', 0.1, 10, NULL, false, 1, '[initial_estimate — noise band analysis: forex zones structurally larger relative to ATR (EURUSD/USDCHF p50 ~1.41-1.43x). Threshold set at 1.0 to pass structurally meaningful forex zones. ML learning target post Phase 127 replay.] FX asset class override for min_zone_width_atr.', '2026-06-15 08:54:45.143571+00');
INSERT INTO public.config_schema VALUES ('feature.zone_engine.min_stop_distance_atr', 'float', '0.5', 0.05, 5, NULL, false, 1, '[initial_estimate] Absolute floor on stop distance from entry as ATR multiple. Independent of MIN_STOP_ATR_MULTIPLIER — ML may tune that parameter but cannot breach this floor without an operator override.', '2026-06-15 08:54:45.143571+00');
INSERT INTO public.config_schema VALUES ('feature.zone_engine.min_stop_distance_atr.equity', 'float', '0.5', 0.05, 5, NULL, false, 1, '[initial_estimate] Absolute floor on stop distance from entry as ATR multiple. Independent of MIN_STOP_ATR_MULTIPLIER — ML may tune that parameter but cannot breach this floor without an operator override. Equity asset class override.', '2026-06-15 08:54:45.143571+00');
INSERT INTO public.config_schema VALUES ('feature.zone_engine.min_stop_distance_atr.fx', 'float', '0.3', 0.05, 5, NULL, false, 1, '[initial_estimate] Absolute floor on stop distance from entry as ATR multiple. Independent of MIN_STOP_ATR_MULTIPLIER — ML may tune that parameter but cannot breach this floor without an operator override. FX asset class override; lower due to structurally tighter forex spreads.', '2026-06-15 08:54:45.143571+00');
INSERT INTO public.config_schema VALUES ('feature.zone_engine.min_stop_distance_atr.futures', 'float', '0.4', 0.05, 5, NULL, false, 1, '[initial_estimate] Absolute floor on stop distance from entry as ATR multiple. Independent of MIN_STOP_ATR_MULTIPLIER — ML may tune that parameter but cannot breach this floor without an operator override. Futures asset class override.', '2026-06-15 08:54:45.143571+00');
INSERT INTO public.config_schema VALUES ('threshold.mean_reversion.trend_regime_max', 'float', '0.2', 0, 1, NULL, false, 1, '[rca_analysis] Max abs(trend_regime) for MeanReversionPlugin Gate A. Relaxed from 0.4 to 0.2 in Phase 126 after dual-gate mutual-exclusion diagnosis (both_gates_ok/total_bars = 0.005% at threshold=0.4). Plugin parked shadow_only=True; redesign needed to reconcile Gate A (ranging) vs Gate B (kalman displacement). ML learning target.', '2026-06-15 09:03:04.808816+00');
INSERT INTO public.config_schema VALUES ('threshold.signal_audit.ic_validated_floor', 'float', '0.02', -1, 1, NULL, false, 1, '[conventional — Pearson IC > 0.02 is the standard predictive power threshold for financial ML. ML learning target post Phase 127 replay.] Minimum IC for a plugin to be classified VALIDATED. Plugins above this threshold and with hit_rate CI lower > hit_rate_validated_floor are considered statistically predictive.', '2026-06-15 13:54:45.132589+00');
INSERT INTO public.config_schema VALUES ('threshold.signal_audit.ic_anti_signal_ceiling', 'float', '-0.02', -1, 1, NULL, false, 1, '[conventional — symmetric lower bound to ic_validated_floor. ML learning target post Phase 127 replay.] Maximum IC for a plugin to be classified ANTI-SIGNAL. Plugins below this threshold are negatively predictive and get shadow_only=True pending redesign.', '2026-06-15 13:54:45.132589+00');
INSERT INTO public.config_schema VALUES ('threshold.signal_audit.hit_rate_validated_floor', 'float', '0.45', 0, 1, NULL, false, 1, '[conventional — >45% hit rate CI lower ensures the 95% CI lower bound is above the noise floor. ML learning target post Phase 127 replay.] Minimum bootstrap 95% CI lower bound on hit_rate for VALIDATED classification. Ensures statistical confidence the plugin is above random.', '2026-06-15 13:54:45.132589+00');
INSERT INTO public.config_schema VALUES ('threshold.signal_audit.hit_rate_anti_signal_ceiling', 'float', '0.45', 0, 1, NULL, false, 1, '[conventional — symmetric with hit_rate_validated_floor. ML learning target post Phase 127 replay.] Maximum bootstrap 95% CI upper bound on hit_rate for ANTI-SIGNAL classification. A CI upper bound below 0.45 means even the optimistic estimate is below the noise floor.', '2026-06-15 13:54:45.132589+00');
INSERT INTO public.config_schema VALUES ('threshold.signal_audit.verifiable_population_floor', 'float', '0.90', 0, 1, NULL, false, 1, '[initial_estimate] Minimum fraction of sampled signals with required detection-condition fields populated for VERIFIABLE verdict. Below this threshold: PARTIAL (>=0.50) or UNVERIFIABLE (<0.50).', '2026-06-15 13:54:45.132589+00');
INSERT INTO public.config_schema VALUES ('threshold.signal_audit.partial_population_floor', 'float', '0.50', 0, 1, NULL, false, 1, '[initial_estimate] Minimum fraction for PARTIAL verdict. Below this: UNVERIFIABLE - plugin fires on stale or absent feature data.', '2026-06-15 13:54:45.132589+00');
INSERT INTO public.config_schema VALUES ('threshold.lvn_breakout.vol_threshold', 'float', '1.5', 0.5, 5, NULL, false, 1, '[conventional] Minimum volume expansion multiple (rel_volume or bar/avg ratio) required for LVN breakout gate. 1.5x is industry-standard volume expansion threshold. ML learning target post Phase 127 replay.', '2026-06-15 14:31:41.034405+00');
INSERT INTO public.config_schema VALUES ('weights.lvn_breakout.vol', 'float', '0.30', 0, 1, NULL, false, 1, '[initial_estimate] LVN breakout confidence weight: volume ratio factor. ML learning target.', '2026-06-15 14:31:41.034405+00');
INSERT INTO public.config_schema VALUES ('weights.lvn_breakout.trend_clarity', 'float', '0.25', 0, 1, NULL, false, 1, '[initial_estimate] LVN breakout confidence weight: HMM trend clarity (hmm_probability). ML learning target.', '2026-06-15 14:31:41.034405+00');
INSERT INTO public.config_schema VALUES ('weights.lvn_breakout.lvn_inverse', 'float', '0.25', 0, 1, NULL, false, 1, '[initial_estimate] LVN breakout confidence weight: LVN inverse width (thinner node = faster move). ML learning target.', '2026-06-15 14:31:41.034405+00');
INSERT INTO public.config_schema VALUES ('weights.lvn_breakout.close_strength', 'float', '0.20', 0, 1, NULL, false, 1, '[initial_estimate] LVN breakout confidence weight: bar close strength within range. ML learning target.', '2026-06-15 14:31:41.034405+00');
INSERT INTO public.config_schema VALUES ('threshold.ofi_divergence.min_divergence_sigma', 'float', '1.5', 0.5, 5, NULL, false, 1, '[conventional] Minimum absolute ofi_divergence z-score to pass detection gate. 1.5σ is statistically meaningful divergence (peer: dual_divergence thresholds at 1.0-1.5σ). ML learning target post Phase 127 replay.', '2026-06-15 14:31:41.034405+00');
INSERT INTO public.config_schema VALUES ('weights.ofi_divergence.magnitude', 'float', '0.40', 0, 1, NULL, false, 1, '[initial_estimate] OFI divergence confidence weight: peak divergence magnitude. ML learning target.', '2026-06-15 14:31:41.034405+00');
INSERT INTO public.config_schema VALUES ('weights.ofi_divergence.alignment', 'float', '0.25', 0, 1, NULL, false, 1, '[initial_estimate] OFI divergence confidence weight: EWMA5/EWMA20 directional alignment. ML learning target.', '2026-06-15 14:31:41.034405+00');
INSERT INTO public.config_schema VALUES ('weights.ofi_divergence.persistence', 'float', '0.20', 0, 1, NULL, false, 1, '[initial_estimate] OFI divergence confidence weight: persistence bars beyond minimum. ML learning target.', '2026-06-15 14:31:41.034405+00');
INSERT INTO public.config_schema VALUES ('weights.ofi_divergence.volume', 'float', '0.15', 0, 1, NULL, false, 1, '[initial_estimate] OFI divergence confidence weight: relative volume confirmation. ML learning target.', '2026-06-15 14:31:41.034405+00');
INSERT INTO public.config_schema VALUES ('threshold.failed_breakout.max_reversal_bars', 'int', '3', 1, 10, NULL, false, 1, '[conventional] Maximum bars after BOS detection to wait for a close-back-through reversal. 3 bars reflects tight reversal window — longer windows increase noise. ML learning target post Phase 127 replay.', '2026-06-15 14:31:41.034405+00');
INSERT INTO public.config_schema VALUES ('weights.failed_breakout.break_magnitude', 'float', '0.35', 0, 1, NULL, false, 1, '[initial_estimate] Failed breakout confidence weight: reversal close delta vs ATR. ML learning target.', '2026-06-15 14:31:41.034405+00');
INSERT INTO public.config_schema VALUES ('weights.failed_breakout.rejection_strength', 'float', '0.30', 0, 1, NULL, false, 1, '[initial_estimate] Failed breakout confidence weight: speed of reversal (sooner = stronger). ML learning target.', '2026-06-15 14:31:41.034405+00');
INSERT INTO public.config_schema VALUES ('weights.failed_breakout.volume', 'float', '0.20', 0, 1, NULL, false, 1, '[initial_estimate] Failed breakout confidence weight: relative volume confirmation. ML learning target.', '2026-06-15 14:31:41.034405+00');
INSERT INTO public.config_schema VALUES ('weights.failed_breakout.structure_quality', 'float', '0.15', 0, 1, NULL, false, 1, '[initial_estimate] Failed breakout confidence weight: BOS structural quality (bos_confidence). ML learning target.', '2026-06-15 14:31:41.034405+00');
INSERT INTO public.config_schema VALUES ('threshold.global.conf_ceil', 'float', '0.95', 0.5, 1, NULL, false, 1, '[conventional] Maximum allowed raw confidence for any I7 signal before compose_confidence() clamp. 0.95 preserves discrimination at the top; hard ceiling prevents over-confidence. Operator preference; not ML learning target.', '2026-06-16 04:03:30.039122+00');
INSERT INTO public.config_schema VALUES ('threshold.microstructure.spike_z', 'float', '2.0', 0.5, 5, NULL, false, 1, '[conventional] Minimum abs z-score to classify a microstructure bar as a spike (OFISpike, CVDSpike). 2.0σ is the standard statistical outlier threshold. ML learning target post Phase 127 replay.', '2026-06-16 04:03:30.039122+00');
INSERT INTO public.config_schema VALUES ('feature.state.dedup_min_bars', 'int', '20', 1, 100, NULL, false, 1, '[conventional] Minimum active-condition bars between re-fires of the same event_id in deduplicate_event(). 20 bars (~20 minutes on 1m) prevents rapid re-fire on persistent upstream events. ML learning target.', '2026-06-16 04:03:30.039122+00');
INSERT INTO public.config_schema VALUES ('threshold.delta_exhaustion.spike_z', 'float', '1.5', 0.5, 5, NULL, false, 1, '[conventional] Minimum abs(cvd_spike_z) to enter DeltaExhaustion detection. 1.5σ is lower than OFI/CVD spike (2.0σ) — exhaustion fires on weaker spikes since price failure is the confirming gate. ML learning target post Phase 127 replay.', '2026-06-16 04:03:30.039122+00');
INSERT INTO public.config_schema VALUES ('threshold.delta_exhaustion.price_follow_atr', 'float', '0.3', 0.05, 2, NULL, false, 1, '[conventional] Maximum abs(price_change)/ATR for price to be classified as "failed to follow" CVD spike. 0.3 ATR = weak follow-through; above this threshold the spike is price-confirmed (not exhausted). ML learning target post Phase 127 replay.', '2026-06-16 04:03:30.039122+00');
INSERT INTO public.config_schema VALUES ('weights.delta_exhaustion.cvd_z', 'float', '0.35', 0, 1, NULL, false, 1, '[initial_estimate] DeltaExhaustion confidence weight: CVD spike magnitude above threshold. ML learning target.', '2026-06-16 04:03:30.039122+00');
INSERT INTO public.config_schema VALUES ('weights.delta_exhaustion.price_fail', 'float', '0.30', 0, 1, NULL, false, 1, '[initial_estimate] DeltaExhaustion confidence weight: price failure score (1.0 = zero follow-through). ML learning target.', '2026-06-16 04:03:30.039122+00');
INSERT INTO public.config_schema VALUES ('weights.delta_exhaustion.hmm_ranging', 'float', '0.25', 0, 1, NULL, false, 1, '[initial_estimate] DeltaExhaustion confidence weight: HMM ranging regime alignment magnitude. ML learning target.', '2026-06-16 04:03:30.039122+00');
INSERT INTO public.config_schema VALUES ('weights.delta_exhaustion.persistence', 'float', '0.10', 0, 1, NULL, false, 1, '[initial_estimate] DeltaExhaustion confidence weight: CVD spike persistence proxy. ML learning target.', '2026-06-16 04:03:30.039122+00');
INSERT INTO public.config_schema VALUES ('feature.cvd_divergence.confirmation_bars', 'int', '5', 1, 20, NULL, false, 1, '[rca_analysis] Consecutive bars of CVD-vs-price divergence required before CVDDivergence fires. 5 bars chosen from 90d replay analysis (n=227836 firings); balances persistence signal vs latency. ML learning target post Phase 127 replay.', '2026-06-16 04:03:30.039122+00');
INSERT INTO public.config_schema VALUES ('threshold.cvd_divergence.div_threshold', 'float', '1.0', 0, 3, NULL, false, 1, '[rca_analysis] Minimum abs(cvd_divergence) to pass detection gate. 1.0 = p75 of abs distribution (90d, n=227836); filters zero-divergence noise while keeping top quartile. ML learning target.', '2026-06-16 04:03:30.039122+00');
INSERT INTO public.config_schema VALUES ('feature.cvd_divergence.div_upper_ref', 'float', '2.0', 1, 5, NULL, false, 1, '[rca_analysis] Upper reference for CVD divergence confidence normalization. 2.0 = p90 of abs distribution (90d, n=227836); maps full divergence (slope_dir opposite price_dir) to 1.0 confidence factor. Not a gate; normalization constant. Not a primary ML target.', '2026-06-16 04:03:30.039122+00');
INSERT INTO public.config_schema VALUES ('threshold.cvd_divergence.ofi_dual_threshold', 'float', '1.0', 0, 3, NULL, false, 1, '[conventional] Minimum abs(ofi_divergence) required to flag dual_divergence=True on a CVDDivergence signal. 1.0 matches div_threshold — both measures must be at the same significance level for dual confirmation. Operator preference; not ML target.', '2026-06-16 04:03:30.039122+00');
INSERT INTO public.config_schema VALUES ('feature.dual_divergence.confirmation_bars', 'int', '3', 1, 10, NULL, false, 1, '[conventional] Consecutive bars of simultaneous OFI+CVD divergence required before DualDivergence fires. 3 bars (tighter than CVDDivergence 5-bar) reflects the higher intrinsic signal quality of dual confirmation. ML learning target post Phase 127 replay.', '2026-06-16 04:03:30.039122+00');
INSERT INTO public.config_schema VALUES ('threshold.divergence_stack.score_threshold', 'float', '0.40', 0, 1, NULL, false, 1, '[conventional] Minimum weighted divergence score to pass DivergenceStack detection gate. 0.40 requires at least the top 2-3 inputs to contribute. ML learning target post Phase 127 replay.', '2026-06-16 04:03:30.039122+00');
INSERT INTO public.config_schema VALUES ('feature.divergence_stack.min_agreeing', 'int', '3', 1, 5, NULL, false, 1, '[conventional] Minimum number of divergence inputs (of 5) required to agree for DivergenceStack to fire. 3 of 5 = supermajority; prevents low-breadth fires. ML learning target.', '2026-06-16 04:03:30.039122+00');
INSERT INTO public.config_schema VALUES ('feature.divergence_stack.confidence_norm', 'float', '0.60', 0.1, 1, NULL, false, 1, '[conventional] Denominator for DivergenceStack base_score normalization. 0.60 = practical 3-input maximum (top-3 weights: 0.30+0.25+0.20). Maps realistic max score to 1.0 confidence. Not an ML target; operator preference.', '2026-06-16 04:03:30.039122+00');
INSERT INTO public.config_schema VALUES ('weights.divergence_stack.rsi', 'float', '0.30', 0, 1, NULL, false, 1, '[initial_estimate] DivergenceStack confidence weight: RSI divergence input. Highest weight — RSI is most stable divergence measure. ML learning target.', '2026-06-16 04:03:30.039122+00');
INSERT INTO public.config_schema VALUES ('weights.divergence_stack.macd', 'float', '0.25', 0, 1, NULL, false, 1, '[initial_estimate] DivergenceStack confidence weight: MACD divergence input. ML learning target.', '2026-06-16 04:03:30.039122+00');
INSERT INTO public.config_schema VALUES ('weights.divergence_stack.vol', 'float', '0.20', 0, 1, NULL, false, 1, '[initial_estimate] DivergenceStack confidence weight: Volume/OBV divergence input. ML learning target.', '2026-06-16 04:03:30.039122+00');
INSERT INTO public.config_schema VALUES ('weights.divergence_stack.obv', 'float', '0.15', 0, 1, NULL, false, 1, '[initial_estimate] DivergenceStack confidence weight: OBV divergence input. ML learning target.', '2026-06-16 04:03:30.039122+00');
INSERT INTO public.config_schema VALUES ('weights.divergence_stack.cmf', 'float', '0.10', 0, 1, NULL, false, 1, '[initial_estimate] DivergenceStack confidence weight: CMF divergence input. Lowest weight — CMF is noisiest measure. ML learning target.', '2026-06-16 04:03:30.039122+00');
INSERT INTO public.config_schema VALUES ('threshold.vwap_reclaim.vol_threshold', 'float', '1.2', 0.5, 5, NULL, false, 1, '[conventional] Minimum volume expansion ratio (rel_volume or bar/session_avg) for VWAPReclaim gate. 1.2x is a modest expansion threshold appropriate for VWAP crosses. ML learning target post Phase 127 replay.', '2026-06-16 04:03:30.039122+00');
INSERT INTO public.config_schema VALUES ('feature.signal_writer.batch_size', 'int', '100', 1, 10000, NULL, false, 1, '[initial_estimate] Number of signal events to buffer before flushing to the database. Balances write latency against throughput. NOT ML target.', '2026-06-16 14:55:12.388711+00');
INSERT INTO public.config_schema VALUES ('feature.signal_writer.flush_interval_secs', 'float', '5.0', 0.1, 60, NULL, false, 1, '[initial_estimate] Maximum seconds between signal_writer flushes regardless of batch fullness. Caps write latency under low signal volume. NOT ML target.', '2026-06-16 14:55:12.388711+00');
INSERT INTO public.config_schema VALUES ('feature.signal_writer.max_buffer_size', 'int', '10000', 100, 1000000, NULL, false, 1, '[initial_estimate] Hard cap on in-memory signal buffer size. Prevents unbounded memory growth during burst periods. NOT ML target.', '2026-06-16 14:55:12.388711+00');
INSERT INTO public.config_schema VALUES ('feature.momentum.window_slow', 'int', NULL, NULL, NULL, NULL, false, 1, 'Slow-scale momentum z-score lookback window (bars). [initial_estimate].', '2026-06-22 18:19:00.340925+00');
INSERT INTO public.config_schema VALUES ('feature.lifecycle_writer.batch_size', 'int', '100', 1, 10000, NULL, false, 1, '[initial_estimate] Number of lifecycle events to buffer before flushing to signal_events status updates. NOT ML target.', '2026-06-16 14:55:12.388711+00');
INSERT INTO public.config_schema VALUES ('feature.lifecycle_writer.flush_interval_secs', 'float', '5.0', 0.1, 60, NULL, false, 1, '[initial_estimate] Maximum seconds between lifecycle_writer flushes regardless of batch fullness. NOT ML target.', '2026-06-16 14:55:12.388711+00');
INSERT INTO public.config_schema VALUES ('feature.lifecycle_writer.max_buffer_size', 'int', '10000', 100, 1000000, NULL, false, 1, '[initial_estimate] Hard cap on in-memory lifecycle event buffer size. Prevents unbounded memory growth during burst periods. NOT ML target.', '2026-06-16 14:55:12.388711+00');
INSERT INTO public.config_schema VALUES ('feature.signal_tracker.bootstrap_pending_window_days', 'int', '7', 1, 90, NULL, false, 1, '[initial_estimate] Lookback window in days for bootstrapping pending signals from signal_events on service startup. NOT ML target.', '2026-06-16 14:55:12.388711+00');
INSERT INTO public.config_schema VALUES ('feature.signal_tracker.bootstrap_active_window_days', 'int', '30', 1, 365, NULL, false, 1, '[initial_estimate] Lookback window in days for bootstrapping active signals from signal_events on service startup. NOT ML target.', '2026-06-16 14:55:12.388711+00');
INSERT INTO public.config_schema VALUES ('feature.signal_tracker.bootstrap_dedup_window_days', 'int', '3', 1, 30, NULL, false, 1, '[initial_estimate] Deduplication window in days when bootstrapping signals — suppresses re-processing of recently seen signal_ids. NOT ML target.', '2026-06-16 14:55:12.388711+00');
INSERT INTO public.config_schema VALUES ('feature.signal_tracker.bootstrap_max_attempts', 'int', '3', 1, 10, NULL, false, 1, '[initial_estimate] Maximum retry attempts for signal_tracker bootstrap DB queries on startup failure. NOT ML target.', '2026-06-16 14:55:12.388711+00');
INSERT INTO public.config_schema VALUES ('threshold.signal_tracker.staleness_score', 'float', '0.5', 0, 1, NULL, false, 1, '[initial_estimate] Staleness score threshold above which a signal is considered stale and eligible for expiry. Sourced from lifecycle_tracker.py. NOT ML target.', '2026-06-16 14:55:12.388711+00');
INSERT INTO public.config_schema VALUES ('feature.signal_auditor.audit_lookback_hours', 'int', '1', 1, 168, NULL, false, 1, '[initial_estimate] Lookback window in hours for signal_auditor SQL queries (SQL INTERVAL). Controls how far back the auditor scans for anomalies per cycle. NOT ML target.', '2026-06-16 14:55:12.388711+00');
INSERT INTO public.config_schema VALUES ('ui.signals.recent_window_days', 'int', '90', 1, 365, NULL, false, 1, '[initial_estimate] Default lookback window in days for the signals API recent endpoint. Drives the default date range shown in the dashboard. NOT ML target.', '2026-06-16 14:55:12.388711+00');
INSERT INTO public.config_schema VALUES ('ui.signals.min_confidence', 'float', '0.40', 0, 1, NULL, false, 1, '[data-derived] Minimum raw_confidence threshold for signals returned by the API. Calibrated at 0.40 as the empirical breakeven confidence level. NOT ML target.', '2026-06-16 14:55:12.388711+00');
INSERT INTO public.config_schema VALUES ('ui.signals.min_cis_score', 'float', '0.35', 0, 1, NULL, false, 1, '[initial_estimate] Minimum CIS (Composite Intelligence Score) for signals returned by filtered API endpoints. NOT ML target.', '2026-06-16 14:55:12.388711+00');
INSERT INTO public.config_schema VALUES ('ui.signals.today_window_hours', 'int', '24', 1, 72, NULL, false, 1, '[initial_estimate] Lookback window in hours defining "today" signals in the API (used for same-day signal queries). NOT ML target.', '2026-06-16 14:55:12.388711+00');
INSERT INTO public.config_schema VALUES ('ui.signals.yesterday_window_hours', 'int', '48', 1, 168, NULL, false, 1, '[initial_estimate] Lookback window in hours defining "yesterday" signals in the API (overlapping window — covers today + yesterday). NOT ML target.', '2026-06-16 14:55:12.388711+00');
INSERT INTO public.config_schema VALUES ('ui.signals.short_window_days', 'int', '7', 1, 30, NULL, false, 1, '[initial_estimate] Short lookback window in days for dashboard 7-day signal performance views. NOT ML target.', '2026-06-16 14:55:12.388711+00');
INSERT INTO public.config_schema VALUES ('ui.signals.medium_window_days', 'int', '30', 1, 90, NULL, false, 1, '[initial_estimate] Medium lookback window in days for dashboard 30-day signal performance views. NOT ML target.', '2026-06-16 14:55:12.388711+00');
INSERT INTO public.config_schema VALUES ('ui.signals.latency_threshold_minutes', 'int', '5', 1, 60, NULL, false, 1, '[initial_estimate] Signal latency threshold in minutes — signals older than this from computed_at are flagged as high-latency in the dashboard. NOT ML target.', '2026-06-16 14:55:12.388711+00');
INSERT INTO public.config_schema VALUES ('ui.signals.max_results', 'int', '500', 1, 10000, NULL, false, 1, '[initial_estimate] Maximum number of signal rows returned by unbounded API queries. Prevents runaway result sets. NOT ML target.', '2026-06-16 14:55:12.388711+00');
INSERT INTO public.config_schema VALUES ('ui.signals.top_n_results', 'int', '10', 1, 100, NULL, false, 1, '[initial_estimate] Number of top signals returned by ranked/summary endpoints (e.g., top N by confidence). NOT ML target.', '2026-06-16 14:55:12.388711+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.stop_demand_buffer_atr', 'float', '0.25', 0.05, 2, NULL, false, 1, '[initial_estimate] ATR multiplier added below demand zone low as stop buffer. Stop = nearest_demand_low - ATR x value. ML learning target: correlate with counterfactual_pnl_r per asset class after 30+ outcomes. Bounded below by feature.zone_engine.min_stop_distance_atr.', '2026-06-18 02:06:20.794073+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.stop_sweep_buffer_atr', 'float', '0.30', 0.05, 2, NULL, false, 1, '[initial_estimate] ATR multiplier below sweep level as stop buffer. Stop = sweep_level - ATR x value. ML learning target after 30+ outcomes.', '2026-06-18 02:06:20.794073+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.stop_ob_buffer_atr', 'float', '0.20', 0.05, 2, NULL, false, 1, '[initial_estimate] ATR multiplier below/above order block bottom/top as stop buffer. Used for both FVG and OB stop placements. ML learning target after 30+ outcomes.', '2026-06-18 02:06:20.794073+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.stop_swing_buffer_atr', 'float', '0.25', 0.05, 2, NULL, false, 1, '[initial_estimate] ATR multiplier below swing low (above swing high for shorts) as stop buffer. Also used for EMA-21 support/resistance stop placements. ML learning target.', '2026-06-18 02:06:20.794073+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.stop_sr_buffer_atr', 'float', '0.50', 0.05, 2, NULL, false, 1, '[initial_estimate] ATR multiplier below S/R nearest support (above resistance for shorts). Wider buffer reflects S/R level imprecision vs structural levels. ML learning target.', '2026-06-18 02:06:20.794073+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.stop_fallback_atr', 'float', '2.0', 0.5, 5, NULL, false, 1, '[initial_estimate] ATR multiplier for pure ATR fallback stop when no structural level exists. Stop = entry - ATR x value (longs). Also used as cap override when structural stop exceeds per-TF max_stop. ML learning target after 30+ outcomes.', '2026-06-18 02:06:20.794073+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.zone_sweep_atr', 'float', '0.76', 0.1, 2, NULL, false, 1, '[initial_estimate] ATR multiplier for sweep/reclaim entry zone half-width. Zone = entry +/- ATR x value (total width 1.52x ATR, passes 1.5x ATR gate). ML learning target after 30+ outcomes.', '2026-06-18 02:06:20.794073+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.zone_low_atr', 'float', '1.0', 0.1, 3, NULL, false, 1, '[initial_estimate] ATR multiplier for ATR fallback zone lower bound below entry. Zone_low = entry - ATR x value. Used when no structural zone is available. ML learning target after 30+ outcomes.', '2026-06-18 02:06:20.794073+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.zone_high_atr', 'float', '0.5', 0.1, 3, NULL, false, 1, '[initial_estimate] ATR multiplier for ATR fallback zone upper bound above entry. Zone_high = entry + ATR x value. Asymmetric: lower bound wider by design. ML learning target after 30+ outcomes.', '2026-06-18 02:06:20.794073+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.target_min_atr', 'float', '0.5', 0.1, 3, NULL, false, 1, '[initial_estimate] Minimum target distance from entry as ATR multiple. Filters structural candidate targets closer than this from the entry. ML learning target after 30+ outcomes.', '2026-06-18 02:06:20.794073+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.zone_plugin_fallback_atr', 'float', '0.2', 0.05, 2, NULL, false, 1, '[initial_estimate] Narrow ATR fallback zone half-width for plugins that bypass frame_trade(). Structural fallback — not an ML learning target. Operator preference.', '2026-06-18 02:06:20.794073+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.vp_proximity_atr', 'float', '0.5', 0.05, 2, NULL, false, 1, '[initial_estimate] ATR distance threshold for volume profile proximity gate. Price within VAH or VAL +/- ATR x value activates VP regime for target selection. ML learning target after 30+ outcomes.', '2026-06-18 02:06:20.794073+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.fallback_t1_atr', 'float', '2.0', 0.5, 6, NULL, false, 1, '[initial_estimate] Risk multiplier for ATR fallback T1 target. T1 = entry + risk x value. Applied when no structural target candidates pass RR gate. ML learning target after 30+ outcomes.', '2026-06-18 02:06:20.794073+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.fallback_t2_atr', 'float', '3.5', 1, 8, NULL, false, 1, '[initial_estimate] Risk multiplier for ATR fallback T2 target. T2 = entry + risk x value. ML learning target after 30+ outcomes.', '2026-06-18 02:06:20.794073+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.fallback_t3_atr', 'float', '5.5', 1, 12, NULL, false, 1, '[initial_estimate] Risk multiplier for ATR fallback T3 target. T3 = entry + risk x value. ML learning target after 30+ outcomes.', '2026-06-18 02:06:20.794073+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.min_stop_atr', 'float', '1.0', 0.25, 3, NULL, false, 1, '[initial_estimate] Minimum stop distance as ATR multiple from entry. Primary ML stop control: ensures stops are at least 1x ATR from entry. Bounded below by feature.zone_engine.min_stop_distance_atr (0.5 ATR). ML learning target — primary lever for stopped_at_entry rate reduction.', '2026-06-18 02:06:20.794073+00');
INSERT INTO public.config_schema VALUES ('threshold.trade_framer.min_rr_t1', 'float', '1.5', 0.5, 5, NULL, false, 1, '[initial_estimate] Minimum reward-to-risk ratio for T1 target. Signals with T1 RR below this threshold are rejected as non-viable. ML learning target after 30+ outcomes.', '2026-06-18 02:06:20.794073+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.adaptive_buffer_hard_cap', 'float', '1.40', 1, 3, NULL, false, 1, '[initial_estimate] Maximum multiplier expansion factor for the GARCH adaptive buffer. Caps the vol-driven stop widening: result = min(garch_result, base_mult x value). Operator preference — not an ML learning target (safety ceiling).', '2026-06-18 02:06:20.794073+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.structure_snap_proximity_atr', 'float', '1.5', 0.25, 5, NULL, false, 1, '[initial_estimate] ATR distance threshold for stop basis classification. Structural stops within this many effective-ATR units of the ATR fallback stop are classified as structure_snap; further stops are garch_adaptive. Structural classification parameter — not an ML learning target.', '2026-06-18 02:06:20.794073+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.adaptive_buffer_vol_ratio_min', 'float', '0.70', 0.1, 1, NULL, false, 1, '[initial_estimate] ML learning target: Lower clamp bound for garch_vol_ratio in _adaptive_buffer(). vol_ratio values below this are clamped to this value before piecewise evaluation. WARNING: these 12 coefficients define a single piecewise GARCH vol-response curve. Tuning one in isolation can break the function shape — tune as a group or preserve the piecewise structure.', '2026-06-18 10:17:35.999049+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.adaptive_buffer_vol_ratio_max', 'float', '1.50', 1, 3, NULL, false, 1, '[initial_estimate] ML learning target: Upper clamp bound for garch_vol_ratio in _adaptive_buffer(). vol_ratio values above this are clamped to this value before piecewise evaluation. WARNING: these 12 coefficients define a single piecewise GARCH vol-response curve. Tuning one in isolation can break the function shape — tune as a group or preserve the piecewise structure.', '2026-06-18 10:17:35.999049+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.adaptive_buffer_low_vol_base', 'float', '0.80', 0.3, 1, NULL, false, 1, '[initial_estimate] ML learning target: Base multiplier for the low-volatility branch (vol_ratio <= 1.0) of _adaptive_buffer(). At vol_ratio == vol_ratio_min, garch_mult == this value. WARNING: these 12 coefficients define a single piecewise GARCH vol-response curve. Tuning one in isolation can break the function shape — tune as a group or preserve the piecewise structure.', '2026-06-18 10:17:35.999049+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.adaptive_buffer_low_vol_slope_num', 'float', '0.20', 0, 1, NULL, false, 1, '[initial_estimate] ML learning target: Numerator of the slope fraction in the low-vol branch of _adaptive_buffer(). slope = low_vol_slope_num / low_vol_slope_den. WARNING: these 12 coefficients define a single piecewise GARCH vol-response curve. Tuning one in isolation can break the function shape — tune as a group or preserve the piecewise structure.', '2026-06-18 10:17:35.999049+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.adaptive_buffer_low_vol_slope_den', 'float', '0.30', 0.05, 1, NULL, false, 1, '[initial_estimate] ML learning target: Denominator of the slope fraction in the low-vol branch of _adaptive_buffer(). slope = low_vol_slope_num / low_vol_slope_den. min > 0 prevents division by zero. WARNING: these 12 coefficients define a single piecewise GARCH vol-response curve. Tuning one in isolation can break the function shape — tune as a group or preserve the piecewise structure.', '2026-06-18 10:17:35.999049+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.adaptive_buffer_high_vol_slope_num', 'float', '0.35', 0, 1, NULL, false, 1, '[initial_estimate] ML learning target: Numerator of the slope fraction in the high-vol branch of _adaptive_buffer(). slope = high_vol_slope_num / high_vol_slope_den. WARNING: these 12 coefficients define a single piecewise GARCH vol-response curve. Tuning one in isolation can break the function shape — tune as a group or preserve the piecewise structure.', '2026-06-18 10:17:35.999049+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.adaptive_buffer_high_vol_slope_den', 'float', '0.50', 0.05, 1, NULL, false, 1, '[initial_estimate] ML learning target: Denominator of the slope fraction in the high-vol branch of _adaptive_buffer(). slope = high_vol_slope_num / high_vol_slope_den. min > 0 prevents division by zero. WARNING: these 12 coefficients define a single piecewise GARCH vol-response curve. Tuning one in isolation can break the function shape — tune as a group or preserve the piecewise structure.', '2026-06-18 10:17:35.999049+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.adaptive_buffer_hurst_trend_threshold', 'float', '0.55', 0.5, 0.9, NULL, false, 1, '[initial_estimate] ML learning target: Hurst exponent threshold above which _adaptive_buffer() applies trend-tightening. Regime must be "trend". When hurst >= this value, result is tightened by (hurst - threshold) * tighten_rate. WARNING: these 12 coefficients define a single piecewise GARCH vol-response curve. Tuning one in isolation can break the function shape — tune as a group or preserve the piecewise structure.', '2026-06-18 10:17:35.999049+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.adaptive_buffer_hurst_mr_threshold', 'float', '0.45', 0.1, 0.5, NULL, false, 1, '[initial_estimate] ML learning target: Hurst exponent threshold below which _adaptive_buffer() applies mean-reversion tightening. Regime must be "mean_reversion". When hurst <= this value, result is tightened by (threshold - hurst) * tighten_rate. WARNING: these 12 coefficients define a single piecewise GARCH vol-response curve. Tuning one in isolation can break the function shape — tune as a group or preserve the piecewise structure.', '2026-06-18 10:17:35.999049+00');
INSERT INTO public.config_schema VALUES ('feature.garch.omega', 'float', '0.00001', 1e-06, 0.001, NULL, false, 1, '[conventional] GARCH(1,1) long-run variance intercept (omega). Standard prior for equity/futures returns; controls unconditional variance floor. ML learning target: tune per instrument class after sufficient trade_frames with counterfactual_pnl_r (n >= 100).', '2026-06-19 14:45:42.177928+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.adaptive_buffer_hurst_tighten_rate', 'float', '0.16', 0, 1, NULL, false, 1, '[initial_estimate] ML learning target: Rate at which Hurst deviation tightens the buffer result in _adaptive_buffer(). Applied as result *= 1.0 - (hurst_deviation) * tighten_rate. WARNING: these 12 coefficients define a single piecewise GARCH vol-response curve. Tuning one in isolation can break the function shape — tune as a group or preserve the piecewise structure.', '2026-06-18 10:17:35.999049+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.adaptive_buffer_garch_shock_threshold', 'float', '3.0', 1, 10, NULL, false, 1, '[initial_estimate] ML learning target: garch_shock value above which _adaptive_buffer() applies the shock floor multiplier. When garch_shock > this value, result is floored at base_mult * garch_shock_mult. WARNING: these 12 coefficients define a single piecewise GARCH vol-response curve. Tuning one in isolation can break the function shape — tune as a group or preserve the piecewise structure.', '2026-06-18 10:17:35.999049+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.adaptive_buffer_garch_shock_mult', 'float', '1.35', 1, 3, NULL, false, 1, '[initial_estimate] ML learning target: Floor multiplier applied to base_mult when a GARCH shock is detected in _adaptive_buffer(). result = max(result, base_mult * garch_shock_mult). WARNING: these 12 coefficients define a single piecewise GARCH vol-response curve. Tuning one in isolation can break the function shape — tune as a group or preserve the piecewise structure.', '2026-06-18 10:17:35.999049+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.stop_multiplier_floor.fx', 'float', '1.0', 0.5, 3, NULL, false, 1, '[initial_estimate] Per-asset-class minimum stop floor for FX instruments (EURUSD, GBPUSD, USDCHF, USDJPY). Expressed as ATR multiplier. Overrides universal min_stop_atr for FX. Seed derived from intelligence_features.technical_indicators->>''atr_14'' median per symbol / tick_size; class median ATR/tick ~8.9x. ML learning target: tune per asset class after Phase 133 corpus rebuild (n >= 30 trade_frames with counterfactual_pnl_r). First real value after Phase 133.', '2026-06-18 10:30:53.392518+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.stop_multiplier_floor.commodity_small_tick', 'float', '1.5', 0.5, 3, NULL, false, 1, '[initial_estimate] Per-asset-class minimum stop floor for commodity instruments with small tick sizes (SI, NG, HG, CL). Expressed as ATR multiplier. Seed = 1.5 because NG has only ~1.5x ATR/tick headroom, making a 1.0 ATR floor insufficient for minimum viable stop distance in absolute terms. ML learning target: tune per asset class after Phase 133 corpus rebuild. First real value after Phase 133.', '2026-06-18 10:30:53.392518+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.stop_multiplier_floor.equity_etf', 'float', '1.0', 0.5, 3, NULL, false, 1, '[initial_estimate] Per-asset-class minimum stop floor for equity ETF instruments (QQQ, SPY, IWM, XLE, SMH). Expressed as ATR multiplier. Class median ATR/tick ~15.2x — strong headroom, universal 1.0 ATR floor is sufficient as starting point. ML learning target: tune per asset class after Phase 133 corpus rebuild. First real value after Phase 133.', '2026-06-18 10:30:53.392518+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.stop_multiplier_floor.futures_large_tick', 'float', '1.0', 0.5, 3, NULL, false, 1, '[initial_estimate] Per-asset-class minimum stop floor for large-tick index futures (ES, NQ, YM, RTY). Expressed as ATR multiplier. Class median ATR/tick ~7.7x — all major contracts have adequate headroom at 1.0 ATR. ML learning target: tune per asset class after Phase 133 corpus rebuild. First real value after Phase 133.', '2026-06-18 10:30:53.392518+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.target_max_atr', 'float', '8.0', 1, 20, NULL, false, 1, '[initial_estimate] Maximum target distance from entry in ATR units (default fallback when no per-TF override). ML learning target: tune per-TF max target distances after 30+ outcomes.', '2026-06-18 17:59:32.91613+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.target_max_atr_1m', 'float', '3.0', 1, 10, NULL, false, 1, '[initial_estimate] Maximum target distance for 1m signals in ATR units. ML learning target.', '2026-06-18 17:59:32.91613+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.target_max_atr_5m', 'float', '5.0', 1, 15, NULL, false, 1, '[initial_estimate] Maximum target distance for 5m signals in ATR units. ML learning target.', '2026-06-18 17:59:32.91613+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.target_max_atr_15m', 'float', '7.0', 1, 20, NULL, false, 1, '[initial_estimate] Maximum target distance for 15m signals in ATR units. ML learning target.', '2026-06-18 17:59:32.91613+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.target_max_atr_1h', 'float', '8.0', 1, 20, NULL, false, 1, '[initial_estimate] Maximum target distance for 1h signals in ATR units. ML learning target.', '2026-06-18 17:59:32.91613+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.target_max_atr_4h', 'float', '8.0', 1, 20, NULL, false, 1, '[initial_estimate] Maximum target distance for 4h signals in ATR units. ML learning target.', '2026-06-18 17:59:32.91613+00');
INSERT INTO public.config_schema VALUES ('feature.trade_framer.target_max_atr_1d', 'float', '8.0', 1, 20, NULL, false, 1, '[initial_estimate] Maximum target distance for 1d signals in ATR units. ML learning target.', '2026-06-18 17:59:32.91613+00');
INSERT INTO public.config_schema VALUES ('alpha.regime.realized_vol_window', 'int', '20', NULL, NULL, NULL, false, 1, 'Rolling window (daily bars) for SPY realized vol (log-return std). [initial_estimate] Scaled to TF bars via _tf_window(daily, tf). ML target: No.', '2026-06-29 08:37:03.429741+00');
INSERT INTO public.config_schema VALUES ('feature.hmm.min_rows_for_training', 'int', '500', 100, 10000, NULL, false, 1, '[conventional] Minimum valid observation rows per TF required to attempt Baum-Welch training. Below this threshold the TF is skipped. Not an ML learning target.', '2026-06-19 14:45:42.177928+00');
INSERT INTO public.config_schema VALUES ('feature.hmm.vol_window', 'int', '20', 5, 100, NULL, false, 1, '[conventional] Rolling window (bars) for realized volatility computation in the HMM observation vector. Must match HMMRegimePlugin.vol_window for trainer/inference consistency. Not an ML learning target.', '2026-06-19 14:45:42.177928+00');
INSERT INTO public.config_schema VALUES ('feature.hmm.lookback_days.1m', 'int', '30', 7, 180, NULL, false, 1, '[conventional] Training query lookback in days for 1m bars (~43,200 bars on liquid futures). Not an ML learning target.', '2026-06-19 14:45:42.177928+00');
INSERT INTO public.config_schema VALUES ('feature.hmm.lookback_days.5m', 'int', '60', 14, 365, NULL, false, 1, '[conventional] Training query lookback in days for 5m bars (~17,280 bars). Not an ML learning target.', '2026-06-19 14:45:42.177928+00');
INSERT INTO public.config_schema VALUES ('feature.hmm.lookback_days.15m', 'int', '90', 30, 365, NULL, false, 1, '[conventional] Training query lookback in days for 15m bars (~8,640 bars). Not an ML learning target.', '2026-06-19 14:45:42.177928+00');
INSERT INTO public.config_schema VALUES ('feature.hmm.lookback_days.1h', 'int', '180', 60, 730, NULL, false, 1, '[conventional] Training query lookback in days for 1h bars (~4,320 bars). Not an ML learning target.', '2026-06-19 14:45:42.177928+00');
INSERT INTO public.config_schema VALUES ('feature.hmm.lookback_days.4h', 'int', '365', 90, 730, NULL, false, 1, '[conventional] Training query lookback in days for 4h bars (~2,190 bars). Not an ML learning target.', '2026-06-19 14:45:42.177928+00');
INSERT INTO public.config_schema VALUES ('feature.hmm.lookback_days.1d', 'int', '730', 180, 1825, NULL, false, 1, '[conventional] Training query lookback in days for 1d bars (~730 bars). Not an ML learning target.', '2026-06-19 14:45:42.177928+00');
INSERT INTO public.config_schema VALUES ('feature.garch.alpha', 'float', '0.10', 0.01, 0.5, NULL, false, 1, '[conventional] GARCH(1,1) shock coefficient (alpha). Weight on lagged squared return epsilon^2. Standard prior; 0.10 is conventional for daily-frequency equity series. ML learning target. Constraint: alpha + beta < 1 for stationarity.', '2026-06-19 14:45:42.177928+00');
INSERT INTO public.config_schema VALUES ('feature.garch.beta', 'float', '0.85', 0.5, 0.99, NULL, false, 1, '[conventional] GARCH(1,1) persistence coefficient (beta). Weight on lagged conditional variance. 0.85 is conventional; high persistence typical of equity vol. ML learning target. Constraint: alpha + beta < 1 for stationarity.', '2026-06-19 14:45:42.177928+00');
INSERT INTO public.config_schema VALUES ('feature.kalman.garch_r_scale', 'float', '10000.0', 100, 1000000, NULL, false, 1, '[conventional] Scale factor applied to garch_sigma when computing adaptive measurement noise R for the Kalman filter. R_adaptive = (garch_sigma * scale)^2. garch_sigma is in log-return units (~0.001-0.02); scale maps to R range 0.1-40 in price units. ML learning target: tune per instrument class after Phase 133 corpus.', '2026-06-19 14:45:42.177928+00');
INSERT INTO public.config_schema VALUES ('infra.ensemble_trainer.workers', 'int', '12', NULL, NULL, NULL, false, 1, 'Number of ProcessPoolExecutor workers for ensemble_trainer.py stratum-level parallelism. Each worker processes one (tf, regime) stratum: loads feature matrix X, computes Ledoit-Wolf shrinkage covariance, performs cluster deflation, and returns serializable weights. Default 12 = min(24_cores // 2, 16). Not an ML learning target. [initial_estimate]', '2026-06-28 20:26:16.450201+00');
INSERT INTO public.config_schema VALUES ('alpha.regime.vix_z_window', 'int', '252', NULL, NULL, NULL, false, 1, 'Rolling window (daily bars) for VIX z-score mean/std normalization. [conventional] 252 trading days scaled via _tf_window(). ML target: No.', '2026-06-29 08:37:03.429741+00');
INSERT INTO public.config_schema VALUES ('alpha.regime.ma_window', 'int', '200', NULL, NULL, NULL, false, 1, 'Rolling window (daily bars) for 200MA breadth signal. [conventional] Scaled via _tf_window(). ML target: No.', '2026-06-29 08:37:03.429741+00');
INSERT INTO public.config_schema VALUES ('alpha.validation.oos_start', 'string', '', NULL, NULL, NULL, false, 1, 'OOS holdout start timestamp (ISO8601 UTC). Set once during Phase 141 CORPUS-02. All IC measurement uses data BEFORE this timestamp. OOS used for final validation at Phase 142 exit gate only. [user_preference] ML target: No.', '2026-06-29 08:37:03.429741+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.min_obs_per_regime', 'int', '3000', NULL, NULL, NULL, false, 1, 'Minimum independent observations per (symbol, tf, regime) cell required for IC score to count toward BH-FDR gate and ensemble weighting. [initial_estimate] IC Sharpe on <3K obs too noisy to survive BH-FDR. ML target: No.', '2026-06-29 08:37:03.429741+00');
INSERT INTO public.config_schema VALUES ('infra.backfill.depth_days.1d', 'int', '7300', NULL, NULL, NULL, false, 1, 'Backfill depth (calendar days) for 1d bars. [rca_analysis] Confirmed available via SPY probe 2026-06-19 (7300d exact, 2006-2026). ML target: No.', '2026-07-02 11:17:43.123109+00');
INSERT INTO public.config_schema VALUES ('infra.backfill.depth_days.1h', 'int', '7300', NULL, NULL, NULL, false, 1, 'Backfill depth (calendar days) for 1h bars. [rca_analysis] Confirmed available via SPY probe 2026-07-02 (175,191 bars back to 2006-07-07); prior 5475d (15yr) was a deliberate cap, not a proven ceiling. ML target: No.', '2026-07-02 11:17:43.123109+00');
INSERT INTO public.config_schema VALUES ('infra.backfill.depth_days.15m', 'int', '7300', NULL, NULL, NULL, false, 1, 'Backfill depth (calendar days) for 15m bars. [rca_analysis] Confirmed available via SPY probe 2026-07-02 (700,770 bars back to 2006-07-07); prior 3650d (10yr) was a deliberate cap, not a proven ceiling. ML target: No.', '2026-07-02 11:17:43.123109+00');
INSERT INTO public.config_schema VALUES ('infra.backfill.depth_days.5m', 'int', '7300', NULL, NULL, NULL, false, 1, 'Backfill depth (calendar days) for 5m bars. [rca_analysis] Confirmed available via SPY probe 2026-07-02 (2,102,364 bars back to 2006-07-07); prior 1631d (4.5yr) was a deliberate cap, not a proven ceiling. ML target: No.', '2026-07-02 11:17:43.123109+00');
INSERT INTO public.config_schema VALUES ('infra.backfill.depth_days.1m', 'int', '90', NULL, NULL, NULL, false, 1, 'Backfill depth (calendar days) for 1m bars. [initial_estimate] Deliberate storage/compute tradeoff, not a retention constraint — 1m patterns (time-of-day, day-of-week) repeat on weekly/monthly cycles so 90d captures full repetition. IBKR confirmed 10yr+ retention (SPY probe 2026-06-19). ML target: No.', '2026-07-02 11:17:43.123109+00');
