INSERT INTO public.config_schema VALUES ('alpha.frame.hold_max_bars.high_bear.1h', 'int', '60', NULL, NULL, NULL, false, 1, '[initial_estimate] max hold bars; overwritten by EIC-02 IC decay calibration. NOT an ML learning target. Regime=high_bear, TF=1h.', '2026-07-02 17:00:47.806768+00');
INSERT INTO public.config_schema VALUES ('alpha.frame.hold_max_bars.high_bear.1d', 'int', '60', NULL, NULL, NULL, false, 1, '[initial_estimate] max hold bars; overwritten by EIC-02 IC decay calibration. NOT an ML learning target. Regime=high_bear, TF=1d.', '2026-07-02 17:00:47.806768+00');
INSERT INTO public.config_schema VALUES ('alpha.frame.hold_max_bars.high_bull.5m', 'int', '60', NULL, NULL, NULL, false, 1, '[initial_estimate] max hold bars; overwritten by EIC-02 IC decay calibration. NOT an ML learning target. Regime=high_bull, TF=5m.', '2026-07-02 17:00:47.806768+00');
INSERT INTO public.config_schema VALUES ('alpha.quant.cost_hurdle.5m', 'float', NULL, NULL, NULL, NULL, false, 1, 'Min CI lower bound (alpha_score units) for 5m emissions. Cost-aware directional gate: ci_lower must exceed this to pass. Initial 0.0 = no-op; raise after calibration from corpus data. [initial_estimate]', '2026-06-30 13:00:24.421853+00');
INSERT INTO public.config_schema VALUES ('feature.momentum.zscore_window', 'int', '252', NULL, NULL, NULL, false, 1, '[conventional] Rolling z-score window for momentum, ~1 trading year. Not an ML learning target.', '2026-06-21 00:53:32.557767+00');
