INSERT INTO public.config_schema VALUES ('feature.hurst.window', 'int', '252', NULL, NULL, NULL, false, 1, '[conventional] Hurst R/S rolling window, ~1 trading year. Not an ML learning target.', '2026-06-21 00:53:32.557767+00');
INSERT INTO public.config_schema VALUES ('feature.garch.window', 'int', '100', NULL, NULL, NULL, false, 1, '[initial_estimate] GARCH estimation window bars. ML learning target after sufficient IC data.', '2026-06-21 00:53:32.557767+00');
INSERT INTO public.config_schema VALUES ('feature.vix.zscore_window', 'int', '252', NULL, NULL, NULL, false, 1, '[conventional] VIX z-score rolling window, ~1 trading year. Not an ML learning target.', '2026-06-21 00:53:32.557767+00');
INSERT INTO public.config_schema VALUES ('feature.yield_curve.zscore_window', 'int', '252', NULL, NULL, NULL, false, 1, '[conventional] Yield curve z-score window, ~1 trading year. Not an ML learning target.', '2026-06-21 00:53:32.557767+00');
INSERT INTO public.config_schema VALUES ('feature.regime.cache_refresh_bars', 'int', '30', NULL, NULL, NULL, false, 1, '[initial_estimate] Regime feature recompute cadence in bars. Regime-level features (HMM, Hurst, Shannon, GARCH) are expensive; recompute every N bars and serve from cache. ML learning target.', '2026-06-21 00:53:32.557767+00');
INSERT INTO public.config_schema VALUES ('alpha.vector.v1_quant.members', 'str', 'momentum_z_5,momentum_z_20,hma_slope_z,range_position,bar_close_pos,atr_z,vol_ratio,ctf_momentum', NULL, NULL, NULL, false, 1, '[initial_estimate] V1 Quant vector constituent primitives. Mutable via APR. IC discovery may prune members.', '2026-06-21 00:53:32.560163+00');
