INSERT INTO public.config_schema VALUES ('feature.period.rsi.mid', 'int', '14', NULL, NULL, NULL, false, 1, '[conventional] RSI mid period (Wilder canonical). ML learning target after sufficient IC data.', '2026-06-21 03:18:55.547569+00');
INSERT INTO public.config_schema VALUES ('feature.period.rsi.slow', 'int', '28', NULL, NULL, NULL, false, 1, '[conventional] RSI slow period (double of canonical). ML learning target after sufficient IC data.', '2026-06-21 03:18:55.547569+00');
INSERT INTO public.config_schema VALUES ('feature.period.cci.fast', 'int', '10', NULL, NULL, NULL, false, 1, '[initial_estimate] CCI fast period. ML learning target after sufficient IC data.', '2026-06-21 03:18:55.547569+00');
INSERT INTO public.config_schema VALUES ('feature.period.cci.mid', 'int', '20', NULL, NULL, NULL, false, 1, '[initial_estimate] CCI mid period. ML learning target after sufficient IC data.', '2026-06-21 03:18:55.547569+00');
