INSERT INTO public.config_schema VALUES ('feature.vol_of_vol.window', 'int', '20', 5, 100, NULL, false, 1, '[conventional] Rolling window (bars) for vol_of_vol (rolling std of atr_z). Not an ML learning target at seed time.', '2026-07-07 19:42:22.415544+00');
INSERT INTO public.config_schema VALUES ('feature.high_low_corr.window', 'int', '252', 20, 500, NULL, false, 1, '[conventional] Rolling window (bars, annual-scale) for high_low_corr Pearson correlation of H and L. Not an ML learning target at seed time.', '2026-07-07 19:42:22.415544+00');
INSERT INTO public.config_schema VALUES ('feature.variance_ratio.fast', 'int', '10', 3, 50, NULL, false, 1, '[conventional] Fast window (bars) for variance_ratio_fast (Lo-MacKinlay variance ratio). Not an ML learning target at seed time.', '2026-07-07 19:42:22.415544+00');
INSERT INTO public.config_schema VALUES ('feature.variance_ratio.slow', 'int', '30', 10, 150, NULL, false, 1, '[conventional] Slow window (bars) for variance_ratio_slow. Not an ML learning target at seed time.', '2026-07-07 19:42:22.415544+00');
INSERT INTO public.config_schema VALUES ('feature.vol_asymmetry.window', 'int', '252', 20, 500, NULL, false, 1, '[conventional] Rolling window (bars, annual-scale) for vol_asymmetry_z (std(ret|up)/std(ret|down) z-score). Not an ML learning target at seed time.', '2026-07-07 19:42:22.415544+00');
INSERT INTO public.config_schema VALUES ('feature.bb_pct_b.fast', 'int', '20', 5, 100, NULL, false, 1, '[conventional] Fast Bollinger Band period (classic BB(20)) for bb_pct_b_fast. Not an ML learning target at seed time.', '2026-07-07 19:42:22.415544+00');
INSERT INTO public.config_schema VALUES ('feature.bb_pct_b.slow', 'int', '50', 10, 200, NULL, false, 1, '[conventional] Slow Bollinger Band period for bb_pct_b_slow. Not an ML learning target at seed time.', '2026-07-07 19:42:22.415544+00');
INSERT INTO public.config_schema VALUES ('feature.hv.fast', 'int', '10', 3, 50, NULL, false, 1, '[conventional] Fast window (bars) for hv_z_fast close-to-close historical volatility. Not an ML learning target at seed time.', '2026-07-07 19:42:22.415544+00');
INSERT INTO public.config_schema VALUES ('feature.hv.slow', 'int', '30', 10, 150, NULL, false, 1, '[conventional] Slow window (bars) for hv_z_slow. Not an ML learning target at seed time.', '2026-07-07 19:42:22.415544+00');
INSERT INTO public.config_schema VALUES ('feature.hv.ratio_window', 'int', '252', 20, 500, NULL, false, 1, '[conventional] Rolling mean window (bars, annual-scale) for hv_ratio (hv_fast / rolling_mean(hv, N)). Not an ML learning target at seed time.', '2026-07-07 19:42:22.415544+00');
INSERT INTO public.config_schema VALUES ('feature.parkinson_vol.window', 'int', '20', 5, 100, NULL, false, 1, '[conventional] Rolling-average window (bars) for parkinson_vol_z raw estimator. Not an ML learning target at seed time.', '2026-07-07 19:42:22.415544+00');
INSERT INTO public.config_schema VALUES ('feature.parkinson_vol.zscore_window', 'int', '252', 20, 500, NULL, false, 1, '[conventional] Z-score normalization window (bars, annual-scale) for parkinson_vol_z. Not an ML learning target at seed time.', '2026-07-07 19:42:22.415544+00');
INSERT INTO public.config_schema VALUES ('feature.garman_klass_vol.window', 'int', '20', 5, 100, NULL, false, 1, '[conventional] Rolling-average window (bars) for garman_klass_vol_z raw estimator. Not an ML learning target at seed time.', '2026-07-07 19:42:22.415544+00');
INSERT INTO public.config_schema VALUES ('feature.garman_klass_vol.zscore_window', 'int', '252', 20, 500, NULL, false, 1, '[conventional] Z-score normalization window (bars, annual-scale) for garman_klass_vol_z. Not an ML learning target at seed time.', '2026-07-07 19:42:22.415544+00');
INSERT INTO public.config_schema VALUES ('feature.yang_zhang_vol.window', 'int', '20', 5, 100, NULL, false, 1, '[conventional] Rolling window (bars) for yang_zhang_vol_z raw variance estimator. Not an ML learning target at seed time.', '2026-07-07 19:42:22.415544+00');
INSERT INTO public.config_schema VALUES ('feature.yang_zhang_vol.zscore_window', 'int', '252', 20, 500, NULL, false, 1, '[conventional] Z-score normalization window (bars, annual-scale) for yang_zhang_vol_z. Not an ML learning target at seed time.', '2026-07-07 19:42:22.415544+00');
INSERT INTO public.config_schema VALUES ('feature.vol_velocity.window', 'int', '14', 3, 50, NULL, false, 1, '[conventional] Rolling window (bars) for vol_velocity_z (z-score of rolling atr_z velocity). Not an ML learning target at seed time.', '2026-07-07 19:42:22.415544+00');
INSERT INTO public.config_schema VALUES ('feature.intraday_noise.window', 'int', '78', 10, 200, NULL, false, 1, '[conventional] Session window (bars) for intraday_noise_ratio — 78 = one NY session at 5-minute resolution (390min/5min). Not an ML learning target at seed time.', '2026-07-07 19:42:22.415544+00');
INSERT INTO public.config_schema VALUES ('feature.price_vol_corr.fast', 'int', '252', 20, 500, NULL, false, 1, '[conventional] Fast rolling window (bars, annual-scale) for price_vol_corr_fast Pearson(|log ret|, volume). Not an ML learning target at seed time.', '2026-07-07 19:42:22.415544+00');
INSERT INTO public.config_schema VALUES ('feature.price_vol_corr.slow', 'int', '504', 50, 1000, NULL, false, 1, '[conventional] Slow rolling window (bars, 2yr-scale) for price_vol_corr_slow. Not an ML learning target at seed time.', '2026-07-07 19:42:22.415544+00');
INSERT INTO public.config_schema VALUES ('alpha.fx_regime.momentum_window', 'int', NULL, 5, 500, NULL, false, 1, '[conventional] Rolling window, in DAILY bars, for UUP and HYG log-return z-score. Scaled to the target TF via _tf_window(daily, tf) at compute time.', '2026-07-12 22:50:16.119721+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.partial_fdr_alpha', 'float', '0.05', 0.001, 0.2, NULL, false, 1, '[initial_estimate] Benjamini-Hochberg FDR correction alpha for the interaction-primitive partial-IC family (todo 037). Same conventional 5% as alpha.ic.fdr_alpha (migration 161) but a dedicated key: this family is ~8 features x a handful of (tf, lookahead) cells, a different multiplicity budget than the 516K-hypothesis corpus-wide atomic-feature FDR pass. Not an ML learning target.', '2026-07-09 20:40:57.210779+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.partial_control_condition_max', 'float', '1000.0', 10, 100000, NULL, false, 1, '[initial_estimate] Condition-number ceiling for partial_spearman_ic''s control-design-matrix ill-conditioning guard (todo 037). Above this, the control set is too collinear for a numerically stable partial correlation and partial_ic is returned as NULL rather than a garbage number. Seeded to match the E2 mean-variance path''s mv_condition_max precedent (services/ensemble_ic_engine.py). Not an ML learning target.', '2026-07-09 20:40:57.210779+00');
INSERT INTO public.config_schema VALUES ('alpha.frame.stop_atr_mult', 'float', '1.5', NULL, NULL, NULL, false, 1, '[initial_estimate] FRAME-01: stop-loss distance in ATR multiples from entry. Snapshotted onto every alpha_frames row at creation time. NOT an ML learning target.', '2026-07-10 10:13:36.61183+00');
INSERT INTO public.config_schema VALUES ('alpha.frame.target_r_multiple', 'float', '2.0', NULL, NULL, NULL, false, 1, '[initial_estimate] FRAME-01: target R-multiple (reward:risk ratio) applied on top of the ATR-derived stop distance -- target_price = entry +/- target_r_multiple * stop_distance. Use this exact key name (Pitfall 3) -- the ATR path is the sole target path (sr_resist_dist is 100% NULL across the corpus), so a conditional-fallback-style name would be inaccurate. NOT an ML learning target.', '2026-07-10 10:13:36.61183+00');
INSERT INTO public.config_schema VALUES ('alpha.frame.atr_period', 'int', '14', NULL, NULL, NULL, false, 1, '[conventional] FRAME-01: trailing bar count for the price-unit ATR that Plan 02''s CounterfactualTracker computes from market_data_ohlcv for frame geometry (review H2 -- feature_vectors has no price-unit ATR column, only normalized derivatives). NOT an ML learning target.', '2026-07-10 10:13:36.61183+00');
INSERT INTO public.config_schema VALUES ('infra.interaction_primitives_pilot.fetch_flush_rows', 'int', '500000', 1000, 10000000, NULL, false, 1, '[initial_estimate] Row count after which _fetch_tf_dataset() in scripts/ops/alpha/ops_interaction_primitives_pilot.py flushes its per-symbol raw_by_symbol Python-object buffers to numpy chunk-arrays (Task 3 v3 memory-blowup fix, todo 037). Bounds only the TRANSIENT Python-list accumulation buffer during the tf partition scan (tf=5m is ~25.35M rows) -- the fully concatenated per-symbol dataset this produces still resides in RAM for the whole tf (~4.3GB for tf=5m), which this key does not bound. Sized so the transient buffer stays well under a few hundred MB peak (500,000 rows x 25 cols x ~32 bytes/Python-float-object overhead approx 400MB). Memory-safety tuning knob, not a correctness gate -- not an ML learning target.', '2026-07-10 10:04:52.240014+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.bootstrap_block_size.15m', 'int', '26', 5, 200, NULL, false, 1, '[initial_estimate] Circular block bootstrap block size for 15m bars. ~26 bars per trading day. See alpha.ic.bootstrap_block_size.5m for methodology. Not an ML learning target.', '2026-06-22 18:46:44.052664+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.bootstrap_block_size.1d', 'int', '10', 3, 100, NULL, false, 1, '[conventional] Circular block bootstrap block size for 1d bars. Conventional lower bound of 10 for daily frequency. See alpha.ic.bootstrap_block_size.5m for methodology. Not an ML learning target.', '2026-06-22 18:46:44.052664+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.bootstrap_block_size.1h', 'int', '10', 3, 100, NULL, false, 1, '[conventional] Circular block bootstrap block size for 1h bars. Conventional lower bound of 10; fewer than 10 bars per day at this timeframe. See alpha.ic.bootstrap_block_size.5m for methodology. Not an ML learning target.', '2026-06-22 18:46:44.052664+00');
INSERT INTO public.config_schema VALUES ('alpha.fx_regime.dollar_strong_threshold', 'float', NULL, 0, 5, NULL, false, 1, '[initial_estimate] UUP z-score above which dollar regime is "strong". Candidate ML target.', '2026-07-12 22:50:16.119721+00');
INSERT INTO public.config_schema VALUES ('alpha.fx_regime.carry_risk_on_threshold', 'float', NULL, -5, 5, NULL, false, 1, '[initial_estimate] HYG z-score above which carry environment is "risk_on".', '2026-07-12 22:50:16.119721+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.bootstrap_block_size.5m', 'int', '78', 5, 500, NULL, false, 1, '[initial_estimate] Circular block bootstrap block size for 5m bars. ~78 bars per trading day captures one day of autocorrelation structure per Hall & Horowitz 1996 O(N^(1/3)) guideline. APR-backed so empirical optimal block length can be updated without code change. Not an ML learning target.', '2026-06-22 18:46:44.052664+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.bootstrap_resamples', 'int', '2000', 200, 10000, NULL, false, 1, '[conventional] Number of circular block bootstrap resamples for IC confidence interval estimation. 2000 is conventional for stable CI coverage. Not an ML learning target.', '2026-06-22 18:46:44.052664+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.bootstrap_seed', 'int', '42', 0, 2147483647, NULL, false, 1, '[conventional] RNG seed for circular block bootstrap IC confidence interval estimation. Fixed seed ensures reproducible CI bounds across runs with identical inputs. CAUTION: changing this seed invalidates all existing feature_ic_scores CI columns; a full recompute (truncate + backfill) is required. Not an ML learning target. Seed sensitivity test: run with seeds 0-99 on a held-out window; if CI variance < 1% of IC magnitude, seed choice is immaterial.', '2026-06-23 09:06:30.436513+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.canary_rng_seed', 'int', '90042', 0, 4294967295, NULL, false, 1, '[initial_estimate] Base RNG seed for the canary_noise_gaussian/canary_noise_uniform control predictors (feature_factory.py._canary_sub_seed derives independent per-canary, per-bar sub-seeds from this one key). Changing it changes every canary noise value corpus-wide, invalidating any in-flight canary integrity comparison — same caution class as alpha.hmm.random_state. Not an ML learning target.', '2026-07-11 20:54:19.797741+00');
INSERT INTO public.config_schema VALUES ('alpha.rates_regime.curve_window', 'int', NULL, 5, 500, NULL, false, 1, '[conventional] Rolling window, in DAILY bars, for TLT-SHY log-return spread z-score normalization (mean and std both computed over this window). Scaled to the target TF via _tf_window(daily, tf) at compute time (Plan 04 dispatcher pre-scales ALL group window params this way). Warmup = 2*window bars.', '2026-07-12 22:50:16.119721+00');
INSERT INTO public.config_schema VALUES ('alpha.rates_regime.credit_window', 'int', NULL, 5, 500, NULL, false, 1, '[conventional] Rolling window, in DAILY bars, for HYG-LQD log-return spread z-score normalization. Scaled to the target TF via _tf_window(daily, tf) at compute time.', '2026-07-12 22:50:16.119721+00');
INSERT INTO public.config_schema VALUES ('alpha.equity_regime.vix_low_pct', 'float', NULL, 0, 1, NULL, false, 1, '[initial_estimate] VIX percentile below which vol regime is "low". Same calibration as alpha.regime.vix_low_pct. Candidate ML learning target.', '2026-07-12 22:50:16.119721+00');
INSERT INTO public.config_schema VALUES ('alpha.equity_regime.vix_high_pct', 'float', NULL, 0, 1, NULL, false, 1, '[initial_estimate] VIX percentile above which vol regime is "high". Candidate ML learning target.', '2026-07-12 22:50:16.119721+00');
INSERT INTO public.config_schema VALUES ('alpha.equity_regime.realized_vol_window', 'int', NULL, 5, 500, NULL, false, 1, '[conventional] Rolling window, in DAILY bars, for SPY realized-vol computation (log-return std). Scaled to the target TF via _tf_window(daily, tf) at compute time. Warmup requires realized_vol_window + vix_z_window bars before any valid signal.', '2026-07-12 22:50:16.119721+00');
INSERT INTO public.config_schema VALUES ('alpha.equity_regime.vix_z_window', 'int', NULL, 20, 1000, NULL, false, 1, '[conventional] Rolling window, in DAILY bars, for VIX-proxy z-score normalization (mean and std). 252 = 1 trading year. Scaled via _tf_window(daily, tf) at compute time. Candidate ML learning target.', '2026-07-12 22:50:16.119721+00');
INSERT INTO public.config_schema VALUES ('alpha.equity_regime.ma_window', 'int', NULL, 20, 500, NULL, false, 1, '[conventional] Moving-average window, in DAILY bars, for 200MA breadth signal. 200 = conventional long-term MA. Scaled via _tf_window(daily, tf) at compute time. Candidate ML learning target.', '2026-07-12 22:50:16.119721+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.sharpe_window_size_subsampled', 'int', '100', 1, NULL, NULL, false, 1, '[rca_analysis] Fixed IC-Sharpe rolling window size expressed directly in SUBSAMPLED bars (todo 096), replacing the deprecated alpha.ic.sharpe_window_size (raw bars // stride) semantics that let per-window statistical power collapse at longer lookaheads and mechanically deflated ic_sharpe with zero real signal decay -- see scripts/analysis/ic_sharpe_stride_bias_check.py for the Monte Carlo proof. WARNING: changing this value changes the statistical meaning of every ic_sharpe/ic_sharpe_hac value and invalidates all downstream hold_max_bars calibration -- requires a full corpus re-run and a coordinated rescale of every sharpe-denominated threshold (alpha.ensemble_ic.decay_threshold, alpha.ensemble.sharpe_floor, alpha.feature_registry.min_ic_sharpe_default). NOT an ML learning target.', '2026-07-13 08:56:20.784413+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.sharpe_window_size', 'int', '2000', 200, 20000, NULL, false, 1, '[deprecated] [rca_analysis] Observations per rolling IC Sharpe window. 2000 non-overlapping observations at 1/5 sub-sampling = 10,000 bars per window. Matches the minimum for statistically stable IC Sharpe per IC spec §X.1. Not an ML learning target.', '2026-06-22 18:46:44.052664+00');
INSERT INTO public.config_schema VALUES ('alpha.publisher.is_shadow', 'bool', 'true', NULL, NULL, NULL, false, 1, '[initial_value] Operator-facing promotion switch (todo 011). When true, AlphaPublisher stamps every emitted alpha_events row is_shadow=true. Flip to false only after all Phase 144 promotion-gate criteria in todo 011 pass on the shadow record -- this is a one-way live-promotion switch, not an ML learning target.', '2026-07-14 09:34:04.283104+00');
INSERT INTO public.config_schema VALUES ('alpha.concept_registry.ensemble_strategy_min_promotion_consecutive', 'int', '2', 1, 10, NULL, false, 1, '[initial_estimate] Consecutive winning A/B evaluation rounds required before a candidate ensemble_strategy concept promotes to active. Set below the canonical doc''s generic default of 3 because this domain''s per-round bar is already far stronger than a scalar p<0.05 gate: non-overlapping CIs (challenger ic_ci_lower > champion ic_ci_upper) AND walk_forward_stable AND BH-FDR survival across strata. ML learning target: no; operator may tune.', '2026-07-14 15:50:14.798183+00');
INSERT INTO public.config_schema VALUES ('alpha.concept_registry.ensemble_strategy_min_new_observations', 'float', '2000', 100, 100000, NULL, false, 1, '[conventional] Evidence-mass re-evaluation floor (F3, invariant 2): a concept may not be re-evaluated until >= this many NEW independent observations (sum of n_independent across compared strata, delta vs the last recorded eval) have accrued. Mirrors alpha.decay.recovery_min_observations (2000), the identical standard Phase 143 applies to feature-recovery evidence. Corpus-advance (corpus_build_ref changed) remains a necessary but insufficient precondition. ML learning target: no.', '2026-07-14 15:50:14.798183+00');
INSERT INTO public.config_schema VALUES ('alpha.concept_registry.ensemble_strategy_min_observations', 'float', '1000', 100, 100000, NULL, false, 1, '[initial_estimate] Initial-promotion effective-N observation floor (invariant 7): no promotion fires until the evaluation carries >= this many independent observations, regardless of statistical significance. Value from the canonical doc''s Domains table floor for ensemble_strategy (1,000, per-TF fold minimum), stated against effective N (n_independent), never raw overlapping bars. ML learning target: no.', '2026-07-14 15:50:14.798183+00');
INSERT INTO public.config_schema VALUES ('infra.ibkr.retry_count', 'int', '3', 1, 10, NULL, false, 1, '[conventional] Number of retry attempts on an ambiguous (non-confirmed-no-data) empty historical-data result before giving up on a chunk. Not an ML learning target.', '2026-07-15 01:30:16.261438+00');
INSERT INTO public.config_schema VALUES ('infra.ibkr.retry_backoff_base_s', 'int', '65', 1, 300, NULL, false, 1, '[conventional] Base seconds for exponential backoff between retry attempts (base * 2**attempt: 65s then 130s at the default retry_count=3). Not an ML learning target.', '2026-07-15 01:30:16.261438+00');
INSERT INTO public.config_schema VALUES ('infra.ibkr.no_data_confirmation_chunks', 'int', '2', 1, 10, NULL, false, 1, '[conventional] Consecutive confirmed-no-data (Error 162) chunks required before treating a backward historical-data walk as having passed the instrument''s launch date (todo 049). Not an ML learning target.', '2026-07-15 01:30:16.261438+00');
INSERT INTO public.config_schema VALUES ('alpha.tag_calibrator.fdr_alpha', 'float', '0.05', 0.001, 0.5, NULL, false, 1, '[conventional] Benjamini-Hochberg FDR alpha applied run-level across the full measured tag matrix. Statistical governance threshold, not an ML learning target.', '2026-07-17 08:09:04.058166+00');
INSERT INTO public.config_schema VALUES ('alpha.tag_calibrator.expiry_consecutive_fails', 'int', '3', 1, 10, NULL, false, 1, '[initial_estimate] Consecutive failing runs required before an empirical instrument_tags row is expired (valid_to set); prevents single-run FDR-flicker expiry under weekly re-runs with ~97% window overlap. Not an ML learning target.', '2026-07-17 08:09:04.058166+00');
INSERT INTO public.config_schema VALUES ('alpha.tag_calibrator.discovery_oos_days', 'int', '63', 5, 500, NULL, false, 1, '[initial_estimate] Out-of-sample days required before a newly discovered (gap-annotated) empirical tag is promoted to a live instrument_tags row. Not an ML learning target.', '2026-07-17 08:09:04.058166+00');
INSERT INTO public.config_schema VALUES ('alpha.tag_calibrator.min_sample_n', 'int', '60', 10, 5000, NULL, false, 1, '[initial_estimate] Minimum paired-return sample size required before a (symbol, factor_series) loading is measured at all. Not an ML learning target.', '2026-07-17 08:09:04.058166+00');
INSERT INTO public.config_schema VALUES ('alpha.tag_calibrator.hac_max_lag', 'int', '5', 1, 60, NULL, false, 1, '[conventional] Newey-West Bartlett-kernel max lag for the HAC-adjusted standard error on each measured loading. Not an ML learning target.', '2026-07-17 08:09:04.058166+00');
INSERT INTO public.config_schema VALUES ('alpha.tag_calibrator.half_life_min_days', 'int', '30', 1, 3650, NULL, false, 1, '[initial_estimate] Lower bound for a per-tag_vocabulary-row half_life_days value; guards against a pathologically fast decay being configured. Not an ML learning target.', '2026-07-17 08:09:04.058166+00');
INSERT INTO public.config_schema VALUES ('alpha.tag_calibrator.half_life_max_days', 'int', '365', 1, 3650, NULL, false, 1, '[initial_estimate] Upper bound for a per-tag_vocabulary-row half_life_days value; guards against a pathologically slow (effectively permanent) decay being configured. Not an ML learning target.', '2026-07-17 08:09:04.058166+00');
INSERT INTO public.config_schema VALUES ('alpha.frame.target_r_multiple.high_bull.15m', 'float', '2.0', 0.1, 20, NULL, false, 1, '[initial_estimate] Phase 166 scalar candidate: per-(regime,tf) target R-multiple (reward:risk ratio) applied on top of the ATR-derived stop distance. Seeded at the current global alpha.frame.target_r_multiple (migration 214) value as a starting point -- overwritten by _calibrate_stop_target (EIC-scalar) after first champion weight_version run. NOT an ML learning target. Regime=high_bull, TF=15m.', '2026-07-23 11:53:06.584488+00');
INSERT INTO public.config_schema VALUES ('alpha.frame.stop_atr_mult.high_bull.1h', 'float', '1.5', 0.1, 10, NULL, false, 1, '[initial_estimate] Phase 166 scalar candidate: per-(regime,tf) stop-loss distance in ATR multiples. Seeded at the current global alpha.frame.stop_atr_mult (migration 214) value as a starting point -- overwritten by _calibrate_stop_target (EIC-scalar) after first champion weight_version run. NOT an ML learning target. Regime=high_bull, TF=1h.', '2026-07-23 11:53:06.584488+00');
INSERT INTO public.config_schema VALUES ('infra.vocabulary_drift.window_days', 'int', '30', 1, 365, NULL, false, 1, '[initial_estimate] Recent-window length (days) for the column-backed vocabulary drift audit; not an ML learning target.', '2026-07-18 00:22:46.489089+00');
INSERT INTO public.config_schema VALUES ('alpha.quant.max_abs_return.5m', 'float', '0.25', 0.05, 1, NULL, false, 1, '[initial_estimate] 1-bar (fast-scale) plausibility ceiling on |return_fast| for 5m forward returns (todo 148). sqrt(lookahead_bars)-scaled per scale by forward_return_writer.py:scale_max_abs_return() before being applied to mid/slow/extended -- NEVER applied flat across scales (a flat ceiling false-flags genuine multi-month commodity/EM-ETF moves at slow/extended horizons). Above the scaled ceiling, return_{scale}_suspect is set true and the row is excluded from mean-based consumers (rank-IC layers are unaffected -- Spearman is robust to outlier magnitude). Not an ML learning target.', '2026-07-19 22:57:03.100577+00');
INSERT INTO public.config_schema VALUES ('alpha.quant.max_abs_return.15m', 'float', '0.30', 0.05, 1, NULL, false, 1, '[initial_estimate] 1-bar (fast-scale) plausibility ceiling on |return_fast| for 15m forward returns (todo 148). See alpha.quant.max_abs_return.5m for full rationale including the sqrt-scaling requirement. Not an ML learning target.', '2026-07-19 22:57:03.100577+00');
INSERT INTO public.config_schema VALUES ('alpha.quant.max_abs_return.1h', 'float', '0.40', 0.05, 1.5, NULL, false, 1, '[initial_estimate] 1-bar (fast-scale) plausibility ceiling on |return_fast| for 1h forward returns (todo 148). See alpha.quant.max_abs_return.5m for full rationale including the sqrt-scaling requirement. Not an ML learning target.', '2026-07-19 22:57:03.100577+00');
INSERT INTO public.config_schema VALUES ('alpha.quant.max_abs_return.1d', 'float', '0.50', 0.05, 2, NULL, false, 1, '[initial_estimate] 1-bar (fast-scale) plausibility ceiling on |return_fast| for 1d forward returns (todo 148). Wider than intraday tfs to accommodate genuine large single-day moves (earnings gaps, crisis days) that are real signal, not corruption. See alpha.quant.max_abs_return.5m for full rationale including the sqrt-scaling requirement. Not an ML learning target.', '2026-07-19 22:57:03.100577+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.dependence_length_flag_ratio', 'float', '2.0', 1, 10, NULL, false, 1, '[conventional] Flag threshold for ops_dependence_length_diagnostic.py (todo 145): a (feature, tf) cell is flagged lower-trust when its measured 1/e-decorrelation-lag / bootstrap_block_size ratio exceeds this value. A factor-of-2 overshoot is a reasonable first trigger -- live cases (ctf_momentum ~4x, flight_quality ~750x) cluster well clear of this floor. Written to integrity_monitor as threshold_value, monitor_type=''ic_bootstrap''. Not an ML learning target.', '2026-07-20 00:53:57.55915+00');
INSERT INTO public.config_schema VALUES ('alpha.quant.cross_symbol_corroboration.window_minutes', 'int', '60', 5, 240, NULL, false, 1, '[rca_analysis] Time window (+/- minutes) within which another symbol''s ANY-scale suspect flag counts toward cross-symbol corroboration (todo 152). Verified against the live 2010-05-06 Flash Crash cluster (CWB/ITA/VTV/VUG/VYM), whose suspect rows stagger across bar_ts and scale rather than sharing one exact (tf, bar_ts, scale) triple -- an exact match never corroborates real events. Used by services/forward_return_writer.py alongside alpha.quant.cross_symbol_corroboration.min_symbols. Not an ML learning target.', '2026-07-20 07:57:46.058478+00');
INSERT INTO public.config_schema VALUES ('feature.smc.breaker.lookback', 'int', '10', 2, 50, NULL, false, 1, '[conventional] Trailing bar window for breaker-block derivation from order_blocks'' active-OB list (stateless recompute, no cross-call self._state). Matches BreakerBlocksPlugin''s InputSpec(lookback=10). Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.mitigation.lookback', 'int', '10', 2, 50, NULL, false, 1, '[conventional] Trailing bar window for order-block mitigation-percentage tracking. Matches MitigationBlocksPlugin''s InputSpec(lookback=10). Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.fvg.lookback', 'int', '100', 30, 500, NULL, false, 1, '[conventional] Trailing bar window scanned for 3-candle fair-value-gap imbalances. Matches FairValueGapPlugin''s InputSpec(lookback=100). Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('alpha.quant.cross_symbol_corroboration.min_symbols', 'int', '4', 2, 20, NULL, false, 1, '[initial_estimate] Minimum distinct symbols (including the subject itself) showing an implausible move near the same (tf, bar_ts) to treat a price-sanity-flagged return as a corroborated real market event (Flash Crash, ETF flash crash) rather than a corrupt print (todo 152). "Near" is consumer-specific: ops_known_corrupt_print_cleanup.py matches at the identical timestamp; services/forward_return_writer.py matches within alpha.quant.cross_symbol_corroboration.window_minutes (migration 241) -- an identical-timestamp match was tried there first and empirically failed (see 241). Not an ML learning target.', '2026-07-20 07:38:21.17118+00');
INSERT INTO public.config_schema VALUES ('alpha.quant.price_sanity.magnitude_threshold', 'float', '10.0', 2, 100, NULL, false, 1, '[initial_estimate] Order-of-magnitude ratio vs. neighbor reference price to flag an OHLC field implausible (todo 149/151). Carries forward classify_candidate_bar()''s existing CLI default verbatim, validated against real corrupt prints and the Flash Crash cluster. Used by src/intelligence/statistics/price_sanity.py classify_candidate_bar() -- both the BarAuditor live audit task and the ad hoc (CLI-overridable) ops_known_corrupt_print_cleanup.py script. Not an ML learning target.', '2026-07-20 15:44:43.083277+00');
INSERT INTO public.config_schema VALUES ('alpha.quant.price_sanity.neighbor_agreement_threshold', 'float', '2.0', 1.1, 10, NULL, false, 1, '[initial_estimate] Max ratio between prev_close and next_open for the two neighbor bars to be trusted as a reference (todo 149/151). Carries forward classify_candidate_bar()''s existing CLI default verbatim. Not an ML learning target.', '2026-07-20 15:44:43.083277+00');
INSERT INTO public.config_schema VALUES ('infra.bar_auditor.price_sanity_batch_size', 'int', '500', 50, 5000, NULL, false, 1, '[initial_estimate] Max unaudited bars BarAuditor''s price-sanity task classifies per audit tick (todo 149). Bounds per-cycle cost independent of total backlog size -- a large backlog (e.g. after a bulk historical backfill) drains over multiple ticks rather than blocking one cycle. Not an ML learning target.', '2026-07-20 15:44:43.083277+00');
INSERT INTO public.config_schema VALUES ('alpha.frame.min_stop_price_fraction', 'float', '0.001', 0, 0.05, NULL, false, 1, '[initial_estimate] FRAME-01/counterfactual_tracker: minimum stop_distance as a fraction of entry_price (todo 162). A stop_atr_mult * atr-derived stop below this fraction is treated as degenerate (same ValueError/skip path as atr <= 0) rather than scored -- prevents razor-thin ATR-derived stops on thin-absolute-volatility instruments from producing extreme counterfactual_pnl_r outliers (observed down to -926.87R). 0.10% seed is a conservative starting point against a smooth, non-bimodal extreme-frame-rate-vs-stop-distance% curve in the live corpus -- not overfit to a specific instrument. NOT an ML learning target (yet) -- candidate for future empirical recalibration once more corpus runs exist.', '2026-07-21 13:02:57.184159+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.feature_block_columns', 'int', '32', 4, 256, NULL, false, 1, '[initial_estimate] Number of feature columns processed per block in the feature-blocked rank/IC/CI/fold compute (_subsample_and_rank, services/ic_engine.py, todos 139/140). Bounds peak transient memory to O(n_sub x block) instead of O(n_sub x n_features) -- a peak-memory-vs-loop-overhead knob, not a statistical concept. Not an ML learning target.', '2026-07-23 02:44:11.017651+00');
INSERT INTO public.config_schema VALUES ('feature.smc.liquidity_sweeps.lookback', 'int', '120', 60, 500, NULL, false, 1, '[conventional] Trailing bar window scanned for liquidity sweeps of swing highs/lows. Matches LiquiditySweepsPlugin''s InputSpec(lookback=120). Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.cross_sectional_bootstrap_threads.15m', 'int', '1', 1, 16, NULL, false, 1, '[conventional] ThreadPoolExecutor size for the cross-sectional circular-block-bootstrap-CI re-rank+IC step at tf=15m. These cells finish in minutes serially; threading only adds dispatch overhead. See alpha.ic.cross_sectional_bootstrap_threads.5m for the shared methodology. Not an ML learning target.', '2026-07-23 02:44:13.53441+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.cross_sectional_bootstrap_threads.1h', 'int', '1', 1, 16, NULL, false, 1, '[conventional] ThreadPoolExecutor size for the cross-sectional circular-block-bootstrap-CI re-rank+IC step at tf=1h. These cells finish in minutes serially; threading only adds dispatch overhead. See alpha.ic.cross_sectional_bootstrap_threads.5m for the shared methodology. Not an ML learning target.', '2026-07-23 02:44:13.53441+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.cross_sectional_bootstrap_threads.1d', 'int', '1', 1, 16, NULL, false, 1, '[conventional] ThreadPoolExecutor size for the cross-sectional circular-block-bootstrap-CI re-rank+IC step at tf=1d. These cells finish in minutes serially; threading only adds dispatch overhead. See alpha.ic.cross_sectional_bootstrap_threads.5m for the shared methodology. Not an ML learning target.', '2026-07-23 02:44:13.53441+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.refresh_min_new_fraction', 'float', '0', 0, 1, NULL, false, 1, '[rca_analysis, disabled] Minimum fraction-of-new-bars below which a cell''s prior IC MAY be carried forward across a --training-window-end bump, instead of recomputed. Seeded 0 (disabled) -- at 0 every cell always recomputes on a window-end bump; zero behavior change until Plan 04''s drift study (ops_ic_fingerprint_equivalence.py --drift-study) justifies a nonzero value. Not an ML learning target. See services/ic_engine.py ICEngineConfig docstring.', '2026-07-23 02:44:18.717034+00');
INSERT INTO public.config_schema VALUES ('alpha.frame.stop_atr_mult.high_bear.5m', 'float', '1.5', 0.1, 10, NULL, false, 1, '[initial_estimate] Phase 166 scalar candidate: per-(regime,tf) stop-loss distance in ATR multiples. Seeded at the current global alpha.frame.stop_atr_mult (migration 214) value as a starting point -- overwritten by _calibrate_stop_target (EIC-scalar) after first champion weight_version run. NOT an ML learning target. Regime=high_bear, TF=5m.', '2026-07-23 11:53:06.584488+00');
INSERT INTO public.config_schema VALUES ('alpha.frame.target_r_multiple.high_bear.5m', 'float', '2.0', 0.1, 20, NULL, false, 1, '[initial_estimate] Phase 166 scalar candidate: per-(regime,tf) target R-multiple (reward:risk ratio) applied on top of the ATR-derived stop distance. Seeded at the current global alpha.frame.target_r_multiple (migration 214) value as a starting point -- overwritten by _calibrate_stop_target (EIC-scalar) after first champion weight_version run. NOT an ML learning target. Regime=high_bear, TF=5m.', '2026-07-23 11:53:06.584488+00');
