INSERT INTO public.config_schema VALUES ('alpha.frame.cluster_radius_atr', 'float', '0.5', 0.05, 5, NULL, false, 1, '[initial_estimate] Phase 166 structural candidate Part 1: ATR radius within which two structural candidates (VP POC/VAH/VAL, S/R) are grouped into one confluence cluster. Carried over from the archived confluence-scoring module''s equivalent constant (same value, narrower source universe). NOT an ML learning target.', '2026-07-23 11:53:06.584488+00');
INSERT INTO public.config_schema VALUES ('alpha.frame.single_level_radius_atr', 'float', '0.25', 0.05, 3, NULL, false, 1, '[initial_estimate] Phase 166 structural candidate Part 1: ATR radius used when scoring a single (non-clustered) structural candidate as the fallback tier. Carried over from the archived confluence-scoring module''s equivalent constant (same value). NOT an ML learning target.', '2026-07-23 11:53:06.584488+00');
INSERT INTO public.config_schema VALUES ('alpha.frame.zone_buffer_atr', 'float', '0.1', 0, 1, NULL, false, 1, '[initial_estimate] Phase 166 structural candidate Part 1: ATR buffer added around a resolved confluence zone''s outer bounds before deriving a stop/target price. Seeded narrower than the archived confluence-scoring module''s equivalent constant -- this candidate''s smaller (VP+S-R only) source universe produces tighter, less noisy clusters than the archived module''s full multi-source candidate table. NOT an ML learning target.', '2026-07-23 11:53:06.584488+00');
INSERT INTO public.config_schema VALUES ('alpha.frame.min_width_atr', 'float', '0.05', 0, 2, NULL, false, 1, '[initial_estimate] Phase 166 structural candidate Part 1: minimum confluence-zone width in ATR below which the zone is treated as a single point rather than a range. Seeded narrower than the archived confluence-scoring module''s equivalent constant, consistent with this candidate''s smaller (VP+S-R only) source universe and correspondingly tighter expected cluster widths. NOT an ML learning target.', '2026-07-23 11:53:06.584488+00');
INSERT INTO public.config_schema VALUES ('alpha.frame.strength_weight', 'float', '0.6', 0, 1, NULL, false, 1, '[initial_estimate] Phase 166 structural candidate Part 1: weight on candidate strength (vs. proximity) when scoring the single-best-candidate fallback tier. Carried over from the archived confluence-scoring module''s equivalent constant (same value). Paired with alpha.frame.proximity_weight; not independently bounds-checked to sum to 1.0. NOT an ML learning target.', '2026-07-23 11:53:06.584488+00');
INSERT INTO public.config_schema VALUES ('alpha.frame.proximity_weight', 'float', '0.4', 0, 1, NULL, false, 1, '[initial_estimate] Phase 166 structural candidate Part 1: weight on candidate proximity-to-entry (vs. strength) when scoring the single-best-candidate fallback tier. Carried over from the archived confluence-scoring module''s equivalent constant (same value). Paired with alpha.frame.strength_weight. NOT an ML learning target.', '2026-07-23 11:53:06.584488+00');
INSERT INTO public.config_schema VALUES ('alpha.frame.geometry_source', 'str', 'global', NULL, NULL, '{global,per_cell_scalar,structural}', false, 1, '[initial_estimate] Phase 166: selects which stop/target geometry AlphaFrameWriter derives per frame. "global" = current behavior, the single alpha.frame.stop_atr_mult/target_r_multiple scalars (backward-compatible, unconditional default). "per_cell_scalar" = the scalar candidate''s alpha.frame.stop_atr_mult.<regime>.<tf>/alpha.frame.target_r_multiple.<regime>.<tf> keys (Section 1). "structural" = the structural candidate Part 1''s confluence-resolved VP/S-R geometry (Section 3), falling back to ATR when no confluence level resolves. NOT an ML learning target -- an operator-visible switch flipped explicitly per candidate evaluation run.', '2026-07-23 11:53:06.584488+00');
INSERT INTO public.config_schema VALUES ('alpha.frame.structure_snap_proximity_atr', 'float', '1.5', 0.1, 5, NULL, false, 1, '[reserved, unused] Phase 166 structural candidate Part 1: seeded per the original plan alongside the other 6 structural-confluence thresholds, but no "snap to structural level" tier was implemented in structural_confluence.py''s 3-tier resolution (confluence -> single-best -> ATR fallback always returns the pure scalar seed unconditionally) -- code review finding WR-01 (166-REVIEW.md) traced the original description to a misreading of the archived trade_framer.py''s actual semantics there (a post-hoc stop_basis classification label, never a price transformation). Reserved for todo 175 (Part 2) to reconsider, not currently consumed by any code path. NOT an ML learning target.', '2026-07-23 11:53:06.584488+00');
INSERT INTO public.config_schema VALUES ('feature.session_vp.value_area_pct', 'float', '0.70', 0.1, 0.99, NULL, false, 1, '[conventional] Cumulative-volume fraction defining the session value area (VAH/VAL) in the ported ctx_VolumeProfile histogram. Standard market-profile convention. Phase 163. Not an ML learning target.', '2026-07-23 16:27:53.758563+00');
INSERT INTO public.config_schema VALUES ('feature.session_vp.n_buckets', 'int', '50', 10, 200, NULL, false, 1, '[conventional] Number of price buckets in the session volume-weighted histogram. Matches ctx_VolumeProfile''s existing default. Phase 163. Not an ML learning target.', '2026-07-23 16:27:53.758563+00');
INSERT INTO public.config_schema VALUES ('feature.session_vp.hvn_threshold', 'float', '0.80', 0.5, 0.99, NULL, false, 1, '[conventional] Volume-hist quantile threshold (top 20% by default) above which a bucket is classified a high-volume node (HVN). Matches ctx_VolumeProfile''s existing default. Phase 163. Not an ML learning target.', '2026-07-23 16:27:53.758563+00');
INSERT INTO public.config_schema VALUES ('feature.session_vp.lvn_threshold', 'float', '0.20', 0.01, 0.5, NULL, false, 1, '[conventional] Volume-hist quantile threshold (bottom 20% by default) at/below which a bucket is classified a low-volume node (LVN). Matches ctx_VolumeProfile''s existing default. Phase 163. Not an ML learning target.', '2026-07-23 16:27:53.758563+00');
INSERT INTO public.config_schema VALUES ('feature.sr.window', 'int', '10', 2, 50, NULL, false, 1, '[conventional] find_peaks/find_troughs pivot detection window for support/resistance clustering (Plan 03). Matches support_resistance.py''s existing default. Phase 163. Not an ML learning target.', '2026-07-23 16:27:53.758563+00');
INSERT INTO public.config_schema VALUES ('feature.sr.cluster_atr_mult', 'float', '0.5', 0.05, 5, NULL, false, 1, '[conventional] ATR multiple defining the pivot-clustering radius for support/resistance (Plan 03). Matches support_resistance.py''s existing default. Phase 163. Not an ML learning target.', '2026-07-23 16:27:53.758563+00');
INSERT INTO public.config_schema VALUES ('feature.sr.lookback_by_tf', 'json', '{"1m":60,"5m":60,"15m":80,"1h":120,"1d":60}', NULL, NULL, NULL, false, 1, '[conventional] Per-timeframe bounded lookback window (bars) for support/resistance clustering (Plan 03). Matches support_resistance.py''s existing _LOOKBACK_BY_TF shape. JSON dict keyed by tf string. Phase 163. Not an ML learning target.', '2026-07-23 16:27:53.758563+00');
INSERT INTO public.config_schema VALUES ('feature.session_vp.rolling_window', 'int', '480', 50, 2000, NULL, false, 1, '[conventional] Rolling-track window (bars) for the multi-day POC/VAH/VAL anchor (poc_rolling_dist_atr, poc_session_rolling_divergence_atr). Matches ctx_VolumeProfile''s documented _ROLLING_WINDOW. Backfill''s stateless bars[-N:] slicing genuinely reaches the full configured window against unbounded historical OHLCV. The LIVE pipeline is bounded by FeatureVectorPipeline''s BarHistory(maxlen=200) regardless of this value -- code review finding CR-02 (163-REVIEW.md) corrected the original migration 255 description''s claim that live "genuinely reaches the full 480-bar window," which was true only for backfill. Phase 163. Not an ML learning target.', '2026-07-23 16:27:53.758563+00');
INSERT INTO public.config_schema VALUES ('alpha.equity_regime.breadth_bear', 'float', NULL, 0, 1, NULL, false, 1, '[rca_analysis] Percentile-rank threshold (matches vix_pct''s own tercile construction, not a raw-fraction threshold) below which breadth is "bear". Recalibrated 2026-07-24 (todo 092): breadth_frac is now itself a causal expanding percentile rank before bucketing, same as vix_pct -- the old 0.40 was a guessed raw-fraction cut, never checked against the real distribution (measured median breadth_frac ~0.70-0.76, causing 12-17x population imbalance across regime cells). Changing this value changes every downstream market_regimes label -- requires a full historical regime recompute.', '2026-07-12 22:50:16.119721+00');
INSERT INTO public.config_schema VALUES ('alpha.equity_regime.breadth_bull', 'float', NULL, 0, 1, NULL, false, 1, '[rca_analysis] Percentile-rank threshold (matches vix_pct''s own tercile construction, not a raw-fraction threshold) above which breadth is "bull". Recalibrated 2026-07-24 (todo 092): breadth_frac is now itself a causal expanding percentile rank before bucketing, same as vix_pct -- the old 0.60 was a guessed raw-fraction cut, never checked against the real distribution (measured median breadth_frac ~0.70-0.76, causing 12-17x population imbalance across regime cells). Changing this value changes every downstream market_regimes label -- requires a full historical regime recompute.', '2026-07-12 22:50:16.119721+00');
INSERT INTO public.config_schema VALUES ('alpha.rates_regime.inverted_threshold', 'float', NULL, -5, 0, NULL, false, 1, '[rca_analysis] Percentile-rank threshold (matches vix_pct/breadth_pct''s tercile construction, not a raw z-score threshold) below which the curve is "inverted". Recalibrated 2026-07-24 (todo 092): curve_z is now itself a causal expanding percentile rank before bucketing, same as the equity breadth signal -- the old -0.5 was a guessed z-score cut, never checked against the real distribution (measured "flat" alone at ~86-87% of bars, vs. ~38% expected for a true N(0,1) z-score). Changing this value changes every downstream market_regimes label for regime_group=''rates'' -- requires a full historical regime recompute.', '2026-07-12 22:50:16.119721+00');
INSERT INTO public.config_schema VALUES ('alpha.rates_regime.steep_threshold', 'float', NULL, 0, 5, NULL, false, 1, '[rca_analysis] Percentile-rank threshold (matches vix_pct/breadth_pct''s tercile construction, not a raw z-score threshold) above which the curve is "steep". Recalibrated 2026-07-24 (todo 092): curve_z is now itself a causal expanding percentile rank before bucketing, same as the equity breadth signal -- the old 0.5 was a guessed z-score cut, never checked against the real distribution (measured "flat" alone at ~86-87% of bars, vs. ~38% expected for a true N(0,1) z-score). Changing this value changes every downstream market_regimes label for regime_group=''rates'' -- requires a full historical regime recompute.', '2026-07-12 22:50:16.119721+00');
INSERT INTO public.config_schema VALUES ('alpha.rates_regime.credit_tight_threshold', 'float', NULL, -5, 5, NULL, false, 1, '[rca_analysis] Percentile-rank median-split threshold (matches vix_pct/breadth_pct''s rank construction, not a raw z-score threshold) above which credit is "tight". Recalibrated 2026-07-24 (todo 092): credit_z is now itself a causal expanding percentile rank before bucketing -- the old 0.0 was a guessed z-score cut, never checked against the real distribution. Changing this value changes every downstream market_regimes label for regime_group=''rates'' -- requires a full historical regime recompute.', '2026-07-12 22:50:16.119721+00');
INSERT INTO public.config_schema VALUES ('alpha.construction.decile_fraction', 'float', '0.10', NULL, NULL, NULL, false, 1, '[initial_estimate] Phase 167: top/bottom fraction of the ranked equity universe forming each leg of the cross-sectional decile-spread construction -- matches T3''s validated _DECILE_FRACTION exactly. NOT an ML learning target.', '2026-07-27 04:17:32.526507+00');
INSERT INTO public.config_schema VALUES ('alpha.construction.cost_hurdle_bps_round_trip', 'json', '[1, 3, 5, 10]', NULL, NULL, NULL, false, 1, '[conventional] Phase 167: todo 030''s blended round-trip cost-floor sweep (bps), applied to this construction''s ACTUAL measured one-way turnover per bar (D-05) -- distinct from the flat, single-value alpha.quant.cost_hurdle.<tf> key (do not confuse the two; Pitfall 5). Seeded as a JSON array literal -- json.loads(config_value) must parse to the exact Python list [1, 3, 5, 10] of ints, never consumed via the generic cfg() str-cast helper.', '2026-07-27 04:17:32.526507+00');
INSERT INTO public.config_schema VALUES ('alpha.construction.null_shuffles', 'int', '40', NULL, NULL, NULL, false, 1, '[conventional] Phase 167: shuffled-ranking-null draw count for the construction''s gate evaluation, re-run on every --evaluate-gate invocation (unlike _DEFAULT_BOOTSTRAP_RANDOM_STATE, which stays a plain reused Python constant per RESEARCH.md) -- runtime cost is linear in this value, an operator will genuinely want to tune it. Matches T3''s validated _N_NULL_SHUFFLES. NOT an ML learning target.', '2026-07-27 04:17:32.526507+00');
INSERT INTO public.config_schema VALUES ('alpha.construction.attribution_max_static_r2', 'float', '0.50', NULL, NULL, NULL, false, 1, '[initial_estimate] Phase 167: Validation Gate 2''s ceiling for "a fixed leg-membership benchmark explains most of the spread''s return" -- above this R^2, the construction is judged a disguised static factor tilt rather than a genuine time-varying forecast. No prior empirical basis exists in this codebase for this specific ceiling; treat as a starting point pending live measurement, not a settled statistical result.', '2026-07-27 04:17:32.526507+00');
INSERT INTO public.config_schema VALUES ('infra.cross_sectional_spread_tracker.itersize', 'int', '5000', NULL, NULL, NULL, false, 1, '[conventional] Phase 167: psycopg2 named server-side cursor itersize for CrossSectionalSpreadTracker''s incremental corpus scan. Matches infra.counterfactual_tracker.itersize (migration 205) precedent. NOT an ML learning target.', '2026-07-27 04:17:32.526507+00');
INSERT INTO public.config_schema VALUES ('infra.cross_sectional_spread_tracker.chunk_size', 'int', '5000', NULL, NULL, NULL, false, 1, '[conventional] Phase 167: accumulate-and-flush chunk size for CrossSectionalSpreadTracker''s per-bar write pass. Matches infra.alpha_frame_writer.chunk_size''s precedent shape (migration 205), sized smaller here since this is a per-bar cross-sectional pass (one row per bar_ts), not a per-symbol anti-join pass. NOT an ML learning target.', '2026-07-27 04:17:32.526507+00');
INSERT INTO public.config_schema VALUES ('alpha.construction.null_p_threshold', 'float', '0.05', NULL, NULL, NULL, false, 1, '[conventional] Phase 167: Validation Gate 1''s shuffled-ranking-null significance level -- a scale''s null_p must be strictly below this value, at BOTH lookahead scales, for the binding gate1_passes verdict to be true (alongside the bootstrap CI clearing at the most conservative cost tier). Standard 5% two-sided significance convention; not an ML learning target.', '2026-07-27 12:24:53.362725+00');
INSERT INTO public.config_schema VALUES ('alert.lag.feature-vector-writer', 'int', '1000', 100, 10000, NULL, false, 1, '[initial_estimate] Consumer lag threshold for indicagent-feature-vector-writer (v3.0 FeatureVectorWriter, topic_feature_vectors -> feature_vectors). Replaces the mislabeled migration-103 alert.lag.feature-writer key, which pointed at the archived v2.x indicagent-feature-writer.service and masked this unit never being deployed. Same threshold value as bar-writer''s sibling key; not an ML learning target.', '2026-07-27 20:57:19.836462+00');
INSERT INTO public.config_schema VALUES ('alert.lag.feature-writer', 'int', '1000', NULL, NULL, NULL, false, 1, '[ORPHANED, migration 264] Superseded by alert.lag.feature-vector-writer -- this key was mislabeled at the archived v2.x indicagent-feature-writer.service (Redpanda -> intelligence_features, permanently dead) and masked the v3.0 FeatureVectorWriter never being deployed. No code path reads this key anymore.', '2026-05-29 22:22:51.030275+00');
INSERT INTO public.config_schema VALUES ('feature.hmm.n_components', 'int', '3', 2, 10, NULL, false, 1, '[rca_analysis] Number of hidden states in the GaussianHMM. BIC K-selection study (2026-06-26, migration 172) found K=5 minimizes BIC on SPY/TLT/GLD/EWT 5m data, unanimous across all 4 symbols -- superseded the prior K=3 [initial_estimate] default. Not an ML learning target (changes model topology, requires full retraining).', '2026-06-19 14:45:42.177928+00');
INSERT INTO public.config_schema VALUES ('feature.smc.order_blocks.lookback', 'int', '100', 50, 500, NULL, false, 1, '[conventional] Trailing bar window scanned for order-block impulse+opposing-candle detection. Matches OrderBlocksPlugin''s InputSpec(lookback=100). Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.order_blocks.impulse_bars', 'int', '3', 1, 10, NULL, false, 1, '[conventional] Minimum consecutive same-direction candles defining an impulsive move for order-block detection. Matches OrderBlocksPlugin.impulse_bars. Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.order_blocks.significant_move_pct', 'float', '0.003', 0.0001, 0.05, NULL, false, 1, '[conventional] Minimum impulse move size, as a fraction of current price, to qualify as significant. Matches OrderBlocksPlugin''s hardcoded 0.3% threshold. Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.order_blocks.opposing_candle_lookback', 'int', '10', 2, 50, NULL, false, 1, '[conventional] Bars scanned backward from an impulse''s start to find the last opposing candle (the order block itself). Matches OrderBlocksPlugin''s hardcoded range(...,10,...). Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.liquidity_sweeps.swing_neighbor', 'int', '5', 2, 20, NULL, false, 1, '[conventional] find_swing_highs/find_swing_lows neighbor window (bars on each side) for swing-point detection ahead of sweep scanning. Matches LiquiditySweepsPlugin.neighbor. Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.liquidity_sweeps.reclaim_bars', 'int', '3', 1, 20, NULL, false, 1, '[conventional] Bars checked after a sweep for reclaim confirmation (price continuing back through the swept level). Matches LiquiditySweepsPlugin.reclaim_bars. Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.liquidity_sweeps.depth_ramp_max_pct', 'float', '2.0', 0.1, 10, NULL, false, 1, '[conventional] Upper bound (percent depth) of the linear_ramp mapping sweep wick-beyond depth to bounded [0,1] sweep_strength. Matches LiquiditySweepsPlugin''s hardcoded linear_ramp(depth, 0, 2.0). Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.liquidity_sweeps.reclaim_velocity_ramp_max', 'float', '0.5', 0.05, 2, NULL, false, 1, '[conventional] Upper bound of the linear_ramp mapping 1/bars_to_reclaim to bounded [0,1] reclaim_velocity. Matches LiquiditySweepsPlugin''s hardcoded linear_ramp(..., 0, 0.5). Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.liquidity_pools.lookback', 'int', '150', 60, 500, NULL, false, 1, '[conventional] Trailing bar window scanned for liquidity-pool levels (equal-highs/lows, session H/L). Matches LiquidityPoolsPlugin''s InputSpec(lookback=150); the plugin''s separate 1d InputSpec (PWH/PWL/PDH/PDL) is descoped per 164-RESEARCH.md''s cross-timeframe-gap finding. Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.liquidity_pools.swing_neighbor', 'int', '5', 2, 20, NULL, false, 1, '[conventional] find_swing_highs/find_swing_lows neighbor window for equal-highs/equal-lows clustering. Matches LiquidityPoolsPlugin''s hardcoded n=5. Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.liquidity_pools.atr_fallback_pct', 'float', '0.002', 0.0001, 0.05, NULL, false, 1, '[conventional] Fallback ATR-as-fraction-of-price used only when the passed-in atr_val is non-positive. Matches LiquidityPoolsPlugin''s hardcoded current_price * 0.002 fallback. Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.liquidity_pools.equal_level_tolerance_atr_mult', 'float', '0.75', 0.05, 3, NULL, false, 1, '[conventional] ATR multiple defining the price-clustering tolerance for equal-highs/equal-lows grouping. Matches LiquidityPoolsPlugin''s hardcoded atr * 0.75. Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.liquidity_pools.session_bars', 'int', '390', 30, 1000, NULL, false, 1, '[conventional] Trailing bar count treated as "current session" for session-high/session-low pool levels (390 = one 1m RTH session). Matches LiquidityPoolsPlugin''s hardcoded high[-390:]. Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.liquidity_pools.significance_weights', 'json', '{"eq_highs_3":0.75,"eq_lows_3":0.75,"eq_highs_2":0.60,"eq_lows_2":0.60,"session_high":0.50,"session_low":0.50}', NULL, NULL, NULL, false, 1, '[conventional] Per-level-type significance weights for liquidity-pool selection (nearest-significant-level tie-break). Matches LiquidityPoolsPlugin''s _SIG dict, with pwh/pwl/pdh/pdl entries dropped (PWH/PWL/PDH/PDL descoped, no daily-bar access in compute()''s single-tf signature). JSON dict keyed by level-type string. Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.zones.lookback', 'int', '150', 60, 500, NULL, false, 1, '[conventional] Trailing bar window scanned for supply/demand zone (Rally-Base-Drop / Drop-Base-Rally) origins. Matches SupplyDemandZonesPlugin''s InputSpec(lookback=150). Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.zones.impulse_atr_mult', 'float', '1.5', 0.1, 10, NULL, false, 1, '[conventional] ATR multiple a close-to-close move must exceed to qualify as a zone-forming impulse. Matches SupplyDemandZonesPlugin.impulse_atr_mult. Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.zones.base_body_ratio', 'float', '0.5', 0.05, 1, NULL, false, 1, '[conventional] Maximum body/range ratio for a candle to qualify as part of a zone''s consolidation base. Matches SupplyDemandZonesPlugin.base_body_ratio. Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.zones.base_atr_mult', 'float', '1.0', 0.05, 10, NULL, false, 1, '[conventional] ATR multiple a base candle''s range must stay under to qualify as consolidation. Matches SupplyDemandZonesPlugin.base_atr_mult. Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.zones.max_base_bars', 'int', '5', 1, 30, NULL, false, 1, '[conventional] Maximum consecutive base candles scanned left of an impulse when forming a zone. Matches SupplyDemandZonesPlugin.max_base_bars. Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.zones.zone_height_cap_atr_mult', 'float', '2.5', 0.1, 10, NULL, false, 1, '[conventional] ATR multiple capping maximum zone height (prevents degenerate oversized zones). Matches SupplyDemandZonesPlugin.zone_height_cap. Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.zones.impulse_overlap_atr_mult', 'float', '0.4', 0.01, 5, NULL, false, 1, '[conventional] ATR multiple bounding the allowed high/low overlap between an impulse bar and its predecessor. Matches SupplyDemandZonesPlugin''s hardcoded atr * 0.4 overlap check. Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.zones.freshness_decay_k', 'float', '0.5', 0.01, 5, NULL, false, 1, '[conventional] Decay-rate constant k passed to freshness_decay(test_count, k) for zone freshness scoring. Matches SupplyDemandZonesPlugin''s hardcoded freshness_decay(zone.test_count, k=0.5). Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.zones.strength_premium_align_mult', 'float', '1.20', 1, 2, NULL, false, 1, '[conventional] Zone-strength multiplier applied when a demand/supply zone aligns with the discount/premium side of the current range. Matches SupplyDemandZonesPlugin''s hardcoded s * 1.20. Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.zones.strength_fvg_align_mult', 'float', '1.15', 1, 2, NULL, false, 1, '[conventional] Zone-strength multiplier applied when a fair-value-gap midpoint falls inside the zone. Matches SupplyDemandZonesPlugin''s hardcoded s * 1.15. Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.zones.age_penalty_floor', 'float', '0.70', 0.1, 1, NULL, false, 1, '[conventional] Minimum age-penalty multiplier floor for zone strength (oldest zones never decay below this). Matches SupplyDemandZonesPlugin''s hardcoded max(0.70, ...). Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.zones.age_penalty_window_bars', 'int', '200', 20, 2000, NULL, false, 1, '[conventional] Bar-age normalization window for the zone-strength age penalty. Matches SupplyDemandZonesPlugin''s hardcoded age / 200. Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.zones.age_penalty_max_pct', 'float', '0.30', 0.01, 1, NULL, false, 1, '[conventional] Maximum fractional age-penalty applied to zone strength as age approaches age_penalty_window_bars. Matches SupplyDemandZonesPlugin''s hardcoded * 0.30. Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.zones.max_tracked_zones', 'int', '5', 1, 20, NULL, false, 1, '[conventional] Maximum nearest zones per side (demand/supply) retained after sorting by distance. Matches SupplyDemandZonesPlugin''s hardcoded [:5] slice. Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.bos_choch.lookback', 'int', '120', 60, 500, NULL, false, 1, '[conventional] Trailing bar window scanned for break-of-structure / change-of-character swing breaks. Matches BOSCHoCHPlugin''s InputSpec(lookback=120). Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.bos_choch.swing_neighbor', 'int', '5', 2, 20, NULL, false, 1, '[conventional] find_swing_highs/find_swing_lows neighbor window for BOS/CHoCH swing-point detection. Matches BOSCHoCHPlugin.neighbor. Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.amd.lookback', 'int', '30', 2, 200, NULL, false, 1, '[conventional] Trailing bar window for AMD cycle overnight-range/manipulation state. Matches AMDCyclePlugin''s InputSpec(lookback=30). Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.amd.accum_start_utc_hour', 'int', '20', 0, 23, NULL, false, 1, '[conventional] UTC hour marking the start of the AMD Accumulation phase (20:00 UTC = 8pm ET overnight range start). Matches AMDCyclePlugin._ACCUM_START. Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.amd.accum_end_utc_hour', 'int', '24', 1, 24, NULL, false, 1, '[conventional] UTC hour marking the end of the AMD Accumulation phase (24 = wraps at midnight UTC). Matches AMDCyclePlugin._ACCUM_END. Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.amd.manip_end_utc_hour', 'int', '10', 0, 23, NULL, false, 1, '[conventional] UTC hour marking the end of the AMD Manipulation phase (00:00-10:00 UTC = midnight-5am ET). Matches AMDCyclePlugin._MANIP_END. Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.smc.amd.dist_end_utc_hour', 'int', '21', 0, 23, NULL, false, 1, '[conventional] UTC hour marking the end of the AMD Distribution phase (10:00-21:00 UTC = 5am-4pm ET). Matches AMDCyclePlugin._DIST_END. Phase 164. Not an ML learning target.', '2026-07-28 01:30:56.306277+00');
INSERT INTO public.config_schema VALUES ('feature.swing.pivot_window', 'int', '5', 2, 50, NULL, false, 1, '[conventional] find_peaks/find_troughs pivot detection neighbor window, shared by swing_detector.py AND trend_structure.py (same underlying call, same value, Plan 02). Deliberately NOT unified with feature.sr.window=10 (Phase 163), which scopes a different S/R clustering operation. Matches the archived plugins'' own neighbor=5 default. Phase 165. Not an ML learning target.', '2026-07-28 07:22:59.271806+00');
INSERT INTO public.config_schema VALUES ('feature.swing.lookback_bars', 'int', '120', 20, 1000, NULL, false, 1, '[conventional] Bounded causal lookback window (bars) for the shared swing-detection pivot pass (Plan 02). Matches the archived swing_detector.py''s InputSpec(lookback=120). Phase 165. Not an ML learning target.', '2026-07-28 07:22:59.271806+00');
INSERT INTO public.config_schema VALUES ('feature.trend_structure.atr_strength_divisor', 'float', '5.0', 0.5, 50, NULL, false, 1, '[conventional] Divisor in trend_strength = dominant_fraction * (price_range/ATR) / divisor (Plan 02). Matches the archived trend_structure.py''s hardcoded 5.0 divisor. Phase 165. Not an ML learning target.', '2026-07-28 07:22:59.271806+00');
INSERT INTO public.config_schema VALUES ('feature.trend_structure.range_lookback_bars', 'int', '20', 5, 200, NULL, false, 1, '[conventional] Bar window for the high[-N:]/low[-N:] price-range component of trend_strength''s ATR normalization (Plan 02) -- a second, independent hardcoded constant in trend_structure.py that 165-RESEARCH.md''s Finding A found the prior survey missed (separate from the 5.0 divisor and from feature.swing.pivot_window). Matches the archived file''s hardcoded high[-20:]/low[-20:] slice. Phase 165. Not an ML learning target.', '2026-07-28 07:22:59.271806+00');
INSERT INTO public.config_schema VALUES ('feature.swing_momentum.confirm_n', 'int', '3', 1, 20, NULL, false, 1, '[conventional] Confirmation-bar count for swing_momentum.py''s own hand-rolled _detect_extremes() (Plan 03) -- deliberately separate from feature.swing.pivot_window (D-06/RESEARCH Finding B: different algorithm, self-contained by design per the archived plugin''s own docstring). Matches the archived plugin''s _CONFIRM_N=3. Phase 165. Not an ML learning target.', '2026-07-28 07:22:59.271806+00');
INSERT INTO public.config_schema VALUES ('feature.swing_momentum.max_extremes', 'int', '6', 4, 20, NULL, false, 1, '[conventional] Maximum tracked swing extremes for swing_momentum.py (Plan 03). MUST stay EVEN -- represents complete swings (6 = 3 complete swings, an unpaired trailing extreme would be a half-swing). Matches the archived plugin''s _MAX_EXTREMES=6. Phase 165. Not an ML learning target.', '2026-07-28 07:22:59.271806+00');
INSERT INTO public.config_schema VALUES ('feature.swing_momentum.lookback_bars', 'int', '60', 20, 1000, NULL, false, 1, '[conventional] Bounded causal lookback window (bars) for swing_momentum.py''s _detect_swing_extremes (Plan 03). Matches the archived plugin''s min_lookback/InputSpec(lookback=60). Phase 165. Not an ML learning target.', '2026-07-28 07:22:59.271806+00');
INSERT INTO public.config_schema VALUES ('feature.swing_momentum.reference_bars', 'int', '20', 1, 200, NULL, false, 1, '[conventional] Reference-window bar count for swing_momentum.py''s velocity/reference calculations (Plan 03). Matches the archived plugin''s _REFERENCE_BARS=20. Phase 165. Not an ML learning target.', '2026-07-28 07:22:59.271806+00');
INSERT INTO public.config_schema VALUES ('feature.swing_momentum.speed_factor_min', 'float', '0.1', 0.01, 10, NULL, false, 1, '[conventional] Lower clamp bound for swing_momentum.py''s speed_factor (Plan 03). Matches the archived plugin''s clamp(..., 0.1, 3.0). Phase 165. Not an ML learning target.', '2026-07-28 07:22:59.271806+00');
INSERT INTO public.config_schema VALUES ('feature.swing_momentum.speed_factor_max', 'float', '3.0', 0.1, 100, NULL, false, 1, '[conventional] Upper clamp bound for swing_momentum.py''s speed_factor (Plan 03). Matches the archived plugin''s clamp(..., 0.1, 3.0). Phase 165. Not an ML learning target.', '2026-07-28 07:22:59.271806+00');
INSERT INTO public.config_schema VALUES ('feature.swing_momentum.energy_divisor', 'float', '3.0', 0.1, 100, NULL, false, 1, '[conventional] Divisor in struct_energy = clamp(amplitude_ratio * speed_factor / divisor, 0, 1) (Plan 03). Matches the archived plugin''s hardcoded /3.0 divisor. Phase 165. Not an ML learning target.', '2026-07-28 07:22:59.271806+00');
INSERT INTO public.config_schema VALUES ('feature.swing_momentum.intensity_ramp_lo', 'float', '1.0', 0, 100, NULL, false, 1, '[conventional] Lower bound of the linear_ramp mapping amplitude_ratio to bounded [0,1] swing_amplitude_intensity (Plan 03). Matches the archived plugin''s linear_ramp(amplitude_ratio, 1.0, 2.0). Phase 165. Not an ML learning target.', '2026-07-28 07:22:59.271806+00');
INSERT INTO public.config_schema VALUES ('feature.swing_momentum.intensity_ramp_hi', 'float', '2.0', 0, 100, NULL, false, 1, '[conventional] Upper bound of the linear_ramp mapping amplitude_ratio to bounded [0,1] swing_amplitude_intensity (Plan 03). Matches the archived plugin''s linear_ramp(amplitude_ratio, 1.0, 2.0). Phase 165. Not an ML learning target.', '2026-07-28 07:22:59.271806+00');
INSERT INTO public.config_schema VALUES ('feature.fib.cluster_atr_divisor', 'float', '2.0', 0.1, 100, NULL, false, 1, '[conventional] ATR divisor defining the fib-level clustering threshold for fib_cluster_strength (Plan 03). Matches the archived fibonacci_zones.py''s hardcoded atr_14 / 2.0. Phase 165. Not an ML learning target.', '2026-07-28 07:22:59.271806+00');
INSERT INTO public.config_schema VALUES ('feature.fib.cluster_fallback_divisor', 'float', '20.0', 0.1, 1000, NULL, false, 1, '[conventional] Fallback divisor for the fib-clustering threshold, used only when ATR is unavailable (Plan 03). Matches the archived fibonacci_zones.py''s hardcoded swing_range / 20.0. Phase 165. Not an ML learning target.', '2026-07-28 07:22:59.271806+00');
INSERT INTO public.config_schema VALUES ('feature.session_levels.asia_start_et_hour', 'int', '20', 0, 23, NULL, false, 1, '[conventional] ET hour marking the start of the Asian trading session (Plan 04). Matches the archived session_levels.py''s hour-mask constant (20:00 ET). Phase 165. Not an ML learning target.', '2026-07-28 07:22:59.271806+00');
INSERT INTO public.config_schema VALUES ('feature.session_levels.asia_end_et_hour', 'int', '4', 0, 23, NULL, false, 1, '[conventional] ET hour marking the end of the Asian trading session (Plan 04). Matches the archived session_levels.py''s hour-mask constant (04:00 ET). Phase 165. Not an ML learning target.', '2026-07-28 07:22:59.271806+00');
INSERT INTO public.config_schema VALUES ('feature.smc.order_blocks.strength_fallback', 'float', '0.5', 0, 1, NULL, false, 1, '[conventional] ob_strength fallback when avg_volume <= 0 (degenerate/empty volume window) in _compute_order_blocks -- neutral midpoint of the [0,1] strength range. Not an ML learning target: this is a rare degenerate-input guard, not a calibrated signal weight. Phase 164 migration 266 shipped this as a hardcoded 0.5 literal; this migration only adds APR plumbing around the existing value.', '2026-07-28 12:33:35.148998+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.active_scales.5m', 'json', NULL, NULL, NULL, NULL, false, 1, '[rca_analysis] JSON array of scale names ic_engine.py attempts computation for on 5m -- subset of ["fast","mid","slow","extended"]. All four active; 5m has no measured completeness collapse at any tier (see todo 146''s full-corpus diagnostic). Order in the array is not meaningful -- canonicalized to fast, mid, slow, extended order at load time regardless of how written here.', '2026-07-30 14:06:47.170956+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.active_scales.15m', 'json', NULL, NULL, NULL, NULL, false, 1, '[rca_analysis] JSON array of scale names ic_engine.py attempts computation for on 15m. Same rationale as 5m -- all four active.', '2026-07-30 14:06:47.170956+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.active_scales.1d', 'json', NULL, NULL, NULL, NULL, false, 1, '[rca_analysis] JSON array of scale names ic_engine.py attempts computation for on 1d. Same rationale as 5m -- all four active (1d has no session-boundary gate at all, per forward_return_writer.py).', '2026-07-30 14:06:47.170956+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.active_scales.1h', 'json', NULL, NULL, NULL, NULL, false, 1, '[rca_analysis] JSON array of scale names ic_engine.py attempts computation for on 1h -- subset of ["fast","mid","slow","extended"]. All four active (reverted 2026-07-30, migration 272): the earlier slow/extended exclusion (migration 271) was caused by forward_return_writer.py''s same-ET-session completeness gate, which has since been removed (todo 208) -- not a property of 1h itself. Order in the array is not meaningful -- canonicalized to fast, mid, slow, extended order at load time regardless of how written here.', '2026-07-30 14:06:47.170956+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.cross_sectional_bootstrap_threads.5m', 'int', '6', 1, 16, NULL, false, 1, '[initial_estimate] ThreadPoolExecutor size for the cross-sectional circular-block-bootstrap-CI re-rank+IC step at tf=5m (services/ic_engine.py, todo 133). 5m cross-sectional cells are the largest (up to ~599K rows) and benefit from threaded dispatch. Cross-sectional pass ONLY -- this key does not apply to the per-symbol path, which has its own sibling key (infra.ic_engine.per_symbol_bootstrap_threads.{tf}, migration 273). CORRECTED 2026-07-30 (todo 215): this description previously claimed threading the per-symbol path "would oversubscribe cores instead of speeding anything up" as settled fact -- that was asserted, never measured, and a live isolated-single-worker benchmark of the structurally equivalent per-symbol bootstrap found the opposite (real 2-6x speedup, GIL released by scipy rankdata/argsort). Thread count changes wall time only, never output (162-01 precomputed resample-index matrix). Not an ML learning target.', '2026-07-23 02:44:13.53441+00');
INSERT INTO public.config_schema VALUES ('infra.signal_auditor.audit_interval_seconds', 'int', '300', 10, 3600, NULL, false, 1, '[initial_estimate] Seconds between signal_auditor.py audit cycles during market hours. Pure infrastructure cadence knob. Not an ML learning target.', '2026-07-31 15:04:30.502318+00');
INSERT INTO public.config_schema VALUES ('feature.hmm.min_obs_factor', 'int', '50', 10, 1000, NULL, false, 1, '[initial_estimate] Minimum obs-row multiplier for regime_writer.py''s HMM fit gate: min_rows = n_components * min_obs_factor. Below this, the fit is meaningless (too few state transitions to estimate the transition matrix). Raising this makes the fit more conservative (skips more thin symbol/tf cells); lowering it risks fitting HMMs on insufficient data. Not an ML learning target -- a data-sufficiency gate, not a model parameter. Domain is feature.hmm.* (matches the other 10 HMM tunables regime_writer.py reads in the same block -- n_components, vol_window, full_cov_min_obs, etc.), not alpha.hmm.* (reserved for alpha.hmm.random_state, the one HMM key that specifically invalidates downstream alpha outputs when changed). min_value floored at 10, not 1 -- a multiplier of 1 would let min_rows collapse to n_components alone, defeating the gate the key exists to enforce.', '2026-07-31 15:52:45.952363+00');
INSERT INTO public.config_schema VALUES ('infra.ibkr.rate_limit_max_requests', 'int', '55', 1, 60, NULL, false, 1, '[conventional] Max historical-data requests _SlidingWindowRateLimiter allows within the sliding window before pre-emptively sleeping. IBKR enforces a hard ceiling of 60 requests per 10-minute window (Error 162 "query cancelled" on breach); 55 is a conservative 5-slot buffer absorbing jitter. Not an ML learning target.', '2026-07-31 22:04:12.336858+00');
INSERT INTO public.config_schema VALUES ('infra.ibkr.rate_limit_window_sec', 'float', '600.0', 60, 3600, NULL, false, 1, '[conventional] Sliding-window duration (seconds) _SlidingWindowRateLimiter tracks request timestamps over, matching IBKR''s documented 10-minute pacing period. Not an ML learning target.', '2026-07-31 22:04:12.336858+00');
INSERT INTO public.config_schema VALUES ('feature.factor_beta.window', 'int', '60', 10, 500, NULL, false, 1, '[conventional] Rolling OLS window (bars) shared by both equity_beta_z and rate_beta_z (same statistic, different factor series). "factor_beta" naming (not bare "beta") avoids the glossary''s ban on an unqualified "beta" term. Phase 151. ML learning target: yes.', '2026-08-05 13:09:31.373779+00');
INSERT INTO public.config_schema VALUES ('feature.factor_beta.zscore_window', 'int', '252', 20, 2520, NULL, false, 1, '[conventional] Z-score window (bars) shared by both equity_beta_z and rate_beta_z. Phase 151. ML learning target: yes.', '2026-08-05 13:09:31.373779+00');
INSERT INTO public.config_schema VALUES ('alpha.hmm.walk_forward.initial_warmup_bars.5m', 'int', '39600', 100, 400000, NULL, false, 1, '[initial_estimate] todo 248: bars of history required before the first walk-forward HMM fit at 5m (~2yr at 5m density). See migration 292 header. Not an ML learning target.', '2026-08-05 17:31:38.424279+00');
INSERT INTO public.config_schema VALUES ('alpha.hmm.walk_forward.refit_every_bars.15m', 'int', '6600', 100, 100000, NULL, false, 1, '[rca_analysis] todo 248: bars between walk-forward HMM refits at 15m. Independently re-piloted and confirmed (SPY/15m: 56.8% label agreement vs 22.1% chance baseline, +34.8 points above chance, 0 sign flips) -- see docs/analysis/hmm-parameter-lookahead-pilot-spy-1h.md. Not an ML learning target.', '2026-08-05 17:31:38.424279+00');
INSERT INTO public.config_schema VALUES ('alpha.hmm.walk_forward.initial_warmup_bars.15m', 'int', '13200', 100, 200000, NULL, false, 1, '[rca_analysis] todo 248: bars of history required before the first walk-forward HMM fit at 15m (~2yr at 15m density). Same pilot confirmation as refit_every_bars.15m. Not an ML learning target.', '2026-08-05 17:31:38.424279+00');
INSERT INTO public.config_schema VALUES ('alpha.hmm.walk_forward.refit_every_bars.1h', 'int', '1650', 100, 50000, NULL, false, 1, '[rca_analysis] todo 248: bars between walk-forward HMM refits at 1h (~1 trading year). Directly measured by the Gate 4 pilot (SPY/1h, TLT/1h): full-history-vs-walk-forward label agreement 24.9% vs 21.7% chance baseline -- see docs/analysis/hmm-parameter-lookahead-pilot-spy-1h.md. Not an ML learning target.', '2026-08-05 17:31:38.424279+00');
INSERT INTO public.config_schema VALUES ('feature.factory.target_timeframes', 'json', '["5m", "15m", "1h", "1d"]', NULL, NULL, NULL, false, 1, '[conventional] JSON array of timeframes services/backfill_feature_factory.py processes -- drives _load_status_map() and both the fetch and compute stage loops. 1m intentionally excluded (live FeatureVectorPipeline owns 1m, not this batch job -- confirmed intentional, todo 199). Matches the long-standing hardcoded _TARGET_TIMEFRAMES module constant this key replaces. Not an ML learning target.', '2026-07-31 23:19:15.374854+00');
INSERT INTO public.config_schema VALUES ('infra.blas_threads_per_worker', 'int', '1', 1, 24, NULL, false, 1, '[rca_analysis] Per-ProcessPoolExecutor-worker OpenBLAS/OpenMP thread cap, applied via services/_batch_utils.py make_worker_pool()/limit_blas_threads() (threadpoolctl.threadpool_limits()) in each worker''s initializer=. Shared by regime_writer.py, ic_engine.py, ensemble_ic_engine.py, counterfactual_tracker.py, backfill_feature_factory.py. Without this, each worker process defaults to using all logical cores'' worth of BLAS threads, oversubscribing N-worker pools by ~Nx. Measured (todo 216): a representative GaussianHMM fit ran 2.5x slower at the unthreaded default than at threads=1, in complete isolation. Also empirically confirmed non-COMPUTATIONAL: threads=1 vs threads=24 on an identical fit produced byte-identical discrete state labels despite ~1e-10 floating-point noise in the raw model parameters. Default 1 is correct because process-level parallelism (infra.*.workers) already provides the real parallelism; raising this only makes sense alongside a corresponding drop in worker count, and should be re-benchmarked before changing, not guessed. Not an ML learning target.', '2026-08-02 12:07:01.387065+00');
INSERT INTO public.config_schema VALUES ('infra.compression_auditor.check_interval_seconds', 'int', '21600', 600, 86400, NULL, false, 1, '[initial_estimate] How often CompressionAuditor runs its ground-truth drift check (timescaledb_information.chunks vs. each hypertable''s compress_after policy). 6h default: catalog-only query, cheap to run often; same-day detection of the todo-233 failure mode. Not an ML learning target.', '2026-08-03 02:58:51.170763+00');
INSERT INTO public.config_schema VALUES ('infra.compression_auditor.grace_period_hours', 'int', '24', 12, 168, NULL, false, 1, '[initial_estimate] Extra time past compress_after before a chunk is flagged as overdue, absorbing ordinary compression-policy scheduling jitter (all policies run on a 12h schedule_interval as of this migration). Not an ML learning target.', '2026-08-03 02:58:51.170763+00');
INSERT INTO public.config_schema VALUES ('alert.lag.compression-auditor', 'int', '1000', 100, 10000, NULL, false, 1, '[initial_estimate] Consumer lag threshold for indicagent-compression-auditor. This daemon consumes no Kafka topic (pure DB-only auditor) -- the threshold governs how stale agent_last_message_timestamp_seconds may get before service_auditor flags it, same mechanism as every other unit in _AGENT_ID_TO_UNIT. Not an ML learning target.', '2026-08-03 02:58:51.170763+00');
INSERT INTO public.config_schema VALUES ('feature.momentum_velocity.window', 'int', '14', 2, 200, NULL, false, 1, '[conventional] Bar-lag window for the first-difference-then-z-score construction behind momentum_z_velocity_fast/mid/slow. Seeded to match feature.vol_velocity.window''s live value (14). Phase 151. ML learning target: yes.', '2026-08-05 10:16:44.195403+00');
INSERT INTO public.config_schema VALUES ('feature.vwap_velocity.window', 'int', '14', 2, 200, NULL, false, 1, '[conventional] Bar-lag window for vwap_dev_sigma_velocity. Separate key from feature.vol_velocity.window / feature.momentum_velocity.window per naming-system.md section 7 (semantically distinct family). Phase 151. ML learning target: yes.', '2026-08-05 10:16:44.195403+00');
INSERT INTO public.config_schema VALUES ('feature.bars_since_extreme_move.sigma_threshold', 'float', '2.0', 0.5, 10, NULL, false, 1, '[conventional] Multiple of the rolling standard deviation of abs(log return) above which a bar counts as an extreme-move event for bars_since_extreme_move_fast/slow. Phase 151. ML learning target: yes.', '2026-08-05 12:19:10.752512+00');
INSERT INTO public.config_schema VALUES ('feature.bars_since_vol_spike.threshold', 'float', '2.0', 1, 20, NULL, false, 1, '[conventional] rel_volume level above which a bar counts as a volume-spike event for bars_since_vol_spike_fast/slow. Phase 151. ML learning target: yes.', '2026-08-05 12:19:10.752512+00');
INSERT INTO public.config_schema VALUES ('feature.tip_tlt.zscore_window', 'int', '252', 20, 2520, NULL, false, 1, '[conventional] Z-score window (bars) for tip_tlt_ret_z (TIPS/nominal Treasury spread proxy). Phase 151. ML learning target: yes.', '2026-08-05 13:09:31.373779+00');
INSERT INTO public.config_schema VALUES ('feature.hyg_lqd.zscore_window', 'int', '252', 20, 2520, NULL, false, 1, '[conventional] Z-score window (bars) for hyg_lqd_ret_z (high-yield/investment-grade credit spread proxy). Phase 151. ML learning target: yes.', '2026-08-05 13:09:31.373779+00');
INSERT INTO public.config_schema VALUES ('feature.sb_corr.window_fast', 'int', '30', 5, 250, NULL, false, 1, '[conventional] Fast rolling window (bars) for sb_corr_fast (SPY/TLT log-return correlation). Phase 151. ML learning target: yes.', '2026-08-05 13:09:31.373779+00');
INSERT INTO public.config_schema VALUES ('feature.sb_corr.window_slow', 'int', '60', 10, 500, NULL, false, 1, '[conventional] Slow rolling window (bars) for sb_corr_slow (SPY/TLT log-return correlation). Phase 151. ML learning target: yes.', '2026-08-05 13:09:31.373779+00');
INSERT INTO public.config_schema VALUES ('feature.sb_corr.zscore_window', 'int', '252', 20, 2520, NULL, false, 1, '[conventional] Z-score window (bars) for sb_corr_z (z-scores sb_corr_fast). Phase 151. ML learning target: yes.', '2026-08-05 13:09:31.373779+00');
INSERT INTO public.config_schema VALUES ('alpha.hmm.walk_forward.refit_every_bars.5m', 'int', '19800', 100, 200000, NULL, false, 1, '[initial_estimate] todo 248: bars between walk-forward HMM refits at 5m. Scaled from the 1h pilot''s directly-measured value by 5m''s bar-density ratio (12x), following the same scaling logic 15m''s value independently confirmed -- NOT itself re-piloted at 5m. See migration 292 header. Not an ML learning target (calibrates measurement methodology, not a model parameter).', '2026-08-05 17:31:38.424279+00');
INSERT INTO public.config_schema VALUES ('alpha.hmm.walk_forward.initial_warmup_bars.1h', 'int', '3300', 100, 100000, NULL, false, 1, '[rca_analysis] todo 248: bars of history required before the first walk-forward HMM fit at 1h (~2 trading years). Same pilot as refit_every_bars.1h. Not an ML learning target.', '2026-08-05 17:31:38.424279+00');
INSERT INTO public.config_schema VALUES ('alpha.hmm.walk_forward.refit_every_bars.1d', 'int', '252', 20, 5000, NULL, false, 1, '[initial_estimate] todo 248: bars between walk-forward HMM refits at 1d (~1 trading year at daily density). Fresh, UNPILOTED estimate -- no broadened-pilot measurement exists at this tf, the least-certain of the four calibrated tfs. See migration 292 header. Not an ML learning target.', '2026-08-05 17:31:38.424279+00');
INSERT INTO public.config_schema VALUES ('alpha.hmm.walk_forward.initial_warmup_bars.1d', 'int', '504', 20, 10000, NULL, false, 1, '[initial_estimate] todo 248: bars of history required before the first walk-forward HMM fit at 1d (~2 trading years at daily density). Same unpiloted-estimate caveat as refit_every_bars.1d. Not an ML learning target.', '2026-08-05 17:31:38.424279+00');
INSERT INTO public.config_schema VALUES ('feature.atr_normalization.min_atr_pct', 'float', '0.0001', 0, 0.01, NULL, false, 1, '[conventional] Floor on atr_val as a fraction of close_ for every ATR-normalized distance feature in feature_factory.py (_is_valid_atr, todo 237). atr_val below min_atr_pct * abs(close_) is treated as invalid, same as atr_val <= 0, preventing a legitimately-positive but numerically-tiny ATR from exploding a normalized distance (confirmed live: weekly_r1_dist_atr up to 96,512 during a genuinely flat BIL period). Relative (not absolute), so it holds across instruments at any price scale. ML learning target: yes -- an ML tuner may find a higher floor better separates real flat-period degeneracy from ordinary low-volatility bars.', '2026-08-05 19:35:43.100023+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.bootstrap_early_stop.enabled', 'bool', 'false', NULL, NULL, NULL, false, 1, '[initial_estimate] Gate for adaptive early-stop on _blocked_bootstrap_ci''s resample loop (services/ic_engine.py, todo 227). false (seeded default) is byte-identical to the pre-todo-227 fixed-bootstrap_resamples behavior. Flipping true is a genuine behavior change (approximate ci_lower/ci_upper, fewer resamples on cells that converge early) -- a separate, later, explicit deployment decision requiring its own corpus re-run, not forced by this migration. Bit-identical reproducibility confirmed NOT load-bearing for this CI (every downstream consumer reads it as a threshold/sign gate, never an exact run-to-run value) -- see this migration''s header. Not an ML learning target.', '2026-08-05 23:57:51.638337+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.bootstrap_early_stop.check_interval', 'int', '200', 10, 2000, NULL, false, 1, '[initial_estimate] Recompute and check the running ci_lower/ci_upper estimate every this-many additional resamples once early-stop is enabled. Smaller = checks more often (more overhead, stops closer to the true convergence point); larger = fewer checks (less overhead, may overshoot by up to this many wasted resamples). Not benchmarked -- see this migration''s header. Not an ML learning target.', '2026-08-05 23:57:51.638337+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.bootstrap_early_stop.tol', 'float', '0.002', 0, 1, NULL, false, 1, '[initial_estimate] Max absolute change in ci_lower/ci_upper (elementwise across a feature block) between consecutive checkpoints to count as "stable." An order of magnitude tighter than this corpus''s typical ~0.02-0.05 IC magnitude, chosen conservatively pending real convergence data (todo 227). Not an ML learning target.', '2026-08-05 23:57:51.638337+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.bootstrap_early_stop.min_resamples', 'int', '200', 10, 2000, NULL, false, 1, '[initial_estimate] Never stop early before at least this many resamples have been computed, regardless of how quickly the estimate appears to stabilize -- guards against a lucky-noise false stop on very few draws. Not an ML learning target.', '2026-08-05 23:57:51.638337+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.bootstrap_early_stop.stable_checks', 'int', '2', 1, 10, NULL, false, 1, '[initial_estimate] Require this many CONSECUTIVE checkpoints within tol before actually stopping -- guards against stopping on a single-checkpoint fluke. Not an ML learning target.', '2026-08-05 23:57:51.638337+00');
INSERT INTO public.config_schema VALUES ('feature.ctf.higher_tf_map', 'json', '{"5m": "1h", "15m": "1h", "1h": "1d", "1d": "1d"}', NULL, NULL, NULL, false, 1, '[conventional] JSON object mapping source timeframe -> higher timeframe (HTF) used to compute ctf_momentum/ctf_vwap_align/ctf_regime_align. Single source of truth for both services/backfill_feature_factory.py''s batch path and services/feature_vector_pipeline.py''s live path -- both read it via FeatureFactoryConfig.ctf_higher_tf_map, never a hardcoded dict. "1d" is deliberately self-referential (no timeframe above 1d exists in this corpus). Matches the long-standing hardcoded feature_cache._CTF_HIGHER_TF module constant this key replaces. Not an ML learning target.', '2026-08-07 11:22:45.773619+00');
INSERT INTO public.config_schema VALUES ('alpha.commodity_regime.momentum_window', 'int', '60', NULL, NULL, NULL, false, 1, '[conventional] Rolling window, in DAILY bars, for the unified commodity group''s momentum z-score. Scaled to the target TF via _tf_window(daily, tf) at compute time. Consolidated from the identical commodity_energy/metals/agri values by migration 306.', '2026-08-07 13:27:16.570957+00');
INSERT INTO public.config_schema VALUES ('alpha.commodity_regime.primary_threshold', 'float', '0.75', NULL, NULL, NULL, false, 1, '[initial_estimate] Unified commodity group up_primary/down_primary threshold. Consolidated from the identical commodity_energy/metals/agri values by migration 306. Candidate ML target.', '2026-08-07 13:27:16.570957+00');
INSERT INTO public.config_schema VALUES ('alpha.regime.groups', 'json', NULL, NULL, NULL, NULL, false, 1, '[initial_estimate] JSON array of regime group configs. Each entry: {"name": str, "tag_filter": [str], "signal_type": str, "params_prefix": str, "enabled": bool, "exclude_symbols": [str] (optional)}. tag_filter patterns match instrument_tags.tag values (prefix match, trailing * stripped). signal_type maps to a module in src/intelligence/regime_signals/. params_prefix is the APR namespace for that signal''s thresholds. Groups are checked in order (order is never load-bearing); symbols matching more than one enabled group raise AmbiguousRegimeGroupError (fail loud), UNLESS the symbol is named in the matched group''s exclude_symbols list -- a small, explicit, documented carve-out for genuine dual-categorical-membership symbols (migration 306), not a silent precedence rule. Symbols matching no enabled group are OMITTED from regime-stratified IC this run (pooled IC still covers them) with a loud startup warning -- never silently defaulted to "equity". exclude_symbols only affects this single-membership routing (ic_engine.py); cross_sectional_regime_model.py''s peer-averaging has no such constraint and ignores it.', '2026-07-12 22:50:16.119721+00');
INSERT INTO public.config_schema VALUES ('alpha.hmm_volatility.n_components', 'int', '3', 2, 3, NULL, false, 1, '[rca_analysis] Phase 172: both K=2 and K=3 cleared the null-arm block-reliability control per 171-FINAL-VERDICT section 3; K=3 preserved the calm/elevated/turbulent framing per section 5. Todo 478 (2026-10-02): at 1d every K=3 arm plateaus at 0.39 labeled (a state strands at zero occupation); K=2 labels 0.997 and passed the stage-2 intraday non-regression gate, so the seed moves to 2. Changing relabels the family; first consumer is the 186-26 rebuild. Not an ML learning target.', '2026-08-09 10:48:53.545033+00');
INSERT INTO public.config_schema VALUES ('alpha.hmm_volatility.covariance_type', 'str', 'full', NULL, NULL, NULL, false, 1, '[rca_analysis] Phase 172: GaussianHMM covariance_type for the volatility-only regime HMM (2 observation dimensions: realized_vol, vol_of_vol) per 171-FINAL-VERDICT.md section 5''s recommended model specification. Not an ML learning target.', '2026-08-09 10:48:53.545033+00');
INSERT INTO public.config_schema VALUES ('feature.rsi_velocity.window', 'int', '14', 2, 200, NULL, false, 1, '[conventional] Bar-lag window for the first-difference-then-z-score construction behind rsi_velocity_fast/mid/slow. Seeded to match feature.vol_velocity.window''s live value (14), same precedent as feature.momentum_velocity.window. Todo 320. ML learning target: yes.', '2026-08-15 15:39:09.580606+00');
INSERT INTO public.config_schema VALUES ('feature.ofi_velocity.window', 'int', '14', 2, 200, NULL, false, 1, '[conventional] Bar-lag window for ofi_z_velocity. Separate key from feature.rsi_velocity.window per naming-system.md section 7 (semantically distinct family). Todo 320. ML learning target: yes.', '2026-08-15 15:39:09.580606+00');
INSERT INTO public.config_schema VALUES ('feature.cvd_velocity.window', 'int', '14', 2, 200, NULL, false, 1, '[conventional] Bar-lag window for cvd_slope_z_velocity. Separate key from feature.ofi_velocity.window per naming-system.md section 7 (semantically distinct family). Todo 320. ML learning target: yes.', '2026-08-15 15:39:09.580606+00');
INSERT INTO public.config_schema VALUES ('feature.volume_velocity.window', 'int', '14', 2, 200, NULL, false, 1, '[conventional] Bar-lag window for volume_z_velocity. Separate key from feature.cvd_velocity.window per naming-system.md section 7 (semantically distinct family). Todo 320. ML learning target: yes.', '2026-08-15 15:39:09.580606+00');
INSERT INTO public.config_schema VALUES ('infra.backfill.ohlcv_insert_batch_size', 'int', NULL, NULL, NULL, NULL, false, 1, '[initial_estimate] Row batch size for market_data_ohlcv multi-row VALUES INSERT in scripts/infrastructure/backfill/infrastructure_run_historical_pipeline.py (store_bars). Pure infrastructure throughput knob -- output is invariant to this value. Not an ML learning target.', '2026-08-12 18:25:43.696371+00');
INSERT INTO public.config_schema VALUES ('infra.backfill.gap_cluster_max_days', 'int', NULL, NULL, NULL, NULL, false, 1, '[initial_estimate] Proximity threshold (days) for cluster_gap_ranges() in scripts/infrastructure/backfill/infrastructure_run_historical_pipeline.py -- gap ranges separated by more than this many days of already-present data get their own IBKR fetch request instead of being coalesced into one request that re-spans already-complete history. Pure infrastructure IBKR-budget knob -- output correctness is invariant to this value, only fetch efficiency varies. Not an ML learning target.', '2026-08-12 18:25:43.696371+00');
INSERT INTO public.config_schema VALUES ('infra.compressed_hypertable_write_session.statement_timeout_ms', 'int', NULL, NULL, NULL, NULL, false, 1, '[rca_analysis] statement_timeout (milliseconds) applied for the duration of compressed_hypertable_write_session / async_compressed_hypertable_write_session (services/_batch_utils.py), overriding the role/database default (30min) that is tuned for interactive/API queries, not this function''s own long batch decompress/ write/recompress+VACUUM sequence. Restored to the connection''s prior value on exit. Not an ML learning target -- pure infrastructure timeout knob, output is invariant to this value (only whether the batch completes at all, or fails with more wall-clock margin, varies).', '2026-08-14 03:27:34.976123+00');
INSERT INTO public.config_schema VALUES ('infra.compressed_hypertable_write_session.idle_session_timeout_ms', 'int', NULL, NULL, NULL, NULL, false, 1, '[rca_analysis] idle_session_timeout AND idle_in_transaction_session_timeout (milliseconds, same value applied to both) applied for the duration of compressed_hypertable_write_session / async_compressed_hypertable_write_session (services/_batch_utils.py), overriding the role/database default (1h) that is tuned for interactive/API connections, not this function''s own long batch decompress/[caller work]/recompress+VACUUM sequence where the middle step''s duration is caller-determined and can leave this connection idle for an arbitrary time. Restored to the connection''s prior value on exit. Not an ML learning target -- pure infrastructure timeout knob, output is invariant to this value (only whether the batch completes at all, or is killed for sitting idle, varies).', '2026-08-15 13:48:14.184526+00');
INSERT INTO public.config_schema VALUES ('alpha.forward_returns.gap_multiplier', 'float', NULL, NULL, NULL, NULL, false, 1, '[conventional] has_gap_before_entry floor -- the elapsed time between the signal bar (T) and the entry bar (T+1 open) must exceed this many multiples of the timeframe''s nominal bar interval (tf_to_seconds()) before being flagged as an anomalous gap. Guards against 1-bar noise/rounding false positives. Not an ML learning target.', '2026-08-17 00:29:08.828936+00');
INSERT INTO public.config_schema VALUES ('alpha.forward_returns.gap_max_seconds', 'int', NULL, NULL, NULL, NULL, false, 1, '[initial_estimate] has_gap_before_entry ceiling (seconds) -- elapsed time between signal bar and entry bar must stay under this to be flagged. Default (14400s = 4h) is calibrated for equity/ETF RTH sessions only (confirmed all 231 corpus symbols are asset_class=equity as of 2026-08-16) -- excludes normal overnight (~17.5h+) and weekend closures. NOT yet safe for futures/fx symbols (short daily maintenance breaks would be misflagged); needs asset-class-aware widening before a mixed-asset-class run can trust this column, per todo 334. Not an ML learning target.', '2026-08-17 00:29:08.828936+00');
INSERT INTO public.config_schema VALUES ('infra.alpha_publisher.chunk_size', 'int', '50000', 1, 500000, NULL, false, 1, '[initial_estimate] Row batch size for alpha_events INSERT + Kafka publish in services/alpha_publisher.py (_flush_chunk). Pure infrastructure throughput/memory knob -- output is invariant to this value; only wall-clock and peak RSS change. Seeded at the pre-migration hardcoded default. Not an ML learning target.', '2026-08-23 12:18:39.527349+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.earnings_season_conditioned', 'bool', 'true', NULL, NULL, NULL, false, 1, '[user_preference] Run-level switch gating an additional IC stratification pass conditioned on earnings_season_flag. Cost scales with cross-sectional cell count -- disable to skip the extra pass entirely. Todo 353, Phase 176. Not an ML learning target.', '2026-09-23 11:06:07.402256+00');
INSERT INTO public.config_schema VALUES ('alpha.hmm_volatility.vol_window', 'int', '20', 5, 500, NULL, false, 1, '[rca_analysis] Phase 172: realized-vol rolling-std window for the volatility-only regime HMM, the axis''s ORDERING column (column 0 of the 2-column observation). Todo 478 (2026-10-02): at 1d the 250-day window leaves the column nearly constant inside a segment (98.2% skip); preregistered stage-1 sweep picked 60, stage-2 intraday non-regression PASS. Changing relabels the family; first consumer is the 186-26 rebuild. Not an ML learning target.', '2026-08-09 10:48:53.545033+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.broadcast_variance_threshold', 'float', '1e-9', 0, 1, NULL, false, 1, '[initial_estimate] Per-bar_ts cross-symbol max-minus-min tolerance below which a feature is considered symbol-invariant (broadcast) rather than idiosyncratic. Picked as "smaller than any float32 rounding difference," never benchmarked. Shared by TWO readers, both affected by any change to this value: the offline classifier scripts/ops/alpha/ops_broadcast_feature_audit.py (uses it to CLASSIFY features into concept_registry.metadata->>''broadcast''), and -- after Phase 173 Plan 04 lands -- the compute-time invariance assertion in services/ic_engine.py::_compute_one_broadcast_cell (uses it to ASSERT the same classification still holds, crashing rather than silently computing on drifted data if it does not). Loosening this key affects both classification and the compute-time crash guard. Not an ML learning target.', '2026-08-25 16:03:24.889233+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.broadcast_max_bars_per_day.5m', 'int', '78', 1, 200, NULL, false, 1, '[conventional] Max observed 5m bars per NYSE trading day (390-minute cash session / 5), used by _compute_one_symbol_broadcast_cell (todo 354) to derive the per-scale day_stride so a day-decimated broadcast-feature observation''s forward-return window cannot overlap a later kept observation''s window for a scale whose lookahead spans more than one trading day. Cross-checked against 2 years of real SPY feature_vectors data (exact match). Not an ML learning target.', '2026-08-26 13:04:03.15882+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.broadcast_max_bars_per_day.15m', 'int', '26', 1, 100, NULL, false, 1, '[conventional] Max observed 15m bars per NYSE trading day (390/15). See .5m sibling key''s description for full rationale -- same mechanism, same provenance, cross-checked against real SPY data (exact match). Not an ML learning target.', '2026-08-26 13:04:03.15882+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.broadcast_max_bars_per_day.1h', 'int', '7', 1, 30, NULL, false, 1, '[conventional] Max observed 1h bars per NYSE trading day (390/60=6.5, rounded up to 7 so the day_stride guard is never tighter than the true observed max). See .5m sibling key''s description for full rationale -- this is the tf where the guard actually changes behavior (slow/extended scales'' lookahead_bars exceed bars-per-day). Not an ML learning target.', '2026-08-26 13:04:03.15882+00');
INSERT INTO public.config_schema VALUES ('alpha.regime.cross_sectional.min_hold_bars', 'int', '3', 1, 20, NULL, false, 1, '[initial_estimate] Minimum consecutive bars a new threshold-bucketed tier label must persist before cross_sectional_regime_model.py confirms the transition, applied independently to each tier dimension before combining into the final regime_label. Prevents single-bar flips when a signal oscillates around a tier boundary -- market_regimes had zero transition guard before this (todo 005), unlike regime_writer.py''s per-symbol HMM path which already has the identical protection via feature.hmm.min_hold_bars (migration 176/179, same default value 3, same provenance -- not independently calibrated for this signal family). Introduces at most min_hold_bars of lag on genuine transitions. Changing this value moves market_regimes labels corpus-wide on the next batch run -- same blast-radius class as an HMM_RANDOM_STATE change; requires a full market_regimes relabel + ic_engine recompute to take effect. Not an ML learning target.', '2026-08-27 11:15:13.430752+00');
INSERT INTO public.config_schema VALUES ('infra.ic.max_unrouted_symbols', 'int', NULL, NULL, NULL, NULL, false, 1, 'Hard ceiling on active instruments unmatched by any enabled regime group tag_filter; ic_engine raises at startup when exceeded (default 0 = any unrouted instrument fails the run). Added todo 280 step 3 after the unrouted-symbols warning fired on 120 symbols unnoticed for a month. [user_preference]', '2026-09-03 23:52:02.394277+00');
INSERT INTO public.config_schema VALUES ('alpha.regime.groups.signal_tag_filter', 'json', NULL, NULL, NULL, NULL, false, 1, 'Optional per-group list resolving PEER (signal-input) symbols, preferred over tag_filter by cross_sectional_regime_model; routing to measurement always uses tag_filter. Lets a group measure a wider symbol set than feeds its regime signal. [user_preference]', '2026-09-03 23:52:02.394277+00');
INSERT INTO public.config_schema VALUES ('alpha.universe.stratified_sample_random_state', 'int', '42', 0, NULL, NULL, false, 1, '[user_preference] Phase 174 (D-02): RNG seed for the market-cap-stratified random draw from the Russell 3000 population. Changing this value invalidates the reproducibility of any sample already drawn with the old value -- re-running the sourcing script with a different seed draws a different, non-comparable sample. Not an ML learning target.', '2026-09-15 15:13:50.472641+00');
INSERT INTO public.config_schema VALUES ('alpha.universe.cap_bucket_count', 'int', '10', 2, 50, NULL, false, 1, '[initial_estimate] Phase 174 (D-02): number of equal-population market-cap strata (deciles at the default) pandas.qcut() bins the addressable population into for the stratified draw. Changing this value changes the sample''s composition (which names are eligible to be drawn together within a stratum). Not an ML learning target.', '2026-09-15 15:13:50.472641+00');
INSERT INTO public.config_schema VALUES ('alpha.universe.target_sample_size', 'int', '0', 0, NULL, NULL, false, 1, '[initial_estimate] Phase 174 (D-01): number of symbols the stratified sampler draws in one run. 0 means UNSET -- the sourcing script fails loud naming this key rather than drawing an arbitrarily-sized sample. D-01 forbids locking a target count before the ic_engine memory fix''s actually-supported scale is measured (Plan 11); this key stays 0 until that measurement sets it for real. Not an ML learning target.', '2026-09-15 15:13:50.472641+00');
INSERT INTO public.config_schema VALUES ('alpha.research.screen_alpha', 'float', '0.05', 0, 1, NULL, false, 1, '[user_preference] One-sided family alpha of the book screen before division by M (evidence framework E15). A change needs a methodology-change-ledger entry (docs/plans/methodology-change-ledger.md). Not an ML learning target.', '2026-09-25 15:13:18.762236+00');
INSERT INTO public.config_schema VALUES ('infra.research_runner.workers', 'int', '8', 1, NULL, NULL, false, 1, '[initial_estimate] Worker processes for the research runner''s shift null and power replicates. Throughput only; results do not depend on it. Matches infra.ic_engine.workers. Not an ML learning target.', '2026-09-25 15:13:18.762236+00');
INSERT INTO public.config_schema VALUES ('alpha.universe.pilot_sample_size', 'int', '40', 30, 50, NULL, false, 1, '[initial_estimate] Phase 174 D-10: size of the down-cap pre-registered pilot gate draw (distinct from alpha.universe.target_sample_size, which stays 0/unset per D-01 until Plan 11 measures the ic_engine scale-up result -- overloading one key for both purposes would make the D-01 crash-loud guard unreachable during the pilot). D-10''s decision text specifies roughly 30-50 symbols for this pilot cohort. Not an ML learning target.', '2026-09-16 13:30:27.151961+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.max_cell_rows', 'int', '1200000', 100000, 150000000, NULL, false, 1, '[rca_analysis] Crash-loud row-count ceiling for a single IC compute cell (symbol|POOLED, tf, regime). A cell above this raises CellTooLargeError rather than silently routing to an alternate algorithm -- see the 2026-07-18 OOM incident (5m/low_bull cross-sectional cell, ~599K observations, ~20.5GB anon-rss). Sized ~2x that largest known cell. Not an ML learning target.', '2026-07-23 02:44:11.017651+00');
INSERT INTO public.config_schema VALUES ('alpha.tag_calibrator.materiality.min_partial_loading', 'float', '0.35', 0, 1, NULL, false, 1, '[initial_estimate] Minimum absolute partial_loading (OLS beta after control-set orthogonalization) required to pass the Pass 4 materiality gate. Proposed by Codex; NOT re-derived against this corpus''s actual partial-loading distribution. See docs/foundation/apr-calibration-backlog.md.', '2026-09-23 09:25:13.077853+00');
INSERT INTO public.config_schema VALUES ('alpha.tag_calibrator.materiality.min_partial_loading_ci_low', 'float', '0.20', 0, 1, NULL, false, 1, '[initial_estimate] Minimum lower-CI bound on partial_loading (R-05, Codex''s lower-CI gate) required to pass the Pass 4 materiality gate. Proposed by Codex; NOT re-derived against this corpus''s actual partial-loading distribution. See docs/foundation/apr-calibration-backlog.md.', '2026-09-23 09:25:13.077853+00');
INSERT INTO public.config_schema VALUES ('alpha.tag_calibrator.materiality.min_incremental_r2', 'float', '0.05', 0, 1, NULL, false, 1, '[initial_estimate] Minimum incremental_r2 (explanatory power beyond the control set alone) required to pass the Pass 4 materiality gate. Proposed by Codex; NOT re-derived against this corpus''s actual partial-loading distribution. See docs/foundation/apr-calibration-backlog.md.', '2026-09-23 09:25:13.077853+00');
INSERT INTO public.config_schema VALUES ('alpha.tag_calibrator.materiality.min_sample_n', 'int', '756', 60, 5000, NULL, false, 1, '[initial_estimate] Minimum materiality_sample_n (Pass 4''s own post-control-alignment observation count) required before a (symbol, tag) partial loading is measured at all. Proposed by Codex; NOT re-derived against this corpus''s actual partial-loading distribution. See docs/foundation/apr-calibration-backlog.md.', '2026-09-23 09:25:13.077853+00');
INSERT INTO public.config_schema VALUES ('alpha.tag_calibrator.materiality.sign_stability_window_days', 'int', '252', 60, 1260, NULL, false, 1, '[initial_estimate] Length in trading days of each rolling window used for the D-06 sign-stability measurement. Proposed by Codex; NOT re-derived against this corpus''s actual partial-loading distribution. See docs/foundation/apr-calibration-backlog.md.', '2026-09-23 09:25:13.077853+00');
INSERT INTO public.config_schema VALUES ('alpha.tag_calibrator.materiality.sign_stability_window_count', 'int', '4', 2, 12, NULL, false, 1, '[initial_estimate] Number of rolling sign_stability_window_days windows evaluated for sign stability (sign_stable_windows_total). Proposed by Codex; NOT re-derived against this corpus''s actual partial-loading distribution. See docs/foundation/apr-calibration-backlog.md.', '2026-09-23 09:25:13.077853+00');
INSERT INTO public.config_schema VALUES ('alpha.tag_calibrator.materiality.min_sign_stable_windows', 'int', '3', 1, 12, NULL, false, 1, '[initial_estimate] Minimum sign_stable_windows (out of sign_stability_window_count) required to pass the Pass 4 materiality gate. Proposed by Codex; NOT re-derived against this corpus''s actual partial-loading distribution. See docs/foundation/apr-calibration-backlog.md.', '2026-09-23 09:25:13.077853+00');
INSERT INTO public.config_schema VALUES ('alpha.tag_calibrator.materiality.null_arm_alpha', 'float', '0.05', 0.001, 0.25, NULL, false, 1, '[initial_estimate] BH-FDR alpha applied to the D-06 circular-shift null-arm p-vector (null_arm_p_value -> null_arm_bh_p), mirroring the project''s standing alpha.tag_calibrator.fdr_alpha=0.05 convention. Proposed by Codex; NOT re-derived against this corpus''s actual partial-loading distribution. See docs/foundation/apr-calibration-backlog.md.', '2026-09-23 09:25:13.077853+00');
INSERT INTO public.config_schema VALUES ('alpha.tag_calibrator.materiality.null_arm_draws', 'int', '1000', 100, 10000, NULL, false, 1, '[initial_estimate] Monte-Carlo draw count for the D-06 circular-shift null-arm control. A cost/resolution knob -- the floor of 100 means the smallest resolvable p-value is 1/101. Proposed by Codex; NOT re-derived against this corpus''s actual partial-loading distribution. See docs/foundation/apr-calibration-backlog.md.', '2026-09-23 09:25:13.077853+00');
INSERT INTO public.config_schema VALUES ('alpha.tag_calibrator.materiality.null_arm_seed', 'int', '42', 0, 2147483647, NULL, false, 1, '[conventional] Base seed mixed with a per-(symbol, tag) hash to derive each pair''s D-06 circular-shift null generator. 42 is this project''s standing default RNG seed (HMM_RANDOM_STATE), not an uncalibrated statistical estimate. WARNING: changing this value invalidates every previously computed null_arm_p_value/null_arm_bh_p in instrument_tags. Exists so an operator can test seed sensitivity or force re-randomization without a code edit. Not routed to docs/foundation/apr-calibration-backlog.md -- not a gate-shaped threshold awaiting corpus calibration.', '2026-09-23 09:25:13.077853+00');
INSERT INTO public.config_schema VALUES ('alpha.tag_calibrator.materiality.control_factor_series', 'json', '["SPY","TLT","HYG-IEF","UUP"]', NULL, NULL, NULL, false, 1, '[initial_estimate] R-03: the orthogonalization control set used to compute partial_loading/incremental_r2. Four legs only, no DBC commodity leg: SPY (broad equity), TLT (rates), HYG-IEF (credit), UUP (dollar). No commodity-broad leg is wired today because commodity_broad has measurement_type=''definitional'' with no factor_series; DBC is the pre-identified candidate to append here (an APR edit, not a code change or a tag_vocabulary mutation) if the shadow diagnostic surfaces commodity-cycle confounding.', '2026-09-23 09:25:13.077853+00');
INSERT INTO public.config_schema VALUES ('feature.earnings_season.start_days', 'int', '14', 0, 91, NULL, false, 1, '[initial_estimate] Start of the earnings-season window, in calendar days since the most recent quarter end. Seeded from D-04''s corrected proxy test (1.90x in-season/off-season ratio, p=5.05e-05, 67% of symbols). Changing this value invalidates every previously computed earnings_season_flag value and requires a feature recompute. Todo 353, Phase 176. ML learning target: yes.', '2026-09-23 11:06:07.402256+00');
INSERT INTO public.config_schema VALUES ('feature.earnings_season.end_days', 'int', '42', 1, 91, NULL, false, 1, '[initial_estimate] End of the earnings-season window, in calendar days since the most recent quarter end. Seeded from D-04''s corrected proxy test (1.90x in-season/off-season ratio, p=5.05e-05, 67% of symbols). Changing this value invalidates every previously computed earnings_season_flag value and requires a feature recompute. Todo 353, Phase 176. ML learning target: yes.', '2026-09-23 11:06:07.402256+00');
INSERT INTO public.config_schema VALUES ('alpha.ic.bootstrap_numba_kernel', 'bool', 'false', NULL, NULL, NULL, false, 1, '[rca_analysis] Todo 385 lever 2: run the ic_engine circular block bootstrap through the counting-rank numba kernel instead of the scipy resample loop (~20x on SPY 1h at equal threads). COMPUTATIONAL: part of the cell fingerprint, so changing it invalidates every cell (the kernel accumulates in float64, the scipy path in float32). Not an ML learning target.', '2026-09-23 22:40:48.570498+00');
INSERT INTO public.config_schema VALUES ('infra.backfill.empty_history_reverify_days', 'int', '90', 1, 3650, NULL, false, 1, '[initial_estimate] Migration 354: age after which an ohlcv_empty_history row stops suppressing requests, so the backfill asks the provider again whether the history now exists (providers do fill history in: IBKR''s ODFL daily history starts 2024-05-07 despite a 1991 head timestamp). Lower = faster pickup of newly served history, more requests re-spent on confirmed-empty ranges. Not an ML learning target.', '2026-09-23 23:22:55.780165+00');
INSERT INTO public.config_schema VALUES ('infra.compressed_hypertable_write_session.disk_path', 'str', NULL, NULL, NULL, NULL, false, 1, '[rca_analysis] A path on the filesystem that holds the TimescaleDB volume, read with shutil.disk_usage by the compressed write session''s pre-flight (the Docker volume dir itself is not readable by the service user; "/" is the same filesystem on this host). Not an ML learning target.', '2026-09-25 03:03:26.440151+00');
INSERT INTO public.config_schema VALUES ('infra.compressed_hypertable_write_session.min_free_after_fraction', 'float', NULL, NULL, NULL, NULL, false, 1, '[initial_estimate] Fraction of that filesystem that must remain free after the session decompresses every compressed chunk (conservative peak: full uncompressed size). The session raises before touching anything otherwise. Same role as ic_engine''s scratch_min_free_after_fraction. Not an ML learning target.', '2026-09-25 03:03:26.440151+00');
INSERT INTO public.config_schema VALUES ('alpha.research.vintage_id', 'str', 'vintage_1', NULL, NULL, NULL, false, 1, '[user_preference] Research vintage the screen budget is charged against. Vintage 1 = data before alpha.validation.oos_start (2025-12-24). A change needs a methodology-change-ledger entry (docs/plans/methodology-change-ledger.md). Not an ML learning target.', '2026-09-25 15:13:18.762236+00');
INSERT INTO public.config_schema VALUES ('alpha.research.budget_m', 'int', '30', 1, NULL, NULL, false, 1, '[user_preference] M, the number of book versions that may be screen-tested on the vintage (evidence framework E15); the bar is screen_alpha / M. A change needs a methodology-change-ledger entry (docs/plans/methodology-change-ledger.md). Not an ML learning target.', '2026-09-25 15:13:18.762236+00');
INSERT INTO public.config_schema VALUES ('infra.dividend_event.lookback_years', 'int', '1', 1, 30, NULL, false, 1, '[initial_estimate] Years of IBKR daily history a dividend_event_writer run requests per symbol (Yahoo always returns full history). A full IBKR history is a one-off --years run; the coverage check refuses to extend a symbol whose new window does not reach its stored coverage. Not an ML learning target.', '2026-09-26 13:15:14.963842+00');
INSERT INTO public.config_schema VALUES ('alpha.universe.r2k_sample_size', 'int', '100', 1, 2000, NULL, false, 1, '[user_preference] Size of the down-cap Russell 2000 stratified draw (universe_expansion_holdings_draw.py): cap-decile-stratified sample from IWM (Russell 2000) holdings, excluding symbols already in instruments. Chosen by the owner 2026-09-26. Changing it after a draw has been onboarded does not re-draw; a new draw is a new onboarding run. Not an ML learning target.', '2026-09-26 02:10:46.113227+00');
INSERT INTO public.config_schema VALUES ('infra.ibkr.venue_fallback.exchanges', 'json', '["NYSE", "ARCA", "ISLAND", "AMEX", "BATS"]', NULL, NULL, NULL, false, 1, '[rca_analysis] IBKR routing codes asked for a stock''s history before its first SMART bar (todo 433); the one with the most volume is kept. ISLAND is Nasdaq. The contract''s current primary is skipped. Not an ML learning target.', '2026-09-26 12:26:15.499569+00');
INSERT INTO public.config_schema VALUES ('infra.ibkr.venue_fallback.timeframes', 'json', '["1d"]', NULL, NULL, NULL, false, 1, '[initial_estimate] Timeframes whose pre-venue-move history is recovered (todo 433). Intraday history depth is capped by IBKR regardless, so recovery there is untested. Not an ML learning target.', '2026-09-26 12:26:15.499569+00');
INSERT INTO public.config_schema VALUES ('infra.ibkr.venue_fallback.min_gap_days', 'int', '7', 1, 3650, NULL, false, 1, '[conventional] Minimum days between the requested start and the first SMART bar before former venues are asked; smaller gaps are weekends and holidays, not venue moves. Not an ML learning target.', '2026-09-26 12:26:15.499569+00');
INSERT INTO public.config_schema VALUES ('infra.ibkr.venue_fallback.store_bars', 'bool', 'false', NULL, NULL, NULL, false, 1, '[user_preference] Operator switch. false: former venues only verify (history found there blocks an empty-history record and is logged). true: the highest-volume venue''s bars are stored as source ibkr_venue. Set true only after the D3 listing-venue validation study passes. Not an ML learning target.', '2026-09-26 12:26:15.499569+00');
INSERT INTO public.config_schema VALUES ('infra.ibkr.rate_limit_max_requests_by_tf', 'json', '{}', NULL, NULL, NULL, false, 1, '[rca_analysis] Per-timeframe historical-request limits per infra.ibkr.rate_limit_window_sec, each with its own window, e.g. {"1d": 150}. Unlisted timeframes use infra.ibkr.rate_limit_max_requests. Set only from the rate-limit probe (--rate-ceilings), with a margin below the highest clean ceiling. Not an ML learning target.', '2026-09-26 12:26:15.552023+00');
INSERT INTO public.config_schema VALUES ('threshold.dividend_event.noise_margin', 'float', '1.25', 1, NULL, NULL, false, 1, '[initial_estimate] Multiple of the worst-case rounding bound (0.005/close on each of two days; ADJUSTED_LAST is quoted to the cent) that a TRADES/ADJUSTED_LAST ratio step must exceed to count as a dividend. 1.0 is the exact bound; the margin absorbs closing-print differences between the two series. Changing it changes which events are derived. Not an ML learning target.', '2026-09-26 13:15:14.963842+00');
INSERT INTO public.config_schema VALUES ('threshold.dividend_event.ex_date_match_days', 'int', '5', 1, 30, NULL, false, 1, '[initial_estimate] Two sources reporting unmatched ex-dates this many calendar days apart or fewer are treated as one dividend on disagreeing dates, which fails the dividend_event_writer run (the reconciled view would count it twice). Shorter than the shortest regular distribution interval (weekly payers aside). Not an ML learning target.', '2026-09-26 13:15:14.963842+00');
INSERT INTO public.config_schema VALUES ('threshold.dividend_event.source_yield_rel_tolerance', 'float', '0.10', 0, 1, NULL, false, 1, '[initial_estimate] Relative difference between the two sources'' yields on the same ex-date above which the event is logged as a disagreement. 2026-09-26 measurement: medians 0.3% to 1.2%, maximum 5.3% on SPY, HYG and TLT. Diagnostic only. Not an ML learning target.', '2026-09-26 13:15:14.963842+00');
INSERT INTO public.config_schema VALUES ('threshold.dividend_event.stable_sessions', 'int', '3', 1, 10, NULL, false, 1, '[rca_analysis] Rows on each side of an IBKR ADJUSTED_LAST / TRADES ratio step over which the ratio must stay within the rounding bound for the step to count as a dividend (the series in lockstep). 3 keeps weekly payers (5 sessions apart) detectable. Changing it changes which IBKR events are derived. Not an ML learning target.', '2026-09-26 18:07:32.986266+00');
INSERT INTO public.config_schema VALUES ('infra.bar_campaign.client_ids', 'json', '[47, 48, 49]', NULL, NULL, NULL, false, 1, '[initial_estimate] IBKR client ids reserved for phase 185 bar campaigns (D-30). 46 and 40 belong to the todo 449 chain and 45 to the nightly backfill, so campaign code must not take them; ids must stay <= 50 (the provider ceiling). Changing this only affects runs started afterwards. Not an ML learning target.', '2026-09-27 23:00:23.86507+00');
INSERT INTO public.config_schema VALUES ('infra.ibkr_history_lease.nightly_wait_minutes', 'int', '60', 1, 1440, NULL, false, 1, '[initial_estimate] Minutes the nightly 1d backfill waits for the IBKR history-stream lease before failing loudly (D-29). A bulk-tier holder yields within one (symbol, tf) unit, about 18 minutes worst case, so 60 minutes covers a full yield cycle. Not an ML learning target.', '2026-09-27 23:00:23.86507+00');
INSERT INTO public.config_schema VALUES ('infra.ibkr_history_lease.priority_wait_minutes', 'int', '240', 1, 1440, NULL, false, 1, '[initial_estimate] Minutes a priority-tier campaign waits for the IBKR history-stream lease before failing loudly (D-29). Longer than the nightly wait because a priority campaign is rarer and restarts are more expensive. Not an ML learning target.', '2026-09-27 23:00:23.86507+00');
INSERT INTO public.config_schema VALUES ('infra.ohlcv_observation.copy_batch_rows', 'int', '50000', 1000, 1000000, NULL, false, 1, '[initial_estimate] Buffer size in rows at which the ohlcv_observation COPY writer flushes D1 requests and observations (phase 185 plan 02). Bounded to keep the in-memory buffer small against long campaigns. Not an ML learning target.', '2026-09-27 23:00:23.86507+00');
INSERT INTO public.config_schema VALUES ('threshold.bar_scrub.jump_sigma', 'float', '8.0', 1, 1000, NULL, false, 1, '[initial_estimate] Abs log return over rolling sigma above which vol_scaled_jump flags a bar. Informational (not quarantining) until validated. Not an ML learning target.', '2026-09-28 01:05:42.002846+00');
INSERT INTO public.config_schema VALUES ('threshold.bar_scrub.jump_vol_window', 'int', '60', 5, 10000, NULL, false, 1, '[conventional] Rolling window (bars) for the vol_scaled_jump sigma estimate. Not an ML learning target.', '2026-09-28 01:05:42.002846+00');
INSERT INTO public.config_schema VALUES ('threshold.bar_scrub.stale_run_min', 'int', '5', 2, 1000, NULL, false, 1, '[initial_estimate] Consecutive identical-OHLC traded bars (volume > 0) before stale_print flags a run. Informational until validated. Not an ML learning target.', '2026-09-28 01:05:42.002846+00');
INSERT INTO public.config_schema VALUES ('threshold.bar_scrub.volume_outlier_mad', 'float', '10.0', 1, 1000, NULL, false, 1, '[initial_estimate] Robust z of log volume above which volume_outlier flags a bar. Informational until validated. Not an ML learning target.', '2026-09-28 01:05:42.002846+00');
INSERT INTO public.config_schema VALUES ('threshold.bar_scrub.volume_window', 'int', '60', 5, 10000, NULL, false, 1, '[conventional] Rolling window (bars) for the volume_outlier MAD estimate. Not an ML learning target.', '2026-09-28 01:05:42.002846+00');
INSERT INTO public.config_schema VALUES ('threshold.bar_scrub.corroboration_max_clearable_ratio', 'float', '2.5', 0.1, 100, NULL, false, 1, '[rca_analysis] D-11 ceiling: corroboration can clear at most this multiple of the magnitude threshold (inverse of the 2010-05-06 60% break rule); below alpha.quant.price_sanity.magnitude_threshold 10.0 so no CONFIRMED_CORRUPT print is ever cleared. Not an ML learning target.', '2026-09-28 01:05:42.002846+00');
INSERT INTO public.config_schema VALUES ('threshold.bar_scrub.view_disagreement_rel', 'float', '0.02', 0, 1, NULL, false, 1, '[initial_estimate] Relative price disagreement above which view_disagreement flags a bar (TRADES vs ADJUSTED_LAST pairing). Not an ML learning target.', '2026-09-28 01:05:42.002846+00');
INSERT INTO public.config_schema VALUES ('threshold.bar_scrub.quarantine_rules', 'json', '["ohlc_invariant","non_positive_price","price_sanity","split_seam","legacy_price_sanity_status"]', NULL, NULL, NULL, false, 1, '[user_preference] Rules whose flags quarantine a bar (D-09 flag-never-delete). jump/stale/volume rules stay informational until validated (Pitfall 5). Not an ML learning target.', '2026-09-28 01:05:42.002846+00');
INSERT INTO public.config_schema VALUES ('infra.bar_scrub.symbol_batch', 'int', '50', 1, 10000, NULL, false, 1, '[initial_estimate] Symbols per batch in the D2a scrub pass (plan 10). Bounded to keep per-batch memory small. Not an ML learning target.', '2026-09-28 01:05:42.002846+00');
INSERT INTO public.config_schema VALUES ('alpha.survivorship.delisting_return.nasdaq', 'float', '-0.55', -1, 0, NULL, false, 1, '[conventional] Performance-delisting return for Nasdaq names, Shumway and Warther 1999 (The delisting bias in CRSP''s Nasdaq data and its implications for the size effect). Enters labels.py delisting_sensitivity and the D0 survivorship bound reported beside the statistic (D-04). Not an ML learning target.', '2026-09-28 02:30:41.680446+00');
INSERT INTO public.config_schema VALUES ('alpha.survivorship.delisting_return.nyse_amex', 'float', '-0.30', -1, 0, NULL, false, 1, '[ASSUMED] Performance-delisting return for NYSE/AMEX names, Shumway 1997 (The delisting bias in CRSP data); [ASSUMED] number not confirmed against the paper. Enters labels.py delisting_sensitivity and the D0 survivorship bound (D-04). Not an ML learning target.', '2026-09-28 02:30:41.680446+00');
INSERT INTO public.config_schema VALUES ('alpha.survivorship.hazard.nasdaq_annual', 'float', '0.056', 0, 1, NULL, false, 1, '[conventional] Annual probability a Nasdaq name delists for performance reasons, from the Shumway survivorship literature. Divided by trading_days_per_year for the per-session hazard in labels.py delisting_sensitivity. Not an ML learning target.', '2026-09-28 02:30:41.680446+00');
INSERT INTO public.config_schema VALUES ('alpha.survivorship.hazard.nyse_amex_annual', 'float', '0.012', 0, 1, NULL, false, 1, '[conventional] Annual probability a NYSE/AMEX name delists for performance reasons, from the Shumway survivorship literature. Divided by trading_days_per_year for the per-session hazard in labels.py delisting_sensitivity. Not an ML learning target.', '2026-09-28 02:30:41.680446+00');
INSERT INTO public.config_schema VALUES ('alpha.survivorship.haircut.small_cap_annual', 'float', '0.015', 0, 1, NULL, false, 1, '[ASSUMED] Annual survivorship haircut for small-cap names, spec range 1-2 percent a year; [ASSUMED] midpoint, not a measured value. Scaled by the attempt''s small-cap share into the D0 survivorship bound (labels.py survivorship_bound, D-04). Not an ML learning target.', '2026-09-28 02:30:41.680446+00');
INSERT INTO public.config_schema VALUES ('alpha.survivorship.trading_days_per_year', 'int', '252', 200, 260, NULL, false, 1, '[conventional] Trading sessions per year; converts the annual delisting hazards to per-session and annualizes the D0 survivorship bound (labels.py SurvivorshipRule). Not an ML learning target.', '2026-09-28 02:30:41.680446+00');
INSERT INTO public.config_schema VALUES ('infra.bar_derivation.grid_symbol_batch', 'int', '10', 1, 10000, NULL, false, 1, '[initial_estimate] Symbols per progress chunk in the D2b grid stage (phase 185 plan 11). Bounded to keep the per-symbol 5m arrays and the chunk progress log cadence small. Not an ML learning target.', '2026-09-28 05:46:37.67036+00');
INSERT INTO public.config_schema VALUES ('infra.bar_derivation.grid_write_method', 'text', 'segment_delete_copy', NULL, NULL, NULL, false, 1, '[rca_analysis] Write method the grid stage uses to replace a (symbol, 15m/1h) segment: segment_delete_copy (archive, verify, DELETE, reinsert in one transaction) per 185-01 measurements c/d; native upsert measured worse on disk and is not implemented. Changing this key does not switch code paths; it records the measured choice. Not an ML learning target.', '2026-09-28 05:46:37.67036+00');
INSERT INTO public.config_schema VALUES ('infra.bulk_load.statement_timeout_ms', 'int', '14400000', 60000, NULL, NULL, false, 1, '[conventional] statement_timeout for one bulk_load() data transaction (COPY plus the completed-provenance update). Same value as the write session key infra.compressed_hypertable_write_session.statement_timeout_ms (migration 314): one load unit must survive a multiday rebuild''s slowest partition. Not an ML learning target.', '2026-09-28 11:17:37.496078+00');
INSERT INTO public.config_schema VALUES ('infra.bulk_load.compress_on_complete', 'bool', 'true', NULL, NULL, NULL, false, 1, '[initial_estimate] Operator switch: when false, bulk_load() skips the per-chunk compress_completed_chunks step so a pilot can measure the uncompressed working set before committing to it. Not an ML learning target.', '2026-09-28 11:17:37.496078+00');
INSERT INTO public.config_schema VALUES ('feature.coverage.min_symbol_fraction', 'float', '0.95', 0, 1, NULL, false, 1, '[initial_estimate] Minimum share of symbols with rows at a tf that must carry at least one non-NULL value of a feature over the span. One definition shared by feature_lifecycle (186-09), todo 421 coverage check and todo 435 S0 floor (src/intelligence/statistics/feature_coverage.py). Not an ML learning target.', '2026-09-29 16:38:58.093612+00');
INSERT INTO public.config_schema VALUES ('feature.lifecycle.lookback_days', 'int', '90', 1, NULL, NULL, false, 1, '[initial_estimate] Span ending at the evaluated window over which feature_lifecycle measures data quality. Not an ML learning target.', '2026-09-29 16:38:58.093612+00');
INSERT INTO public.config_schema VALUES ('feature.lifecycle.demotion_min_consecutive', 'int', '2', 1, NULL, NULL, false, 1, '[conventional] Trailing failing windows before a feature moves active to shadow_only (data_quality_fail). Not an ML learning target.', '2026-09-29 16:38:58.093612+00');
INSERT INTO public.config_schema VALUES ('feature.lifecycle.recovery_min_passes', 'int', '1', 1, NULL, NULL, false, 1, '[initial_estimate] Trailing passing windows before a feature moves shadow_only to active (data_quality_restored). Not an ML learning target.', '2026-09-29 16:38:58.093612+00');
INSERT INTO public.config_schema VALUES ('infra.feature_lifecycle.max_concurrent_tfs', 'int', '3', 1, 10, NULL, false, 1, '[initial_estimate] Timeframes feature_lifecycle measures at once; each holds one pool connection for aggregate queries over the feature_vectors hypertable (BaseBatch pool has ten). Cannot move a verdict. Not an ML learning target.', '2026-09-29 23:42:07.923793+00');
INSERT INTO public.config_schema VALUES ('infra.bar_derivation.venue_bars_1d', 'bool', 'false', NULL, NULL, NULL, false, 1, '[user_preference] D-17 gate: when true the D2 rule may use listing-venue 1d bars. Set only by the D3 venue validation study verdict for 1d (ops_venue_study.py --apply-verdict); false leaves venue bars stored and unused. Not an ML learning target.', '2026-09-30 00:55:15.188033+00');
INSERT INTO public.config_schema VALUES ('infra.bar_derivation.venue_bars_intraday', 'bool', 'false', NULL, NULL, NULL, false, 1, '[user_preference] D-17 gate: when true intraday features may read recovered listing-venue intraday bars. Set only by the D3 venue validation study verdict for 5m (ops_venue_study.py --apply-verdict); false leaves them unused (D-18). Not an ML learning target.', '2026-09-30 00:55:15.188033+00');
INSERT INTO public.config_schema VALUES ('infra.hmm.rolling_block_rows', 'int', '16384', 1, NULL, NULL, false, 1, '[initial_estimate] rows per block in the HMM obs-builder rolling reductions; bounds transient memory, does not change output; not an ML target', '2026-09-30 05:19:53.183726+00');
INSERT INTO public.config_schema VALUES ('alpha.hmm.covariance_ridge', 'float', '0.000001', 0, 0.01, NULL, false, 1, '[conventional] ridge added (times the identity) to each full-covariance matrix before the Cholesky factorization in the HMM log-emission; guards near-singular covariances on flat timeframes. Carried over from the pre-186 regime writer. Not an ML learning target. CHANGING THIS INVALIDATES every stored regime label (full re-run of regime_writer and the rebuild).', '2026-09-30 06:08:23.236357+00');
INSERT INTO public.config_schema VALUES ('alpha.hmm.momentum_vol_floor', 'float', '0.00000001', 1e-12, 0.01, NULL, false, 1, '[conventional] floor on realized volatility in the trend HMM momentum observation (sum of log returns / max(realized_vol, floor)); avoids division by zero on flat series. Carried over from the pre-186 regime writer. Not an ML learning target. CHANGING THIS INVALIDATES every stored trend regime label (full re-run of regime_writer and the rebuild).', '2026-09-30 06:08:23.236357+00');
INSERT INTO public.config_schema VALUES ('threshold.seam.rel_tol', 'float', '0.002', 1e-05, 0.5, NULL, false, 1, '[initial_estimate] Relative tolerance of the stored/fresh close ratio inside one seam run, and the distance from 1 below which a day is on one scale (split-seam audit, plan 15). Not an ML learning target.', '2026-09-30 10:10:44.362681+00');
INSERT INTO public.config_schema VALUES ('threshold.seam.min_run', 'int', '5', 1, 1000, NULL, false, 1, '[initial_estimate] Fewest consecutive days a constant-ratio run needs to count as a seam (split-seam audit, plan 15). Not an ML learning target.', '2026-09-30 10:10:44.362681+00');
INSERT INTO public.config_schema VALUES ('threshold.seam.ratio_snap_tol', 'float', '0.01', 1e-05, 0.5, NULL, false, 1, '[initial_estimate] Largest gap between a seam factor and the nearest rational p/q (p, q <= 50) for the seam to be recorded as a split; otherwise it stays unexplained (plan 15). Not an ML learning target.', '2026-09-30 10:10:44.362681+00');
INSERT INTO public.config_schema VALUES ('infra.bar_campaign.bootstrap_years', 'int', '20', 1, 40, NULL, false, 1, '[conventional] Years of TRADES and ADJUSTED_LAST 1d history the D1 bootstrap fetch requests back from now, one request per series per name (RESEARCH, plan 15). Not an ML learning target.', '2026-09-30 10:10:44.362681+00');
INSERT INTO public.config_schema VALUES ('alpha.ic_measure.degenerate_std', 'float', '1e-8', 0, NULL, NULL, false, 1, '[conventional] Std below which a feature column is degenerate and its IC is NaN (services/ic_engine.py literal at 2348, the same value). Not an ML learning target.', '2026-09-30 12:15:19.050943+00');
INSERT INTO public.config_schema VALUES ('alpha.ic_measure.monitor_degenerate_std', 'float', '1e-10', 0, NULL, NULL, false, 1, '[initial_estimate] Std floor of a member''s window-IC spread below which its IC Sharpe is 0.0 instead of a ratio to a near-zero denominator (the value the monitor used as a literal). A different quantity from alpha.ic_measure.degenerate_std. Not an ML learning target.', '2026-09-30 12:15:19.050943+00');
INSERT INTO public.config_schema VALUES ('alpha.ic_measure.horizons', 'json', '{"5m":[6,12,39],"15m":[2,5,10],"1h":[1,2],"1d":[1,2,5,10]}', NULL, NULL, NULL, false, 1, '[initial_estimate] Per-tf in-session horizon lists (bars) the IC writer measures: the stored feature_ic_scores lookaheads that fit inside one session (1h 20 and 60 cross sessions and are dropped per D-18). The first entry of a tf is its proposer horizon (CI and FDR columns are filled there). Not an ML learning target.', '2026-09-30 12:15:19.050943+00');
INSERT INTO public.config_schema VALUES ('alpha.ic_measure.monitor_window_sessions', 'int', '63', 1, NULL, NULL, false, 1, '[conventional] Whole sessions per monitoring window (one quarter of sessions). Not an ML learning target.', '2026-09-30 12:15:19.050943+00');
INSERT INTO public.config_schema VALUES ('infra.ic_measure.symbol_chunk_size', 'int', '50', 1, NULL, NULL, false, 1, '[initial_estimate] Symbols per S0 panel chunk in the IC writer; a memory knob that never enters a value. Not an ML learning target.', '2026-09-30 12:15:19.050943+00');
INSERT INTO public.config_schema VALUES ('infra.ic_measure.fetch_chunk_rows', 'int', '200000', 1000, NULL, NULL, false, 1, '[initial_estimate] Rows per server-side cursor fetch when the IC writer streams feature_vectors into arrays; bounds the Python tuple overhead per round trip, never enters a value. Not an ML learning target.', '2026-09-30 15:10:13.126495+00');
INSERT INTO public.config_schema VALUES ('infra.ic_measure.bootstrap_threads', 'int', '12', 1, NULL, NULL, false, 1, '[initial_estimate] Numba threads of the IC writer''s block bootstrap kernel (one cell at a time). Throughput only: each resample row is independent, so the count never changes a value and never enters a unit identity. Not an ML learning target.', '2026-09-30 18:18:45.287629+00');
INSERT INTO public.config_schema VALUES ('infra.ic_measure.bootstrap_chunk_resamples', 'int', '250', 1, NULL, NULL, false, 1, '[initial_estimate] Bootstrap resamples drawn and run per slice in the IC writer; bounds the block-start matrix (resamples x blocks int64) to one slice, about 100 MB at 500,000 rows. Never changes a value (batched draws equal sequential draws) and never enters a unit identity. Not an ML learning target.', '2026-09-30 18:18:45.287629+00');
INSERT INTO public.config_schema VALUES ('alpha.regime.cross_sectional.max_orphan_delete_fraction', 'float', '0.01', 0, 1, NULL, false, 1, '[initial_estimate] Largest fraction of a (regime_group, tf) market_regimes history that cross_sectional_regime_model.py may delete as orphans (stored timestamps the run no longer produces) without --accept-orphan-delete; guards against a partial bar fetch silently deleting labeled history. Not an ML learning target.', '2026-10-01 01:41:30.60247+00');
INSERT INTO public.config_schema VALUES ('alpha.regime.cross_sectional.max_changed_fraction', 'float', '0.05', 0, 1, NULL, false, 1, '[initial_estimate] Largest fraction of a (regime_group, tf) market_regimes history that cross_sectional_regime_model.py may rewrite as changed rows (same timestamp, different label or probability vector) without a reviewed --accept-changed=N override; guards against a broken peer set relabeling a history without removing a timestamp. Not an ML learning target.', '2026-10-01 03:20:22.937738+00');
INSERT INTO public.config_schema VALUES ('infra.regime_cross_sectional.feature_vectors_probe_timeout_ms', 'int', '600000', 1000, NULL, NULL, false, 1, '[initial_estimate] statement_timeout in milliseconds of the cross_sectional_regime_model.py --dry-run feature_vectors join probe (a DISTINCT bar_ts scan, about 4 s per tf). Not an ML learning target.', '2026-10-01 03:20:22.937738+00');
INSERT INTO public.config_schema VALUES ('alpha.regime.coverage_auditor.max_permanent_exceptions', 'int', '5', 0, 50, NULL, false, 1, '[initial_estimate] Largest number of permanent_degenerate entries the regime coverage auditor accepts in known_exceptions; a list above it fails the job, so a permanent suppression cannot accumulate unnoticed. Not an ML learning target.', '2026-10-01 03:22:46.290061+00');
INSERT INTO public.config_schema VALUES ('alpha.regime.coverage_auditor.known_exceptions', 'json', '[]', NULL, NULL, NULL, false, 1, '[user_preference] JSON list of {symbol, kind, reason, clears_on, expires, todo}: symbols whose stored regime is all NULL for a diagnosed reason; regime_coverage_auditor stays green on these. kind rebuild_pending needs expires (ISO date; after it the entry fails the job again) and clears_on (the trigger that ends it); kind permanent_degenerate needs a reason and no expiry, is capped by alpha.regime.coverage_auditor.max_permanent_exceptions and is listed in the log every run. A listed symbol that is no longer a gap warns; a malformed list fails the job. Operator-visible switch, not an ML learning target.', '2026-10-01 02:48:23.01146+00');
INSERT INTO public.config_schema VALUES ('infra.economic_series.sources', 'json', '[{"source": "fred", "series_id": "BAMLH0A0HYM2", "revision": "none", "consumer": "credit_spread_screen"}, {"source": "fred", "series_id": "BAMLC0A0CM", "revision": "none", "consumer": "credit_spread_screen"}, {"source": "fred", "series_id": "BAMLH0A3HYC", "revision": "none", "consumer": "credit_spread_screen"}, {"source": "fred", "series_id": "BAMLC0A4CBBB", "revision": "none", "consumer": "credit_spread_screen"}, {"source": "fred", "series_id": "BAA10Y", "revision": "none", "consumer": "credit_spread_screen"}, {"source": "fred", "series_id": "DGS10", "revision": "none", "consumer": "rate_level_screen"}, {"source": "fred", "series_id": "DGS2", "revision": "none", "consumer": "rate_level_screen"}, {"source": "fred", "series_id": "T10Y2Y", "revision": "none", "consumer": "rate_level_screen"}, {"source": "fred", "series_id": "DFII10", "revision": "none", "consumer": "rate_level_screen"}, {"source": "fred", "series_id": "THREEFYTP10", "revision": "model_revised", "consumer": "rate_level_screen"}, {"source": "nyfed", "series_id": "SOFR", "revision": "revised", "consumer": "funding_stress_screen"}, {"source": "nyfed", "series_id": "TGCR", "revision": "revised", "consumer": "funding_stress_screen"}, {"source": "nyfed", "series_id": "BGCR", "revision": "revised", "consumer": "funding_stress_screen"}, {"source": "nyfed", "series_id": "SOFRAI", "revision": "revised", "consumer": "funding_stress_screen"}, {"source": "nyfed", "series_id": "EFFR", "revision": "revised", "consumer": "funding_stress_screen"}, {"source": "nyfed", "series_id": "OBFR", "revision": "revised", "consumer": "funding_stress_screen"}]', NULL, NULL, NULL, false, 1, '[initial_estimate] Series economic_series_writer.py fetches (todo 480): list of {source, series_id, revision, consumer}; source is fred (series_id is the FRED id), yahoo (an index ticker, context only, never a tradeable price) or nyfed (series_id is the NY Fed rate type, expanded to one series per published field, named NYFED_<type>_<field>). revision is none (observed rate, never revised), revised (the publisher flags revisions) or model_revised (history is as-revised, not point in time). Every entry names a consumer. Behavioral list, not an ML learning target.', '2026-10-01 12:41:01.206131+00');
INSERT INTO public.config_schema VALUES ('infra.feature_factory.rebuild_symbols_per_chunk', 'int', '25', 1, 200, NULL, false, 1, '[initial_estimate] Symbols per (chunk, tf, time range) unit of the feature_vectors_v2 rebuild (services/backfill_feature_factory.py run_rebuild_stage). A smaller chunk loses less work to a kill and bounds one unit''s spool; a larger one amortizes the per-unit provenance and COPY overhead. Changing it renames every unit, so a resumed run recomputes. Not an ML learning target.', '2026-10-01 14:04:32.569292+00');
INSERT INTO public.config_schema VALUES ('infra.economic_series.http_timeout_sec', 'int', '60', 5, 600, NULL, false, 1, '[initial_estimate] Per-request HTTP timeout for the FRED and NY Fed fetches in economic_series_writer.py (a full-history response is a few MB). Not an ML learning target.', '2026-10-01 12:42:52.447471+00');
INSERT INTO public.config_schema VALUES ('infra.economic_series.assumed_lag_business_days', 'int', '1', 0, 10, NULL, false, 1, '[conventional] Business days between an observation date and its publication; available_at for a series'' first-fetch history (availability_basis assumed_lag) is the end of that business day. FRED daily series and NY Fed reference rates post the next business day; exchange holidays are not modeled. Not an ML learning target.', '2026-10-01 12:46:13.902853+00');
INSERT INTO public.config_schema VALUES ('infra.economic_series.fetch_concurrency', 'int', '4', 1, 32, NULL, false, 1, '[initial_estimate] Source fetches economic_series_writer.py runs at once (one shared HTTP client). Writes stay serial whatever this is. FRED allows about 120 requests a minute. Not an ML learning target.', '2026-10-01 13:34:06.901286+00');
INSERT INTO public.config_schema VALUES ('infra.economic_series.http_max_attempts', 'int', '3', 1, 10, NULL, false, 1, '[conventional] Attempts per request on a transport error or a 5xx response (exponential backoff with jitter, src/core/retry_utils.py); a 4xx is never retried. Not an ML learning target.', '2026-10-01 13:34:06.901286+00');
INSERT INTO public.config_schema VALUES ('infra.feature_factory.max_unit_rows', 'int', '1000000', 10000, NULL, NULL, false, 1, '[conventional] Loud refusal bound on one rebuild unit''s row count (todo 339): a unit whose spooled rows exceed it raises before any write instead of exhausting disk or memory. One 25-symbol 5m year is about 0.5 million rows. Not an ML learning target.', '2026-10-01 14:04:32.569292+00');
INSERT INTO public.config_schema VALUES ('infra.feature_factory.rebuild_block_rows', 'int', '10000', 1000, 1000000, NULL, false, 1, '[initial_estimate] Rows per memory block of the feature_vectors_v2 rebuild (services/backfill_feature_factory.py): one server-cursor fetch round trip and one spool write block, bounding the worker''s in-memory row buffer (todo 339). Not an ML learning target.', '2026-10-01 18:35:42.061112+00');
INSERT INTO public.config_schema VALUES ('infra.bar_derivation.daily_symbol_batch', 'int', '25', NULL, NULL, NULL, false, 1, '[initial_estimate] Symbols per chunk in the bar_derivation daily stage loop. Not an ML learning target.', '2026-10-02 10:22:42.860218+00');
INSERT INTO public.config_schema VALUES ('infra.bar_derivation.daily_write_method', 'text', 'upsert', NULL, NULL, NULL, false, 1, '[rca_analysis] 1d write method: native upsert per 185-01 measurement b (65.5k rows/s); only differing or missing rows are written. Not an ML learning target.', '2026-10-02 10:22:42.860218+00');
INSERT INTO public.config_schema VALUES ('infra.ibkr.history_request_timeout', 'float', '900', 120, NULL, NULL, false, 1, '[initial_estimate] Per-queue-item stall bound in seconds: the fetcher cancels an item when no IBKR request has been answered for this long. It must exceed infra.ibkr.rate_limit_window_sec (600 s, the longest legitimate silent wait in the pre-emptive rate limiter) plus infra.ibkr.historical_request_timeout_sec (90 s per request); todo 488 suggested 300 s, which would cancel healthy items during a rate-limit sleep. Distinct from infra.ibkr.historical_request_timeout_sec, which bounds one reqHistoricalDataAsync call inside ibkr.py. Not an ML learning target.', '2026-10-02 15:58:55.782343+00');
INSERT INTO public.config_schema VALUES ('infra.ibkr.history_request_retries', 'int', '2', 0, 10, NULL, false, 1, '[initial_estimate] Reconnect-and-retry attempts for a stalled queue item before it is recorded as an error. Not an ML learning target.', '2026-10-02 15:58:55.782343+00');
INSERT INTO public.config_schema VALUES ('infra.backfill.max_consecutive_failures', 'int', '5', 1, NULL, NULL, false, 1, '[initial_estimate] A (symbol, timeframe) whose ohlcv_coverage.consecutive_failures exceeds this is excluded from the fetcher queue (replaces todo 484''s quarantine file); reset with the fetcher''s --reset-failures flag. Not an ML learning target.', '2026-10-02 15:58:55.782343+00');
INSERT INTO public.config_schema VALUES ('infra.backfill.max_staleness_days_before_preempt', 'int', '3', 1, NULL, NULL, false, 1, '[initial_estimate] Calendar days since a covered series'' latest bar beyond which it preempts backlog work. 3 lets a normal Friday-to-Monday weekend pass without preempting; a series missing about two sessions mid-week preempts. Not an ML learning target.', '2026-10-02 15:58:55.782343+00');
INSERT INTO public.config_schema VALUES ('infra.backfill.priority_tf_order', 'json', '["15m", "1h"]', NULL, NULL, NULL, false, 1, '[user_preference] Timeframes ranked ahead of the rest within a priority band (todo 449 owner decision: 15m/1h before 5m). Not an ML learning target.', '2026-10-02 15:58:55.782343+00');
INSERT INTO public.config_schema VALUES ('infra.backfill.default_scopes', 'json', '{"compute": ["1d", "1h", "15m", "5m"], "compute_1d": ["1d"], "backfill": ["1h", "15m"]}', NULL, NULL, NULL, false, 1, '[user_preference] The (eligibility dimension -> timeframes) union the fetcher queues when run without --dimension/--timeframes/--symbols. Mirrors today''s nightly legs (compute full stack, compute_1d-only at 1d) plus the todo 449 HTF campaign; 1m is dropped (todo 455); 5m for the backfill dimension stays out until todo 462 lands (today''s PAUSE_5M state) and is added by an APR edit, not code. Not an ML learning target.', '2026-10-02 15:58:55.782343+00');
INSERT INTO public.config_schema VALUES ('infra.backfill.run_budget_minutes', 'int', '240', 5, NULL, NULL, false, 1, '[initial_estimate] Wall-clock minutes after which a fetcher run stops taking new queue items; the timer''s next fire continues the queue. Not an ML learning target.', '2026-10-02 15:58:55.782343+00');
INSERT INTO public.config_schema VALUES ('infra.ibkr.inter_item_pause_s', 'float', '2.0', 0, NULL, NULL, false, 1, '[conventional] Pause in seconds between fetcher queue items, carried over from the inline asyncio.sleep(2) IBKR pacing pause between instruments in infrastructure_run_historical_pipeline.py (APR migrate-as-you-go). Not an ML learning target.', '2026-10-02 15:58:55.782343+00');
INSERT INTO public.config_schema VALUES ('alpha.hmm_volatility.vol_of_vol_window', 'int', '60', 5, 500, NULL, false, 1, '[rca_analysis] Phase 172: vol-of-vol rolling-std window for the volatility-only regime HMM; 171-FINAL-VERDICT section 6 found this column''s margin thin at wide windows. Todo 478 (2026-10-02): shortened 250 -> 60 with the vol_window change after the preregistered stage-1 verdict E and the stage-2 intraday non-regression PASS. Changing relabels the family; first consumer is the 186-26 rebuild. Not an ML learning target.', '2026-08-09 10:48:53.545033+00');
